INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0e6d77-03b8-486a-ba3b-9a59548f80bf', '七言 十四', '七言 十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["玄門玄理又玄玄，不死根元在汞鉛。","知是一般真箇術，調和六一也同天。","玉京山上羊兒鬧，金水河中石虎眠。","妙要能生覺本體，勤心到處自如然。"]', '["玄门玄理又玄玄，不死根元在汞鉛。","知是一般真箇術，調和六一也同天。","玉京山上羊兒鬧，金水河中石虎眠。","妙要能生覺本體，勤心到处自如然。"]', '诗', 'shi', '', NULL, '七言 十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3240f5e-a6f2-437a-8b76-5d65dd9915dc', '七言 十五', '七言 十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["公卿雖貴不曾酬，說著仙鄉便去遊。","爲討石肝逢蜃海，因尋甜雪過瀛州。","山川醉後壺中放，神鬼閑來匣裏收。","據見目前無箇識，不如杯酒混凡流。"]', '["公卿雖貴不曾酬，说著仙乡便去游。","爲討石肝逢蜃海，因尋甜雪過瀛州。","山川醉後壺中放，神鬼闲来匣裏收。","據见目前無箇識，不如杯酒混凡流。"]', '诗', 'shi', '', NULL, '七言 十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a3ad1e-1882-41c1-a190-397fa37e28fc', '七言 十六', '七言 十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["曾邀相訪到仙家，忽上崑崙宴月華。","玉女控攏蒼獬豸，山童提挈白蝦蟇。","時斟海內千年酒，慣摘壺中四序花。","今在人寰人不識，看看揮袖入煙霞。"]', '["曾邀相訪到仙家，忽上崑崙宴月华。","玉女控攏蒼獬豸，山童提挈白蝦蟇。","时斟海內千年酒，慣摘壺中四序花。","今在人寰人不識，看看揮袖入煙霞。"]', '诗', 'shi', '', NULL, '七言 十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d903fd-1ab9-4a78-b480-9ecd4050c148', '七言 十七', '七言 十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["火種丹田金自生，重重樓閣自分明。","三千功行百旬見，萬里蓬萊一日程。","羽化自應無鬼錄，玉都長是有仙名。","今朝得赴瑤池會，九節幢幡洞裏迎。"]', '["火種丹田金自生，重重楼閣自分明。","三千功行百旬见，万里蓬萊一日程。","羽化自應無鬼錄，玉都长是有仙名。","今朝得赴瑤池會，九節幢幡洞裏迎。"]', '诗', 'shi', '', NULL, '七言 十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26288a6-9c90-4c03-95a8-f12583554854', '七言 十八', '七言 十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["因看崔公入藥鏡，令人心地轉分明。","陽龍言向離宮出，陰虎還於坎位生。","二物會時爲道本，五方行盡得丹名。","修真道士如知此，定跨赤龍歸玉清。"]', '["因看崔公入藥镜，令人心地轉分明。","陽龙言向離宮出，陰虎還於坎位生。","二物會时爲道本，五方行尽得丹名。","修真道士如知此，定跨赤龙归玉清。"]', '诗', 'shi', '', NULL, '七言 十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de46be4-2704-4015-9fe7-62dbc78b5569', '七言 十九', '七言 十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["浮生不實爲輕忽，衲服深藏奇異骨。","非是塵中不染塵，焉得物外通無物。","共語難兮情兀兀，獨自行時輕拂拂。","一點刀圭五彩生，飛丹走入神仙窟。"]', '["浮生不實爲轻忽，衲服深藏奇異骨。","非是塵中不染塵，焉得物外通無物。","共語难兮情兀兀，独自行时轻拂拂。","一点刀圭五彩生，飞丹走入神仙窟。"]', '诗', 'shi', '', NULL, '七言 十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e11215-787b-4a4c-b25b-29ff7ecb8eb4', '七言 二十', '七言 二十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["莫怪愛吟天上詩，蓋緣吟得世間稀。","慣餐玉帝宮中飯，曾著蓬萊洞裏衣。","馬踏日輪紅露捲，鳳銜月角擘雲飛。","何時再控青絲轡，又掉金鞭入紫微。"]', '["莫怪愛吟天上诗，蓋緣吟得世间稀。","慣餐玉帝宮中飯，曾著蓬萊洞裏衣。","马踏日輪紅露捲，鳳銜月角擘云飞。","何时再控青絲轡，又掉金鞭入紫微。"]', '诗', 'shi', '', NULL, '七言 二十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feae9d70-d81d-4bb7-9f5f-47c4a88b993b', '七言 二十一', '七言 二十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["黃芽白雪兩飛金，行即高歌醉即吟。","日月暗扶君甲子，乾坤自與我知音。","精靈滅跡三清劍，風雨騰空一弄琴。","的當南遊歸甚處，莫交鶴去上天尋。"]', '["黄芽白雪兩飞金，行即高歌醉即吟。","日月暗扶君甲子，乾坤自與我知音。","精靈滅跡三清劍，风雨腾空一弄琴。","的當南游归甚处，莫交鹤去上天尋。"]', '诗', 'shi', '', NULL, '七言 二十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888938ce-d63c-4a7b-a06c-b97aac81b194', '七言 二十二', '七言 二十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["雲鬢雙明骨更輕，自言尋鶴到蓬瀛。","日論藥草皆知味，問著神仙自得名。","簪冷夜龍穿碧洞，枕寒晨虎臥銀城。","來春又擬攜筇去，爲憶軒轅海上行。"]', '["云鬢雙明骨更轻，自言尋鹤到蓬瀛。","日論藥草皆知味，问著神仙自得名。","簪冷夜龙穿碧洞，枕寒晨虎臥銀城。","来春又擬携筇去，爲憶軒轅海上行。"]', '诗', 'shi', '', NULL, '七言 二十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94566261-dd84-4388-a853-dc69df876a15', '七言 二十三', '七言 二十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["龍精龜眼兩相和，丈六男兒不奈何。","九盞水中煎赤子，一輪火內養黃婆。","月圓自覺離天網，功滿方知出地羅。","半醉好吞龍鳳髓，勸君休更認彌陀。"]', '["龙精龟眼兩相和，丈六男兒不奈何。","九盞水中煎赤子，一輪火內養黄婆。","月圓自覺離天網，功满方知出地羅。","半醉好吞龙鳳髓，勸君休更認彌陀。"]', '诗', 'shi', '', NULL, '七言 二十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f97c14-ebf7-4345-bf3e-0d7170bccc1a', '七言 二十四', '七言 二十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["強居此境絕知音，野景雖多不合吟。","詩句若喧卿相口，姓名還動帝王心。","道袍薜帶應慵挂，隱帽皮冠尚懶簪。","除此更無餘箇事，一壺村酒一張琴。"]', '["強居此境絕知音，野景雖多不合吟。","诗句若喧卿相口，姓名還动帝王心。","道袍薜带應慵挂，隐帽皮冠尚懶簪。","除此更無餘箇事，一壺村酒一張琴。"]', '诗', 'shi', '', NULL, '七言 二十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb1d05d7-59be-4335-9d24-2406998b7f5e', '七言 二十五', '七言 二十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["華陽山裏多芝田，華陽山叟復延年。","青松巖畔攀高幹，白雲堆裏飲飛泉。","不寒不熱神蕩蕩，東來西去氣綿綿。","三千功滿好歸去，休與時人說洞天。"]', '["华陽山裏多芝田，华陽山叟复延年。","青松巖畔攀高幹，白云堆裏饮飞泉。","不寒不熱神蕩蕩，东来西去氣綿綿。","三千功满好归去，休與时人说洞天。"]', '诗', 'shi', '', NULL, '七言 二十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f8a6c4-42ae-4212-a5aa-6a8196005b63', '七言 二十六', '七言 二十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天生不散自然心，成敗從來古與今。","得路應知能出世，迷途終是任埋沈。","身邊至藥堪攻煉，物外丹砂且細尋。","咫尺洞房仙景在，莫隨波浪沒光陰。"]', '["天生不散自然心，成敗從来古與今。","得路應知能出世，迷途終是任埋沈。","身邊至藥堪攻煉，物外丹砂且細尋。","咫尺洞房仙景在，莫隨波浪沒光陰。"]', '诗', 'shi', '', NULL, '七言 二十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad77054-667e-4c16-96f6-a871bf6917ed', '七言 二十七', '七言 二十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["自隱玄都不記春，幾回滄海變成塵。","玉京殿裏朝元始，金闕宮中拜老君。","悶即駕乘千歲鶴，閑來高臥九重雲。","我今學得長生法，未肯輕傳與世人。"]', '["自隐玄都不記春，幾回滄海变成塵。","玉京殿裏朝元始，金闕宮中拜老君。","悶即駕乘千歲鹤，闲来高臥九重云。","我今学得长生法，未肯轻傳與世人。"]', '诗', 'shi', '', NULL, '七言 二十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f6a47c7-bfde-4491-a162-262015dc36d7', '七言 二十八', '七言 二十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["北帝南辰掌內觀，潛通造化暗相傳。","金槌袖裏居元宅，玉戶星宮降上玄。","舉世盡皆尋此道，誰人空裏得玄關。","明明道在堪消息，日月灘頭去又還。"]', '["北帝南辰掌內观，潛通造化暗相傳。","金槌袖裏居元宅，玉戶星宮降上玄。","舉世尽皆尋此道，誰人空裏得玄关。","明明道在堪消息，日月灘头去又還。"]', '诗', 'shi', '', NULL, '七言 二十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47925956-2a65-48ea-88ef-c3fab4f687d4', '七言 二十九', '七言 二十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["日影元中合自然，奔雷走電入中原。","長驅赤馬居東殿，大啓朱門泛碧泉。","怒拔昆吾歌聖化，喜陪孤月賀新年。","方知此是生生物，得在仁人始受傳。"]', '["日影元中合自然，奔雷走電入中原。","长驱赤马居东殿，大啓朱门泛碧泉。","怒拔昆吾歌聖化，喜陪孤月賀新年。","方知此是生生物，得在仁人始受傳。"]', '诗', 'shi', '', NULL, '七言 二十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eff325c-3287-42c6-b1db-d20378f5d0ea', '七言 三十', '七言 三十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["六龍齊駕得昇乾，須覺潛通造化權。","真道每吟秋月澹，至言長運碧波寒。","晝乘白虎遊三島，夜頂金冠立古壇。","一載已成千歲藥，誰人將袖染塵寰。"]', '["六龙齊駕得昇乾，須覺潛通造化權。","真道每吟秋月澹，至言长運碧波寒。","晝乘白虎游三島，夜頂金冠立古壇。","一載已成千歲藥，誰人將袖染塵寰。"]', '诗', 'shi', '', NULL, '七言 三十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('775780da-f62e-4597-9904-45870207a2b1', '七言 三十一', '七言 三十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["五岳灘頭景象新，仁人方達杳冥身。","天綱運轉三元淨，地脈通來萬物生。","自曉谷神通此道，誰將理性欲修真。","明明說向中黃路，霹靂聲中自得神。"]', '["五岳灘头景象新，仁人方達杳冥身。","天綱運轉三元淨，地脈通来万物生。","自晓谷神通此道，誰將理性欲修真。","明明说向中黄路，霹靂声中自得神。"]', '诗', 'shi', '', NULL, '七言 三十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a53d12a-1020-4abf-851c-45a676b7912f', '七言 三十二', '七言 三十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["欲陪仙侶得身輕，飛過蓬萊徹上清。","朱頂鶴來雲外接，紫鱗魚向海中迎。","姮娥月桂花先吐，王母仙桃子漸成。","下瞰日輪天欲曉，定知人世久長生。"]', '["欲陪仙侶得身轻，飞過蓬萊徹上清。","朱頂鹤来云外接，紫鱗鱼向海中迎。","姮娥月桂花先吐，王母仙桃子漸成。","下瞰日輪天欲晓，定知人世久长生。"]', '诗', 'shi', '', NULL, '七言 三十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ba0c55-c67a-4a9c-989b-782bc8c0265a', '七言 三十三', '七言 三十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["四海皆忙幾箇閑，時人口內說塵緣。","知君有道來山上，何似無名住世間。","十二樓臺藏秘訣，五千言內隱玄關。","方知鼎貯神仙藥，乞取刀圭一粒看。"]', '["四海皆忙幾箇闲，时人口內说塵緣。","知君有道来山上，何似無名住世间。","十二楼台藏秘訣，五千言內隐玄关。","方知鼎貯神仙藥，乞取刀圭一粒看。"]', '诗', 'shi', '', NULL, '七言 三十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695b7657-e964-4392-9849-0955d1d235a0', '七言 三十四', '七言 三十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["割斷繁華掉却榮，便從初得是長生。","曾於錦水爲蟬蛻，又向蓬萊別姓名。","三住住來無否泰，一塵塵在世人情。","不知功滿歸何處，直跨虬龍上玉京。"]', '["割斷繁华掉却榮，便從初得是长生。","曾於錦水爲蟬蛻，又向蓬萊別姓名。","三住住来無否泰，一塵塵在世人情。","不知功满归何处，直跨虬龙上玉京。"]', '诗', 'shi', '', NULL, '七言 三十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfb5f4b-ae7c-403b-ae06-26cbe3ca6ea4', '七言 三十五', '七言 三十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["當年詩價滿皇都，掉臂西歸是丈夫。","萬頃白雲獨自有，一枝丹桂阿誰無。","閑尋渭曲漁翁引，醉上蓮峰道士扶。","他日與君重際會，竹溪茅舍夜相呼。"]', '["當年诗價满皇都，掉臂西归是丈夫。","万頃白云独自有，一枝丹桂阿誰無。","闲尋渭曲漁翁引，醉上蓮峰道士扶。","他日與君重際會，竹溪茅舍夜相呼。"]', '诗', 'shi', '', NULL, '七言 三十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935b0ad4-205f-4a4f-a7ed-6adcf5aa9ddd', '七言 三十六', '七言 三十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["金鎚灼灼舞天階，獨自騎龍去又來。","高臥白雲觀日窟，閑眠秋月擘天開。","離花片片乾坤產，坎蘂翻翻造化栽。","晚醉九巖回首望，北邙山下骨皚皚。"]', '["金鎚灼灼舞天階，独自騎龙去又来。","高臥白云观日窟，闲眠秋月擘天开。","離花片片乾坤產，坎蘂翻翻造化栽。","晚醉九巖回首望，北邙山下骨皚皚。"]', '诗', 'shi', '', NULL, '七言 三十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e1a280-20c9-42fd-9b09-559f4842f2c7', '七言 三十七', '七言 三十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["結交常與道情深，日日隨他出又沈。","若要自通雲外鶴，直須勤煉水中金。","丹成只恐乾坤窄，餌了寧憂疾患侵。","未去瑤臺猶混世，不妨杯酒喜閑吟。"]', '["結交常與道情深，日日隨他出又沈。","若要自通云外鹤，直須勤煉水中金。","丹成只恐乾坤窄，餌了寧憂疾患侵。","未去瑤台猶混世，不妨杯酒喜闲吟。"]', '诗', 'shi', '', NULL, '七言 三十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346c75a6-feae-4679-b6e7-5137568c074e', '七言 三十八', '七言 三十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["因攜琴劍下煙蘿，何幸今朝喜暫過。","貌相本來猶自可，針醫偏更効無多。","仙經已讀三千卷，古法曾持十二科。","些小道功如不信，金堦捨手試看麽。"]', '["因携琴劍下煙蘿，何幸今朝喜暫過。","貌相本来猶自可，針醫偏更効無多。","仙經已读三千卷，古法曾持十二科。","些小道功如不信，金堦捨手試看麽。"]', '诗', 'shi', '', NULL, '七言 三十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840c9e5c-285c-4f2f-8819-55d1ff28fca1', '七言 三十九', '七言 三十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["傾側華陽醉再三，騎[龍]遇晚下南巖。","眉因拍劍留星電，衣爲眠雲惹碧嵐。","金液變來成雨露，玉都歸去老松杉。","曾將鐵鏡照神鬼，霹靂搜尋火滿潭。"]', '["傾側华陽醉再三，騎[龙]遇晚下南巖。","眉因拍劍留星電，衣爲眠云惹碧嵐。","金液变来成雨露，玉都归去老松杉。","曾將鐵镜照神鬼，霹靂搜尋火满潭。"]', '诗', 'shi', '', NULL, '七言 三十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee5be2c-2069-4cf3-bcc1-3d087798f721', '七言 四十', '七言 四十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鐵鏡烹金火滿空，碧潭龍臥夕陽中。","麒麟意合乾坤地，獬豸機關日月東。","三尺劍橫雙水岸，五丁冠頂百神宮。","閑鋪羽服居仙窟，自著金蓮造化功。"]', '["鐵镜烹金火满空，碧潭龙臥夕陽中。","麒麟意合乾坤地，獬豸機关日月东。","三尺劍橫雙水岸，五丁冠頂百神宮。","闲鋪羽服居仙窟，自著金蓮造化功。"]', '诗', 'shi', '', NULL, '七言 四十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb2ae88-c39b-49bd-9cee-23734e5fa7a2', '七言 四十一', '七言 四十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["隨緣信業任浮沈，似水如雲一片心。","兩卷道經三尺劍，一條藜杖七弦琴。","壺中有藥逢人施，腹內新詩遇客吟。","一嚼永添千載壽，一丸丹點一斤金。"]', '["隨緣信業任浮沈，似水如云一片心。","兩卷道經三尺劍，一條藜杖七弦琴。","壺中有藥逢人施，腹內新诗遇客吟。","一嚼永添千載壽，一丸丹点一斤金。"]', '诗', 'shi', '', NULL, '七言 四十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a6e270-49cb-4274-b56f-5d0f91410a09', '七言 四十二', '七言 四十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["琴劍酒碁龍鶴虎，逍遙落托永無憂。","閑騎白鹿遊三島，悶駕青牛看十洲。","碧洞遠觀明月上，青山高隱綵雲流。","時人若要還如此，名利浮華即便休。"]', '["琴劍酒碁龙鹤虎，逍遙落托永無憂。","闲騎白鹿游三島，悶駕青牛看十洲。","碧洞远观明月上，青山高隐綵云流。","时人若要還如此，名利浮华即便休。"]', '诗', 'shi', '', NULL, '七言 四十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827b37f1-2001-45a8-9c16-7676b3e77d8f', '七言 四十三', '七言 四十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["紫極宮中我自知，親磨神劍劍還飛。","先差玉子開南殿，後遣青龍入紫微。","九鼎黃芽棲瑞鳳，一軀仙骨養靈芝。","蓬萊不是凡人處，只怕愚人泄世機。"]', '["紫極宮中我自知，親磨神劍劍還飞。","先差玉子开南殿，後遣青龙入紫微。","九鼎黄芽棲瑞鳳，一軀仙骨養靈芝。","蓬萊不是凡人处，只怕愚人泄世機。"]', '诗', 'shi', '', NULL, '七言 四十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba2f35f-46aa-424e-8920-2054664c3fa0', '七言 四十四', '七言 四十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["向身方始出埃塵，造化功夫只在人。","早使亢龍拋地網，豈知白虎出天真。","綿綿有路誰留我，默默忘言自合神。","擊劍夜深歸甚處，披星帶月折麒麟。"]', '["向身方始出埃塵，造化功夫只在人。","早使亢龙拋地網，豈知白虎出天真。","綿綿有路誰留我，默默忘言自合神。","擊劍夜深归甚处，披星带月折麒麟。"]', '诗', 'shi', '', NULL, '七言 四十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f76aa2e-94f9-4973-9322-086103d820d6', '七言 四十五', '七言 四十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["春盡閑閑過落花，一回舞劍一吁嗟。","常憂白日光陰促，每恨青天道路賒。","本志不求名與利，元心只慕水兼霞。","世間萬種浮沈事，達理誰能似我家。"]', '["春尽闲闲過落花，一回舞劍一吁嗟。","常憂白日光陰促，每恨青天道路賒。","本志不求名與利，元心只慕水兼霞。","世间万種浮沈事，達理誰能似我家。"]', '诗', 'shi', '', NULL, '七言 四十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('900e758e-18e6-416a-b333-256d87c6ba48', '七言 四十六', '七言 四十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["日爲和解月呼丹，華夏諸侯肉眼看。","仁義異如胡越異，世情難似泰衡難。","八仙煉後鍾神異，四海磨成照膽寒。","笑指不平千萬萬，騎龍撫劍九重關。"]', '["日爲和解月呼丹，华夏諸侯肉眼看。","仁義異如胡越異，世情难似泰衡难。","八仙煉後鍾神異，四海磨成照膽寒。","笑指不平千万万，騎龙撫劍九重关。"]', '诗', 'shi', '', NULL, '七言 四十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc62ca2-1f57-4203-941a-ed872bc8fe96', '七言 四十七', '七言 四十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["別來洛汭六東風，醉眼吟情慵不慵。","擺撼乾坤金劍吼，烹煎日月玉爐紅。","杖搖楚甸三千里，鶴翥秦煙幾萬重。","爲報晉成仙子道，再期春色會稽峰。"]', '["別来洛汭六东风，醉眼吟情慵不慵。","擺撼乾坤金劍吼，烹煎日月玉爐紅。","杖搖楚甸三千里，鹤翥秦煙幾万重。","爲報晉成仙子道，再期春色會稽峰。"]', '诗', 'shi', '', NULL, '七言 四十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ee7b7c-1d19-43e9-8d8e-5693880a8357', '七言 四十八', '七言 四十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["髮頭滴血眼如鐶，吐氣雲生怒世間。","爭耐不平千古事，須期一訣蕩兇頑。","蛟龍斬處翻滄海，暴虎除時拔遠山。","爲滅世情兼負義，劍光腥染點痕斑。"]', '["髮头滴血眼如鐶，吐氣云生怒世间。","爭耐不平千古事，須期一訣蕩兇頑。","蛟龙斬处翻滄海，暴虎除时拔远山。","爲滅世情兼負義，劍光腥染点痕斑。"]', '诗', 'shi', '', NULL, '七言 四十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2dd721-41eb-438f-8bd9-82b6093e4f39', '七言 四十九', '七言 四十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["雨雪霏霏天已暮，金鍾滿勸撫焦桐。","詩吟席上未移刻，劍舞筵前疾似風。","何事行杯當午夜，忽然怒目便騰空。","不知誰是虧忠孝，攜箇人頭入坐中。"]', '["雨雪霏霏天已暮，金鍾满勸撫焦桐。","诗吟席上未移刻，劍舞筵前疾似风。","何事行杯當午夜，忽然怒目便腾空。","不知誰是虧忠孝，携箇人头入坐中。"]', '诗', 'shi', '', NULL, '七言 四十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4abbaeef-6949-40c6-aafe-ff4a1eba0acb', '七言 五十', '七言 五十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["未煉還丹且煉心，丹成方覺道元深。","每留客有錢酤酒，誰信君無藥點金。","洞裏風雷歸掌握，壺中日月在胸襟。","神仙事業人難會，養性長生自意吟。"]', '["未煉還丹且煉心，丹成方覺道元深。","每留客有錢酤酒，誰信君無藥点金。","洞裏风雷归掌握，壺中日月在胸襟。","神仙事業人难會，養性长生自意吟。"]', '诗', 'shi', '', NULL, '七言 五十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4667adf-b79e-48d0-b7f4-bbbeba682a68', '七言 五十一', '七言 五十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鐵牛耕地種金錢，刻石時童把貫穿。","一粒粟中藏世界，二升鐺內煮山川。","白頭老子眉垂地，碧眼胡兒手指天。","若向此中玄會得，此玄玄外更無玄。"]', '["鐵牛耕地種金錢，刻石时童把貫穿。","一粒粟中藏世界，二升鐺內煮山川。","白头老子眉垂地，碧眼胡兒手指天。","若向此中玄會得，此玄玄外更無玄。"]', '诗', 'shi', '', NULL, '七言 五十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e73fbc5a-9488-463b-a38f-7dd6960eac8d', '七言 五十二', '七言 五十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["箕星昴宿下長天，凡景寧教不愕然。","龍出水來鱗甲就，鶴沖天氣羽毛全。","塵中教化千人眼，世上人知爾雅篇。","自是凡流福命薄，忍教微妙略輕傳。"]', '["箕星昴宿下长天，凡景寧教不愕然。","龙出水来鱗甲就，鹤沖天氣羽毛全。","塵中教化千人眼，世上人知爾雅篇。","自是凡流福命薄，忍教微妙略轻傳。"]', '诗', 'shi', '', NULL, '七言 五十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dae3e32-3b0f-43a4-a1cc-337db465ac18', '七言 五十三', '七言 五十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["閑來掉臂入天門，拂袂徐徐撮綵雲。","無語下窺黃谷子，破顏平揖紫霞君。","擬登瑤殿參金母，回訪瀛洲看日輪。","恰值嫦娥排宴會，瑤漿新熟味氤氳。"]', '["闲来掉臂入天门，拂袂徐徐撮綵云。","無語下窺黄谷子，破顏平揖紫霞君。","擬登瑤殿參金母，回訪瀛洲看日輪。","恰值嫦娥排宴會，瑤漿新熟味氤氳。"]', '诗', 'shi', '', NULL, '七言 五十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50516b0c-630d-480d-a178-4b24826628d0', '七言 五十四', '七言 五十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["曾隨劉阮醉桃源，未省人間欠酒錢。","一領布裘權且當，九天回日却歸還。","鳳茸襖子非爲貴，狐白裘裳欲比難。","只此世間無價寶，不憑火裏試燒看。"]', '["曾隨劉阮醉桃源，未省人间欠酒錢。","一領布裘權且當，九天回日却归還。","鳳茸襖子非爲貴，狐白裘裳欲比难。","只此世间無價寶，不憑火裏試燒看。"]', '诗', 'shi', '', NULL, '七言 五十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d34cf1-9811-4a27-bfba-89da080dc3d0', '七言 五十五', '七言 五十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["因思往事却成憨，曾讀仙經第十三。","武氏死時應室女，陳王沒後是童男。","兩輪日月從他載，九箇山河一擔擔。","盡日無人話消息，一壺春酒且醺酣。"]', '["因思往事却成憨，曾读仙經第十三。","武氏死时應室女，陳王沒後是童男。","兩輪日月從他載，九箇山河一擔擔。","尽日無人話消息，一壺春酒且醺酣。"]', '诗', 'shi', '', NULL, '七言 五十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a6e6fc-9b1b-4eb8-8d7c-9115e4c27c71', '七言 五十六', '七言 五十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["垂袖騰騰傲世塵，葫蘆攜却數遊巡。","利名身外終非道，龍虎門前辨取真。","一覺夢魂朝紫府，數年蹤跡隱埃塵。","華陰市內纔相見，不是尋常賣藥人。"]', '["垂袖腾腾傲世塵，葫蘆携却數游巡。","利名身外終非道，龙虎门前辨取真。","一覺梦魂朝紫府，數年蹤跡隐埃塵。","华陰市內纔相见，不是尋常賣藥人。"]', '诗', 'shi', '', NULL, '七言 五十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aba50c4-315a-4928-8eaa-5f8aed25e79c', '七言 五十七', '七言 五十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["萬卷仙經三尺琴，劉安聞說是知音。","杖頭春色一壺酒，爐內丹砂萬點金。","悶裏醉眠三路口，閑來遊釣洞庭心。","相逢相遇人誰識，只恐沖天沒處尋。"]', '["万卷仙經三尺琴，劉安闻说是知音。","杖头春色一壺酒，爐內丹砂万点金。","悶裏醉眠三路口，闲来游釣洞庭心。","相逢相遇人誰識，只恐沖天沒处尋。"]', '诗', 'shi', '', NULL, '七言 五十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b0c36a-8e7a-4fb2-9d73-25eaca6d9c5f', '七言 五十八', '七言 五十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["曾戰蚩尤玉座前，六龍高駕振鳴鑾。","如來車後隨金鼓，黃帝旂傍戴鐵冠。","醉捋黑鬚三島黯，怒抽霜劍十洲寒。","軒轅世代橫行後，直隱深巖久覓難。"]', '["曾戰蚩尤玉座前，六龙高駕振鳴鑾。","如来车後隨金鼓，黄帝旂傍戴鐵冠。","醉捋黑鬚三島黯，怒抽霜劍十洲寒。","軒轅世代橫行後，直隐深巖久覓难。"]', '诗', 'shi', '', NULL, '七言 五十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1d802c-5440-46bc-8c55-e7c8f241d449', '七言 五十九', '七言 五十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["頭角蒼浪聲似鐘，貌如冰雪骨如松。","匣中寶劍時頻吼，袖裏金鎚逞露風。","會飲酒時爲伴侶，能行詩句便參同。","來年定赴蓬萊會，騎箇生獰九色龍。"]', '["头角蒼浪声似鐘，貌如冰雪骨如松。","匣中寶劍时頻吼，袖裏金鎚逞露风。","會饮酒时爲伴侶，能行诗句便參同。","来年定赴蓬萊會，騎箇生獰九色龙。"]', '诗', 'shi', '', NULL, '七言 五十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61eab38-e516-4c43-bbf9-4e5234309ebb', '七言 六十', '七言 六十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["神仙暮入黃金闕，將相門關白玉京。","可是洞中無好景，爲憐天下有衆生。","心琴際會閑隨鶴，匣劍時磨待斷鯨。","進退兩楹俱未應，憑君與我指前程。"]', '["神仙暮入黄金闕，將相门关白玉京。","可是洞中無好景，爲怜天下有衆生。","心琴際會闲隨鹤，匣劍时磨待斷鯨。","進退兩楹俱未應，憑君與我指前程。"]', '诗', 'shi', '', NULL, '七言 六十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310b6023-ff08-4fb1-9eec-79c8a8b1ff10', '七言 六十一', '七言 六十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九鼎烹煎一味砂，自然火候放童花。","星辰照出青蓮顆，日月能藏白馬牙。","七返返成生碧霧，九還還就吐紅霞。","有人奪得玄珠餌，三島途中路不賒。"]', '["九鼎烹煎一味砂，自然火候放童花。","星辰照出青蓮顆，日月能藏白马牙。","七返返成生碧霧，九還還就吐紅霞。","有人奪得玄珠餌，三島途中路不賒。"]', '诗', 'shi', '', NULL, '七言 六十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4ae8eb-218f-48fd-a6ad-8510d43d91e4', '七言 六十二', '七言 六十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天生一物變三才，交感陰陽結聖胎。","龍虎順行陰鬼去，龜蛇逆往火龍來。","嬰兒日喫黃婆髓，姹女時餐白玉杯。","功滿自然居物外，人間寒署任輪回。"]', '["天生一物变三才，交感陰陽結聖胎。","龙虎順行陰鬼去，龟蛇逆往火龙来。","嬰兒日喫黄婆髓，姹女时餐白玉杯。","功满自然居物外，人间寒署任輪回。"]', '诗', 'shi', '', NULL, '七言 六十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d030a2b-2ecb-418e-8694-104132fd4215', '七言 六十三', '七言 六十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["星辰聚會入離鄉，日月盈虧助藥王。","三候火燒金鼎寶，五符水煉玉壺漿。","乾坤反覆龍收霧，卯酉相吞虎放光。","入室用機擒捉取，一丸丹點體純陽。"]', '["星辰聚會入離乡，日月盈虧助藥王。","三候火燒金鼎寶，五符水煉玉壺漿。","乾坤反覆龙收霧，卯酉相吞虎放光。","入室用機擒捉取，一丸丹点體純陽。"]', '诗', 'shi', '', NULL, '七言 六十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8058a9a3-bbbb-4154-8387-c51a621ef895', '真人行巴陵市太守怒其不避使案吏具其罪真人曰須酒醒耳頃忽失之但留詩曰', '真人行巴陵市太守怒其不避使案吏具其罪真人曰須酒醒耳頃忽失之但留诗曰', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["暫別蓬萊海上遊，偶逢太守問根由。","身居北斗星杓下，劍挂南宮月角頭。","道我醉來真箇醉，不知愁是怎生愁。","相逢何事不相認，却駕白雲歸去休。"]', '["暫別蓬萊海上游，偶逢太守问根由。","身居北斗星杓下，劍挂南宮月角头。","道我醉来真箇醉，不知愁是怎生愁。","相逢何事不相認，却駕白云归去休。"]', '诗', 'shi', '', NULL, '真人行巴陵市太守怒其不避使案吏具其罪真人曰須酒醒耳頃忽失之但留詩曰 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cacf356-a783-4bf6-b22f-7de4923aa03b', '仙樂侑席', '仙乐侑席', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["曾經天上三千劫，又在人間五百年。","腰下劍鋒橫紫電，爐中丹焰起蒼煙。","纔騎白鹿過蒼海，復跨青牛入洞天。","小技等閑聊戲爾，無人知我是真仙。"]', '["曾經天上三千劫，又在人间五百年。","腰下劍鋒橫紫電，爐中丹焰起蒼煙。","纔騎白鹿過蒼海，复跨青牛入洞天。","小技等闲聊戲爾，無人知我是真仙。"]', '诗', 'shi', '', NULL, '仙樂侑席 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d97bbc-9489-4822-b1de-b423ff62191b', '題桐柏山黃先生庵門', '題桐柏山黄先生庵门', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["吾有玄中極玄語，周遊八極無處吐。","雲軿飄泛到凝陽，一見君兮在玄浦。","知君本是孤雲客，擬話希夷生恍惚。","無爲大道本根源，要君親見求真物。","其中有一分三五，本自無名號丹母。","寒泉瀝瀝氣綿綿，上透崑崙還紫府。","浮沈升降入中宮，四象五行齊見土。","驅青龍，擒白虎，起祥風兮下甘露。","鉛凝真汞結丹砂，一派火輪真爲主。","既修真，須堅確，能轉乾坤泛海岳。","運行天地莫能知，變化鬼神應不覺。","千朝煉就紫金身，乃致全神歸返朴。","黃秀才，黃秀才，既修真，須且早，人間萬事何時了。","貪名貪利愛金多，爲他財色身衰老。","我今勸子心悲切，君自思兮生猛烈。","莫教大限到身來，又是隨流入生滅。","留此片言，用表其意。","他日相逢，必與汝決。","莫退初心，善愛善愛。"]', '["吾有玄中極玄語，周游八極無处吐。","云軿飄泛到凝陽，一见君兮在玄浦。","知君本是孤云客，擬話希夷生恍惚。","無爲大道本根源，要君親见求真物。","其中有一分三五，本自無名號丹母。","寒泉瀝瀝氣綿綿，上透崑崙還紫府。","浮沈升降入中宮，四象五行齊见土。","驱青龙，擒白虎，起祥风兮下甘露。","鉛凝真汞結丹砂，一派火輪真爲主。","既修真，須堅確，能轉乾坤泛海岳。","運行天地莫能知，变化鬼神應不覺。","千朝煉就紫金身，乃致全神归返朴。","黄秀才，黄秀才，既修真，須且早，人间万事何时了。","貪名貪利愛金多，爲他財色身衰老。","我今勸子心悲切，君自思兮生猛烈。","莫教大限到身来，又是隨流入生滅。","留此片言，用表其意。","他日相逢，必與汝決。","莫退初心，善愛善愛。"]', '诗', 'shi', '', NULL, '題桐柏山黃先生庵門 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6337d58a-291c-4be1-a36a-8318341871ef', '五言 一', '五言 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["悟了長生理，秋蓮處處開。","金童登錦帳，玉女下香階。","虎嘯天魂住，龍吟地魄來。","有人明此道，立使返嬰孩。"]', '["悟了长生理，秋蓮处处开。","金童登錦帳，玉女下香階。","虎嘯天魂住，龙吟地魄来。","有人明此道，立使返嬰孩。"]', '诗', 'shi', '', NULL, '五言 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a668c670-aef9-49c6-876d-f957b0ec9341', '五言 二', '五言 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["姹女住南方，身邊產太陽。","蟾宮烹玉液，坎戶煉瓊漿。","過去神仙餌，今來到我嘗。","一杯延萬紀，物外任翺翔。"]', '["姹女住南方，身邊產太陽。","蟾宮烹玉液，坎戶煉瓊漿。","過去神仙餌，今来到我嘗。","一杯延万紀，物外任翺翔。"]', '诗', 'shi', '', NULL, '五言 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76af9e23-544c-4d7c-87d2-ef3d3b852268', '五言 三', '五言 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["頓悟黃芽理，陰陽稟自然。","乾坤爐裏煉，日月鼎中煎。","木產長生汞，金[烹]續命鉛。","世人明此道，立便返童顏。"]', '["頓悟黄芽理，陰陽稟自然。","乾坤爐裏煉，日月鼎中煎。","木產长生汞，金[烹]續命鉛。","世人明此道，立便返童顏。"]', '诗', 'shi', '', NULL, '五言 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0fd4ad-a7aa-4042-a99b-cdf128d472c0', '五言 四', '五言 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["宇宙產黃芽，經爐煅作砂。","陰陽烹五彩，水火煉三花。","鼎內龍降虎，壺中龜遣蛇。","功成歸物外，自在樂煙霞。"]', '["宇宙產黄芽，經爐煅作砂。","陰陽烹五彩，水火煉三花。","鼎內龙降虎，壺中龟遣蛇。","功成归物外，自在乐煙霞。"]', '诗', 'shi', '', NULL, '五言 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3ad5ee-0a96-4a0e-90f4-e42745132837', '五言 五', '五言 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["要覓長生路，除非認本元。","都來一味藥，剛道數千般。","丹鼎烹成汞，爐中煉就鉛。","依時服一粒，白日上冲天。"]', '["要覓长生路，除非認本元。","都来一味藥，剛道數千般。","丹鼎烹成汞，爐中煉就鉛。","依时服一粒，白日上冲天。"]', '诗', 'shi', '', NULL, '五言 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9bcea21-8fa9-4261-a7ea-9e7682a48596', '五言 六', '五言 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["姹女住瑤臺，仙花滿地開。","金苗從此出，玉蘂自天來。","鳳舞長生曲，鸞歌續命杯。","有人明此道，海變已千回。"]', '["姹女住瑤台，仙花满地开。","金苗從此出，玉蘂自天来。","鳳舞长生曲，鸾歌續命杯。","有人明此道，海变已千回。"]', '诗', 'shi', '', NULL, '五言 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('150477b6-37c2-4294-bbe3-c5e3fdecd178', '五言 七', '五言 七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["古往諸仙子，根元占甲庚。","水中聞虎嘯，火裏見龍行。","進退窮三候，相吞用八紘。","沖天功行滿，寒暑不能爭。"]', '["古往諸仙子，根元占甲庚。","水中闻虎嘯，火裏见龙行。","進退窮三候，相吞用八紘。","沖天功行满，寒暑不能爭。"]', '诗', 'shi', '', NULL, '五言 七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5320b510-0dcb-472e-aee5-bb0ea94d68c7', '五言 八', '五言 八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["我悟長生理，太陽伏太陰。","離宮生白玉，坎戶產黃金。","要主君臣義，須存子母心。","九重神室內，虎嘯與龍吟。"]', '["我悟长生理，太陽伏太陰。","離宮生白玉，坎戶產黄金。","要主君臣義，須存子母心。","九重神室內，虎嘯與龙吟。"]', '诗', 'shi', '', NULL, '五言 八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7439510-f25d-4cfe-8fb1-43ca04fd0fe4', '五言 九', '五言 九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["靈丹產太虛，九轉入重爐。","浴就紅蓮顆，燒成白玉珠。","水中鉛一兩，火內汞三銖。","喫了瑤臺寶，升天任海枯。"]', '["靈丹產太虛，九轉入重爐。","浴就紅蓮顆，燒成白玉珠。","水中鉛一兩，火內汞三銖。","喫了瑤台寶，升天任海枯。"]', '诗', 'shi', '', NULL, '五言 九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67d7ab8-475f-464c-af96-f7b9b0f18a49', '五言 十', '五言 十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["姹女住離宮，身邊產雌雄。","爐中七返畢，鼎內九還終。","悟了魚投水，迷因鳥在籠。","耄年服一粒，立地變沖童。"]', '["姹女住離宮，身邊產雌雄。","爐中七返畢，鼎內九還終。","悟了鱼投水，迷因鸟在籠。","耄年服一粒，立地变沖童。"]', '诗', 'shi', '', NULL, '五言 十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8438f8-6955-4d12-b06f-d31ad8537cf0', '五言 十一', '五言 十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["盜得乾坤祖，陰陽是本宗。","天魂生白虎，地魄產青龍。","運寶泥丸在，搬精入上宮。","有人明此法，萬載貌如童。"]', '["盜得乾坤祖，陰陽是本宗。","天魂生白虎，地魄產青龙。","運寶泥丸在，搬精入上宮。","有人明此法，万載貌如童。"]', '诗', 'shi', '', NULL, '五言 十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc79d6b-9ad1-4e55-a117-43810b46a1de', '五言 十二', '五言 十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["要覓金丹理，根元不易逢。","三才七返足，四象九還終。","浴就微微白，燒成漸漸紅。","一丸延萬紀，物外去沖沖。"]', '["要覓金丹理，根元不易逢。","三才七返足，四象九還終。","浴就微微白，燒成漸漸紅。","一丸延万紀，物外去沖沖。"]', '诗', 'shi', '', NULL, '五言 十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e56e1b9-4222-411e-bbc3-4c12b3bf8dc3', '五言 十三', '五言 十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["箇箇覓長生，根元不易尋。","要貪天上寶，須去世間琛。","煉就水中火，燒成陽內陰。","祖師親有語，一味水中金。"]', '["箇箇覓长生，根元不易尋。","要貪天上寶，須去世间琛。","煉就水中火，燒成陽內陰。","祖師親有語，一味水中金。"]', '诗', 'shi', '', NULL, '五言 十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9373786-9726-41ca-a73b-a9b1df3be4a8', '五言 十四', '五言 十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["萬物皆生土，如人得本元。","青龍精是汞，白虎水爲鉛。","悟者子投母，迷應地是天。","將來物外客，箇箇補丹田。"]', '["万物皆生土，如人得本元。","青龙精是汞，白虎水爲鉛。","悟者子投母，迷應地是天。","將来物外客，箇箇補丹田。"]', '诗', 'shi', '', NULL, '五言 十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff1110f3-f23c-48c7-85f0-b279de71221d', '五言 十五', '五言 十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["二十四神清，三千功行成。","寒雲連地轉，聖日滿天明。","玉子偏宜種，金田豈在耕。","此中真妙理，誰道不長生。"]', '["二十四神清，三千功行成。","寒云連地轉，聖日满天明。","玉子偏宜種，金田豈在耕。","此中真妙理，誰道不长生。"]', '诗', 'shi', '', NULL, '五言 十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7e87b2-8322-4727-99b6-f203f7cb0b62', '五言 十六', '五言 十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["妙妙妙中妙，玄玄玄更玄。","動言俱演道，語默盡神仙。","在掌如珠異，當空似月圓。","他時功滿後，直入大羅天。"]', '["妙妙妙中妙，玄玄玄更玄。","动言俱演道，語默尽神仙。","在掌如珠異，當空似月圓。","他时功满後，直入大羅天。"]', '诗', 'shi', '', NULL, '五言 十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ee1814-a6d0-42eb-b548-db1535244e45', '絕句 一', '絕句 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["捉得金晶固命基，日魂東畔月華西。","於中煉就長生藥，服了還同天地齊。"]', '["捉得金晶固命基，日魂东畔月华西。","於中煉就长生藥，服了還同天地齊。"]', '诗', 'shi', '', NULL, '絕句 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15a7226-df6b-48d2-934c-0ea53d3f350f', '絕句 二', '絕句 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["莫怪瑤池消息稀，只緣塵事隔天機。","若人尋得水中火，有一黃童上太微。"]', '["莫怪瑤池消息稀，只緣塵事隔天機。","若人尋得水中火，有一黄童上太微。"]', '诗', 'shi', '', NULL, '絕句 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3311951b-217e-4a51-a7db-a32b64d38ce6', '絕句 三', '絕句 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["混元海底隱生倫，內有黃童玉帝名。","白虎神符潛姹女，靈元鎮在七元君。"]', '["混元海底隐生倫，內有黄童玉帝名。","白虎神符潛姹女，靈元鎮在七元君。"]', '诗', 'shi', '', NULL, '絕句 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd62fd1d-c17c-4deb-a0b7-9815ba54f783', '絕句 四', '絕句 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三畝丹田無種種，種時須藉赤龍耕。","曾將此種教人種，不解鉛池道不生。"]', '["三畝丹田無種種，種时須藉赤龙耕。","曾將此種教人種，不解鉛池道不生。"]', '诗', 'shi', '', NULL, '絕句 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b1a941-50c9-4ec9-b131-8417e7e8b8ed', '絕句 五', '絕句 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["閃灼虎龍神劒飛，好憑身事莫相違。","傳時須在乾坤力，便透三清入紫微。"]', '["閃灼虎龙神劒飞，好憑身事莫相違。","傳时須在乾坤力，便透三清入紫微。"]', '诗', 'shi', '', NULL, '絕句 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fed18c2-a9db-4815-b2b7-76c12da0c635', '絕句 六', '絕句 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["不用梯媒向外求，還丹只在體中收。","莫言大道人難得，自是功夫不到頭。"]', '["不用梯媒向外求，還丹只在體中收。","莫言大道人难得，自是功夫不到头。"]', '诗', 'shi', '', NULL, '絕句 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b9f02a6-1481-4f0e-a0ba-fd49d3da2e92', '絕句 七', '絕句 七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["飲酒須教一百杯，東浮西泛自梯媒。","日精自與月華合，有箇明珠走上來。"]', '["饮酒須教一百杯，东浮西泛自梯媒。","日精自與月华合，有箇明珠走上来。"]', '诗', 'shi', '', NULL, '絕句 七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a183514-1707-4fd9-87f3-be780ced9ab1', '絕句 八', '絕句 八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["不負三光不負人，不欺神道不欺貧。","有人問我修行法，只種心田養此身。"]', '["不負三光不負人，不欺神道不欺貧。","有人问我修行法，只種心田養此身。"]', '诗', 'shi', '', NULL, '絕句 八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cef72683-a09a-41a0-8cec-743064f15f64', '絕句 九', '絕句 九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["時人若擬去瀛洲，先過巍巍十八樓。","自有電雷聲震動，一池金水向東流。"]', '["时人若擬去瀛洲，先過巍巍十八楼。","自有電雷声震动，一池金水向东流。"]', '诗', 'shi', '', NULL, '絕句 九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb5db12-c4bf-4ac1-b7ba-d97ad82134d0', '絕句 十', '絕句 十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["瓶子如金玉子黃，上升下降續神光。","三元一會經年淨，這箇天中日月長。"]', '["瓶子如金玉子黄，上升下降續神光。","三元一會經年淨，這箇天中日月长。"]', '诗', 'shi', '', NULL, '絕句 十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b326ea37-34cf-4ddc-b079-6ee7dcf53aad', '絕句 十一', '絕句 十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["學道須教徹骨貧，囊中只有五三文。","有人問我修行法，遙指天邊日月輪。"]', '["学道須教徹骨貧，囊中只有五三文。","有人问我修行法，遙指天邊日月輪。"]', '诗', 'shi', '', NULL, '絕句 十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2100d40f-5c57-4b87-b99f-6b2ad1af5050', '絕句 十二', '絕句 十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["我自忘心神自悅，跨水穿雲來相謁。","不問黃芽肘後方，妙道通微怎生說。"]', '["我自忘心神自悅，跨水穿云来相謁。","不问黄芽肘後方，妙道通微怎生说。"]', '诗', 'shi', '', NULL, '絕句 十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425391f4-e485-4ac6-a082-c555874b0411', '絕句 十三', '絕句 十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["肘傳丹篆千年術，口誦黃庭兩卷經。","鶴觀古壇松影裏，悄無人跡戶長扃。"]', '["肘傳丹篆千年術，口誦黄庭兩卷經。","鹤观古壇松影裏，悄無人跡戶长扃。"]', '诗', 'shi', '', NULL, '絕句 十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c75422c-39b5-4da7-92d4-2c27438dc399', '絕句 十四', '絕句 十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["獨上高峰望八都，黑雲散後月還孤。","茫茫宇宙人無數，幾箇男兒是丈夫。"]', '["独上高峰望八都，黑云散後月還孤。","茫茫宇宙人無數，幾箇男兒是丈夫。"]', '诗', 'shi', '', NULL, '絕句 十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2091a3-f81c-4757-aa0c-9b8aceab6c97', '絕句 十五', '絕句 十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天下都遊半日功，不須跨鳳與乘龍。","偶因博戲飛神劒，摧却終南第一峰。"]', '["天下都游半日功，不須跨鳳與乘龙。","偶因博戲飞神劒，摧却終南第一峰。"]', '诗', 'shi', '', NULL, '絕句 十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66060086-27e6-4c01-b7d8-587070143296', '絕句 十六', '絕句 十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["朝遊北越暮蒼梧，袖裏青虵膽氣麤。","三入岳陽人不識，朗吟飛過洞庭湖。"]', '["朝游北越暮蒼梧，袖裏青虵膽氣麤。","三入岳陽人不識，朗吟飞過洞庭湖。"]', '诗', 'shi', '', NULL, '絕句 十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df0c2e1-4ea1-483a-9e9c-019d31b1dcd0', '絕句 十七', '絕句 十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["趯倒葫蘆掉却琴，倒行直上臥牛岑。","水飛石上迸如雪，立地看天坐地吟。"]', '["趯倒葫蘆掉却琴，倒行直上臥牛岑。","水飞石上迸如雪，立地看天坐地吟。"]', '诗', 'shi', '', NULL, '絕句 十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a3d5e84-ea53-4c09-a604-32be537fbc5e', '絕句 十八', '絕句 十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["吾家本住在天齊，零落白雲鏁石梯。","來往八千消半日，依前歸路不曾迷。"]', '["吾家本住在天齊，零落白云鏁石梯。","来往八千消半日，依前归路不曾迷。"]', '诗', 'shi', '', NULL, '絕句 十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a928a8b3-23d8-4215-a138-6d6c6d90c996', '絕句 十九', '絕句 十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["蓮峰道士高且潔，不下蓮宮經歲月。","星辰夜禮玉簪寒，龍虎曉開金鼎熱。"]', '["蓮峰道士高且潔，不下蓮宮經歲月。","星辰夜禮玉簪寒，龙虎晓开金鼎熱。"]', '诗', 'shi', '', NULL, '絕句 十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ff8f8a-773e-4e0e-8d9a-fcf739348dfb', '絕句 二十', '絕句 二十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["東山東畔忽相逢，握手丁寧語似鐘。","劒術已成君把去，有蛟龍處斬蛟龍。"]', '["东山东畔忽相逢，握手丁寧語似鐘。","劒術已成君把去，有蛟龙处斬蛟龙。"]', '诗', 'shi', '', NULL, '絕句 二十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('518c566f-124b-49f1-a112-db1a42b1cd59', '絕句 二十一', '絕句 二十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["朝泛蒼梧暮却還，洞中日月我爲天。","匣中寶劒時時吼，不遇同人誓不傳。"]', '["朝泛蒼梧暮却還，洞中日月我爲天。","匣中寶劒时时吼，不遇同人誓不傳。"]', '诗', 'shi', '', NULL, '絕句 二十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4753fec1-6acd-421e-bf64-ef6c6ea86559', '絕句 二十二', '絕句 二十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["偎巖拍手葫蘆舞，過嶺穿雲拄杖飛。","來往八千須半日，金州南畔有松扉。"]', '["偎巖拍手葫蘆舞，過嶺穿云拄杖飞。","来往八千須半日，金州南畔有松扉。"]', '诗', 'shi', '', NULL, '絕句 二十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a19074-684d-4ca3-826b-0811c1257631', '絕句 二十三', '絕句 二十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["養得兒形似我形，我身枯悴子光精。","生生世世常如此，爭似留神養自身。"]', '["養得兒形似我形，我身枯悴子光精。","生生世世常如此，爭似留神養自身。"]', '诗', 'shi', '', NULL, '絕句 二十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c27e42-787a-4d42-8c1b-eb40564b83ed', '絕句 二十四', '絕句 二十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["精養靈根氣養神，此真之外更無真。","神仙不肯分明說，迷了千千萬萬人。"]', '["精養靈根氣養神，此真之外更無真。","神仙不肯分明说，迷了千千万万人。"]', '诗', 'shi', '', NULL, '絕句 二十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8218fe50-a95b-4604-b959-f4a6f7ef1c38', '絕句 二十五', '絕句 二十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["不事王侯不種田，日高猶自抱琴眠。","起來旋點黃金買，不使人間作業錢。"]', '["不事王侯不種田，日高猶自抱琴眠。","起来旋点黄金買，不使人间作業錢。"]', '诗', 'shi', '', NULL, '絕句 二十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef843167-22f3-417a-8a2c-2811ddeb7b3f', '絕句 二十六', '絕句 二十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天涯海角人求我，行到天涯不見人。","忠孝義慈行方便，不須求我自然真。"]', '["天涯海角人求我，行到天涯不见人。","忠孝義慈行方便，不須求我自然真。"]', '诗', 'shi', '', NULL, '絕句 二十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17216ad1-f903-45aa-8ca8-77ee57a2ffbc', '絕句 二十七', '絕句 二十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["莫道幽人一事無，閑中儘有靜工夫。","閉門清晝讀書罷，掃地焚香到日晡。"]', '["莫道幽人一事無，闲中儘有静工夫。","閉门清晝读书罷，掃地焚香到日晡。"]', '诗', 'shi', '', NULL, '絕句 二十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ffbbaf-64fc-4597-98e0-710ff95d2b01', '絕句 二十八', '絕句 二十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["先生先生貌獰惡，拔劒當空氣雲錯。","連喝三回急急去，歘然空裏人頭落。"]', '["先生先生貌獰惡，拔劒當空氣云錯。","連喝三回急急去，歘然空裏人头落。"]', '诗', 'shi', '', NULL, '絕句 二十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('557995d9-848a-40b6-8fc1-85a36bfbcf83', '絕句 二十九', '絕句 二十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["劒起星奔萬里誅，風雷時逐雨聲麤。","人頭攜處非人在，何事高吟過五湖。"]', '["劒起星奔万里誅，风雷时逐雨声麤。","人头携处非人在，何事高吟過五湖。"]', '诗', 'shi', '', NULL, '絕句 二十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7305732-3b1a-46f8-a954-c2fe7dd1dee7', '絕句 三十', '絕句 三十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["麤眉卓豎語如雷，聞說不平便放杯。","仗劒當空千里去，一更別我二更回。"]', '["麤眉卓豎語如雷，闻说不平便放杯。","仗劒當空千里去，一更別我二更回。"]', '诗', 'shi', '', NULL, '絕句 三十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51304359-b236-48d3-a0d6-ba571fb4a9a7', '絕句 三十一', '絕句 三十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["先生先生莫外求，道要人傳劒要收。","今日相逢江海畔，一杯村酒勸君休。"]', '["先生先生莫外求，道要人傳劒要收。","今日相逢江海畔，一杯村酒勸君休。"]', '诗', 'shi', '', NULL, '絕句 三十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d85470b-9e3d-4b9f-9d14-48bf480ff282', '絕句 三十二', '絕句 三十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["龐眉鬬豎惡精神，萬里騰空一踴身。","背上匣中三尺劒，爲天且示不平人。"]', '["龐眉鬬豎惡精神，万里腾空一踴身。","背上匣中三尺劒，爲天且示不平人。"]', '诗', 'shi', '', NULL, '絕句 三十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76159db7-900b-4d8d-b418-aba20ece5484', '徽宗齋會', '徽宗斋會', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["高談闊論若無人，可惜明君不遇真。","陛下問臣來日事，請看午未丙丁春。"]', '["高談闊論若無人，可惜明君不遇真。","陛下问臣来日事，請看午未丙丁春。"]', '诗', 'shi', '', NULL, '徽宗齋會 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e23bf8c-411d-402a-a872-73b59deff9bd', '七夕 一', '七夕 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["四海孤遊一野人，兩壺霜雪足精神。","坎離二物君收得，龍虎丹行運水銀。"]', '["四海孤游一野人，兩壺霜雪足精神。","坎離二物君收得，龙虎丹行運水銀。"]', '诗', 'shi', '', NULL, '七夕 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1631049c-a2d0-4ecf-b9fe-f72eb9a88c5c', '七夕 二', '七夕 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["野人本是天台客，石橋南畔有舊宅。","父子生來有兩口，多好歌笙不好拍。"]', '["野人本是天台客，石橋南畔有旧宅。","父子生来有兩口，多好歌笙不好拍。"]', '诗', 'shi', '', NULL, '七夕 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb2a4bd-77a1-4394-8059-5d730a18e43b', '贈李德成', '贈李德成', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九重天子寰中貴，五等諸侯門外尊。","爭似布衣狂醉客，不教性命屬乾坤。"]', '["九重天子寰中貴，五等諸侯门外尊。","爭似布衣狂醉客，不教性命屬乾坤。"]', '诗', 'shi', '', NULL, '贈李德成 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed966582-de5b-41f6-b041-eb5c38909187', '牧童', '牧童', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["草鋪橫野六七里，笛弄晚風三四聲。","歸來飽飯黃昏後，不脫蓑衣臥月明。"]', '["草鋪橫野六七里，笛弄晚风三四声。","归来飽飯黄昏後，不脫蓑衣臥月明。"]', '诗', 'shi', '', NULL, '牧童 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cba0a35-1e99-4ba2-afe1-a3fc43ac0b8d', '潭州鶴會', '潭州鹤會', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["這回相見不無緣，滿院風光小洞天。","一劒當空又飛去，洞庭驚起老龍眠。"]', '["這回相见不無緣，满院风光小洞天。","一劒當空又飞去，洞庭驚起老龙眠。"]', '诗', 'shi', '', NULL, '潭州鶴會 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3575581c-c176-4f9f-8c03-d2fe2a9b93f1', '紹興道會', '紹兴道會', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["偶乘青帝出蓬萊，劒戟崢嶸遍九垓。","我在目前人不識，爲留一笠莫沉埋。"]', '["偶乘青帝出蓬萊，劒戟崢嶸遍九垓。","我在目前人不識，爲留一笠莫沉埋。"]', '诗', 'shi', '', NULL, '紹興道會 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34c2a6c-7f5e-4e38-a362-afc55c729a70', '贈曹先生', '贈曹先生', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鶴不西飛龍不行，露乾雲破洞簫清。","少年仙子說閑事，遙隔綵雲聞笑聲。"]', '["鹤不西飞龙不行，露乾云破洞簫清。","少年仙子说闲事，遙隔綵云闻笑声。"]', '诗', 'shi', '', NULL, '贈曹先生 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4228c77a-822e-435f-9637-fcf0fd953582', '海上相逢趙同', '海上相逢趙同', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["南宮水火吾須濟，北闕夫妻我自媒。","洞裏龍兒嬌鬱律，山前童子喜徘徊。"]', '["南宮水火吾須濟，北闕夫妻我自媒。","洞裏龙兒嬌鬱律，山前童子喜徘徊。"]', '诗', 'shi', '', NULL, '海上相逢趙同 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c60436-e606-46c9-a6eb-0749c47d70d0', '題鳳翔府天慶觀', '題鳳翔府天慶观', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["得道年來八百秋，不曾飛劒取人頭。","玉皇未有天符至，且貨烏金混世流。"]', '["得道年来八百秋，不曾飞劒取人头。","玉皇未有天符至，且貨烏金混世流。"]', '诗', 'shi', '', NULL, '題鳳翔府天慶觀 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('230c2563-a02c-4bd0-96a6-65eb35c259cd', '劒畫此詩於襄陽雪中', '劒畫此诗於襄陽雪中', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["峴山一夜玉龍寒，鳳林千樹梨花老。","襄陽城裏沒人知，襄陽城外江山好。"]', '["峴山一夜玉龙寒，鳳林千樹梨花老。","襄陽城裏沒人知，襄陽城外江山好。"]', '诗', 'shi', '', NULL, '劒畫此詩於襄陽雪中 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b3b8a7-4671-43ca-a57b-8fc05bdfeb52', '洞庭湖君山頌', '洞庭湖君山頌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["午夜君山翫月回，西鄰小圃碧蓮開。","天香風露蒼華冷，雲在青霄鶴未來。"]', '["午夜君山翫月回，西鄰小圃碧蓮开。","天香风露蒼华冷，云在青霄鹤未来。"]', '诗', 'shi', '', NULL, '洞庭湖君山頌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc2a159-7613-41db-a06a-42f233dc4543', '秦州北山觀留詩', '秦州北山观留诗', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["石池清水是吾心，剛被桃花影倒沉。","一到邽山宮闕內，銷閑澄慮七弦琴。"]', '["石池清水是吾心，剛被桃花影倒沉。","一到邽山宮闕內，銷闲澄慮七弦琴。"]', '诗', 'shi', '', NULL, '秦州北山觀留詩 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e7ab69-72eb-45c8-8169-2fba4cd7b782', '題永康酒樓', '題永康酒楼', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鯨吸鰲吞數百杯，玉山誰起復誰頹。","醒時兩袂天風冷，一朵紅雲海上來。"]', '["鯨吸鰲吞數百杯，玉山誰起复誰頹。","醒时兩袂天风冷，一朵紅云海上来。"]', '诗', 'shi', '', NULL, '題永康酒樓 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc09af65-643f-4608-b4d5-228c5504d8a8', '贈滕宗諒', '贈滕宗諒', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["華州回道人，來到岳陽城。","別我遊何處，秋空一劒橫。"]', '["华州回道人，来到岳陽城。","別我游何处，秋空一劒橫。"]', '诗', 'shi', '', NULL, '贈滕宗諒 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef413fc-5ba1-4fa5-a427-379bb1f54a31', '贈江州太平觀道士', '贈江州太平观道士', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["落魄薛高士，年高無白髭。","雲中閑臥石，山裏冷尋碑。","誇我飲大酒，嫌人說小詩。","不知甚麽漢，一任輩流嗤。"]', '["落魄薛高士，年高無白髭。","云中闲臥石，山裏冷尋碑。","誇我饮大酒，嫌人说小诗。","不知甚麽漢，一任輩流嗤。"]', '诗', 'shi', '', NULL, '贈江州太平觀道士 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63701c9-bfb0-49e3-baeb-c960b12aff1d', '宋朝張天覺爲相之日有繿縷道人及門求施公不知禮敬因戲問道人有何仙術荅以能揑土爲香公請試爲之須臾煙罷道人不見但留詩于案上云', '宋朝張天覺爲相之日有繿縷道人及门求施公不知禮敬因戲问道人有何仙術荅以能揑土爲香公請試爲之須臾煙罷道人不见但留诗于案上云', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["捏土爲香事有因，世間宜假不宜真。","皇朝宰相張天覺，天下雲遊呂洞賓。"]', '["捏土爲香事有因，世间宜假不宜真。","皇朝宰相張天覺，天下云游呂洞賓。"]', '诗', 'shi', '', NULL, '宋朝張天覺爲相之日有繿縷道人及門求施公不知禮敬因戲問道人有何仙術荅以能揑土爲香公請試爲之須臾煙罷道人不見但留詩于案上云 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccddb57-f0b6-4e05-925b-49003dfa2a3d', '贈陳處士', '贈陳处士', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["青霄一路少人行，休話興亡事不成。","金榜因何無姓字，玉都必是有仙名。","雲歸入海龍千尺，雲滿長空鶴一聲。","深謝宋朝明聖主，解書丹詔詔先生。"]', '["青霄一路少人行，休話兴亡事不成。","金榜因何無姓字，玉都必是有仙名。","云归入海龙千尺，云满长空鹤一声。","深謝宋朝明聖主，解书丹詔詔先生。"]', '诗', 'shi', '', NULL, '贈陳處士 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a083efa-e037-4d6a-8569-b7e676fc371c', '哭陳先生', '哭陳先生', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天網恢恢萬象疎，一身親到華山區。","寒雲去後留殘月，春雪來時問太虛。","六洞真人歸紫府，千年鸞鶴老蒼梧。","自從遺却先生後，南北東西少丈夫。"]', '["天網恢恢万象疎，一身親到华山區。","寒云去後留殘月，春雪来时问太虛。","六洞真人归紫府，千年鸾鹤老蒼梧。","自從遺却先生後，南北东西少丈夫。"]', '诗', 'shi', '', NULL, '哭陳先生 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3817a0-07fd-4e7c-8308-047ab579eabd', '化江南簡寂觀道士侯用晦磨劒', '化江南簡寂观道士侯用晦磨劒', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["欲整鋒鋩取憚勞，凌晨開匣玉龍嗥。","手中氣概冰三尺，石上精神虵一條。","姦血默隨流水盡，凶豪今逐漬痕消。","削平浮世不平事，與爾相將上九霄。"]', '["欲整鋒鋩取憚勞，凌晨开匣玉龙嗥。","手中氣概冰三尺，石上精神虵一條。","姦血默隨流水尽，凶豪今逐漬痕消。","削平浮世不平事，與爾相將上九霄。"]', '诗', 'shi', '', NULL, '化江南簡寂觀道士侯用晦磨劒 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbfbc747-acf1-4e1b-b5e8-aef58ef199bc', '熙寧元年八月十九日過湖州東林沈山用石榴皮寫絕句於壁自號回山人', '熙寧元年八月十九日過湖州东林沈山用石榴皮寫絕句於壁自號回山人', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["西鄰已富憂不足，東老雖貧樂有餘。","白酒釀來緣好客，黃金散盡爲收書。"]', '["西鄰已富憂不足，东老雖貧乐有餘。","白酒釀来緣好客，黄金散尽爲收书。"]', '诗', 'shi', '', NULL, '熙寧元年八月十九日過湖州東林沈山用石榴皮寫絕句於壁自號回山人 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10812bf0-3ddb-4b55-a1fd-187aee311bb2', '大雲寺茶詩', '大云寺茶诗', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["玉蘂一鎗稱絕品，僧家造法極功夫。","兔毛甌淺香雲白，蝦眼湯翻細浪俱。","斷送睡魔離几席，增添清氣入肌膚。","幽叢自落溪巖外，不肯移根入上都。"]', '["玉蘂一鎗稱絕品，僧家造法極功夫。","兔毛甌淺香云白，蝦眼湯翻細浪俱。","斷送睡魔離几席，增添清氣入肌膚。","幽叢自落溪巖外，不肯移根入上都。"]', '诗', 'shi', '', NULL, '大雲寺茶詩 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cfccc63-31e4-448f-9adb-e5ef04dd11f9', '別詩二首 一', '別诗二首 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["無心獨坐轉黃庭，不逐時流入利名。","救老只存真一氣，修生長遣百神靈。","朝朝煉液歸瓊壠，夜夜朝元養玉英。","莫笑老人貧裏樂，十年功滿上三清。"]', '["無心独坐轉黄庭，不逐时流入利名。","救老只存真一氣，修生长遣百神靈。","朝朝煉液归瓊壠，夜夜朝元養玉英。","莫笑老人貧裏乐，十年功满上三清。"]', '诗', 'shi', '', NULL, '別詩二首 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df314794-aec3-4778-99ae-6a0463d55340', '別詩二首 二', '別诗二首 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["時人受氣稟陰陽，均體乾坤壽命長。","爲重本宗能壽永，因輕元祖遂淪亡。","三宮自有迴流法，萬物那無運用方。","咫尺崑崙山上玉，幾人知是藥中王。"]', '["时人受氣稟陰陽，均體乾坤壽命长。","爲重本宗能壽永，因轻元祖遂淪亡。","三宮自有迴流法，万物那無運用方。","咫尺崑崙山上玉，幾人知是藥中王。"]', '诗', 'shi', '', NULL, '別詩二首 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6dcac8c-b132-49f8-8758-cadb269d0223', '贈羅浮道士', '贈羅浮道士', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["羅浮道士誰同流，草衣木食輕王侯。","世間甲子管不得，壺裏乾坤只自由。","數着殘棊江月曉，一聲長嘯海山秋。","飲餘回首話歸路，遙指白雲天際頭。"]', '["羅浮道士誰同流，草衣木食轻王侯。","世间甲子管不得，壺裏乾坤只自由。","數着殘棊江月晓，一声长嘯海山秋。","饮餘回首話归路，遙指白云天際头。"]', '诗', 'shi', '', NULL, '贈羅浮道士 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6ec907-4bb3-4266-b3bf-02569ffd7ddf', '宿州天慶觀殿門留贈符離道士', '宿州天慶观殿门留贈符離道士', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["秋景蕭條葉亂飛，庭松影裏坐移時。","雲迷鶴駕何方去，仙洞朝元失我期。"]', '["秋景蕭條葉亂飞，庭松影裏坐移时。","云迷鹤駕何方去，仙洞朝元失我期。"]', '诗', 'shi', '', NULL, '宿州天慶觀殿門留贈符離道士 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3535553-31b0-4b12-983e-db5e50119e97', '題黃鶴樓石照', '題黄鹤楼石照', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["黃鶴樓前吹笛時，白蘋紅蓼滿江湄。","衷情欲訴誰能會，惟有清風明月知。"]', '["黄鹤楼前吹笛时，白蘋紅蓼满江湄。","衷情欲訴誰能會，惟有清风明月知。"]', '诗', 'shi', '', NULL, '題黃鶴樓石照 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee45e7e-378e-486b-9535-a9f77bffd102', '荅僧見', '荅僧见', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三千里外無家客，七百年來雲水身。","行滿蓬萊爲別館，道成瓦礫盡黃金。","待賓榼裏常存酒，化藥爐中別有春。","積德求師何患少，由來天地不私親。"]', '["三千里外無家客，七百年来云水身。","行满蓬萊爲別館，道成瓦礫尽黄金。","待賓榼裏常存酒，化藥爐中別有春。","積德求師何患少，由来天地不私親。"]', '诗', 'shi', '', NULL, '荅僧見 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02f1433-c766-4c72-9738-f1c3179d9b15', '與潭州智度寺慧覺詩', '與潭州智度寺慧覺诗', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["達者推心兼濟物，聖賢傳法不離真。","請師開說西來意，七祖如今未有人。"]', '["達者推心兼濟物，聖賢傳法不離真。","請師开说西来意，七祖如今未有人。"]', '诗', 'shi', '', NULL, '與潭州智度寺慧覺詩 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf44ceff-9ce2-4708-b4e7-e66feb5cec58', '參黃龍機悟後呈偈', '參黄龙機悟後呈偈', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["棄却瓢囊摵碎琴，如今不戀□中金。","自從一見黃龍後，始覺從前錯用心。"]', '["棄却瓢囊摵碎琴，如今不戀□中金。","自從一见黄龙後，始覺從前錯用心。"]', '诗', 'shi', '', NULL, '參黃龍機悟後呈偈 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3377218-e870-4b6a-adf4-cf6425587ae1', '題僧房絕句', '題僧房絕句', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["唐朝進士，今日神仙。","足躡紫霧，却返洞天。"]', '["唐朝進士，今日神仙。","足躡紫霧，却返洞天。"]', '诗', 'shi', '', NULL, '題僧房絕句 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2297fa0-4fbe-4e21-a467-01a86b851f9e', '賜齊州李希遇詩', '賜齊州李希遇诗', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["少飲欺心酒，休貪不義財。","福因慈善得，禍向巧姦來。"]', '["少饮欺心酒，休貪不義財。","福因慈善得，禍向巧姦来。"]', '诗', 'shi', '', NULL, '賜齊州李希遇詩 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aed390e-cec4-4ecf-96ad-37adcb6e8abf', '六言', '六言', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["春暖羣花半開，逍遙石上徘徊。","獨攜玉律丹訣，閑踏青莎碧苔。","古洞眠來九載，流霞飲幾千杯。","逢人莫話他事，笑指白雲去來。"]', '["春暖羣花半开，逍遙石上徘徊。","独携玉律丹訣，闲踏青莎碧苔。","古洞眠来九載，流霞饮幾千杯。","逢人莫話他事，笑指白云去来。"]', '诗', 'shi', '', NULL, '六言 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07909e25-206d-4c7a-b76a-7f052ce2b2f5', '明胎息', '明胎息', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["密室靜存神，陰陽重一斤。","煉成離女液，嚥盡坎男津。","漸變逍遙體，超然自在身。","更休功業滿，旌鶴引朝真。"]', '["密室静存神，陰陽重一斤。","煉成離女液，嚥尽坎男津。","漸变逍遙體，超然自在身。","更休功業满，旌鹤引朝真。"]', '诗', 'shi', '', NULL, '明胎息 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a25f3128-9834-4dc9-9a7f-ebe9568a8881', '警世', '警世', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["二八佳人體似酥，腰間仗劒斬凡夫。","雖然不見人頭落，暗裏教君骨髓枯。"]', '["二八佳人體似酥，腰间仗劒斬凡夫。","雖然不见人头落，暗裏教君骨髓枯。"]', '诗', 'shi', '', NULL, '警世 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96e2c63c-8f70-4e1d-9ed9-e6786f67492e', '通道', '通道', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["通道復通玄，名留四海傳。","交親一拄杖，活計兩空拳。","要果逡巡種，思茶逐旋煎。","豈知來混世，不久却回天。"]', '["通道复通玄，名留四海傳。","交親一拄杖，活計兩空拳。","要果逡巡種，思茶逐旋煎。","豈知来混世，不久却回天。"]', '诗', 'shi', '', NULL, '通道 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24818449-e5a9-41ad-b7d4-81ab80629745', '爲賈師雄發明古鐵鏡', '爲賈師雄發明古鐵镜', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["手內青虵凌白日，洞中仙果豔長春。","須知物外煙霞客，不是塵中磨鏡人。"]', '["手內青虵凌白日，洞中仙果豔长春。","須知物外煙霞客，不是塵中磨镜人。"]', '诗', 'shi', '', NULL, '爲賈師雄發明古鐵鏡 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad2e3b8-c17a-43dd-976b-fac54e398e90', '題全州道士蔣暉壁', '題全州道士蔣暉壁', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["醉舞高歌海上山，天瓢承露結金丹。","夜深鶴透秋空碧，萬里西風一劒寒。"]', '["醉舞高歌海上山，天瓢承露結金丹。","夜深鹤透秋空碧，万里西风一劒寒。"]', '诗', 'shi', '', NULL, '題全州道士蔣暉壁 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6cc0491-846c-4fde-ba61-524cd6323a44', '謁石守道', '謁石守道', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["高心休擬鳳池遊，朱紱銀章寵已優。","欲待禍來名欲滅，林泉養法預爲謀。"]', '["高心休擬鳳池游，朱紱銀章寵已優。","欲待禍来名欲滅，林泉養法預爲謀。"]', '诗', 'shi', '', NULL, '謁石守道 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15953941-0641-4b4e-9c0e-bdfcdc4efa51', '題廣陵妓屏二首 一', '題廣陵妓屏二首 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["嫫母西施共此身，可憐老少隔千春。","他年鶴髮雞皮媼，今日玉顏花貌人。"]', '["嫫母西施共此身，可怜老少隔千春。","他年鹤髮雞皮媼，今日玉顏花貌人。"]', '诗', 'shi', '', NULL, '題廣陵妓屏二首 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a97b707-c0b6-4d49-96a5-ac2495c033d4', '題廣陵妓屏二首 二', '題廣陵妓屏二首 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["花開花落兩悲歡，花與人還事一般。","開在枝間妨客折，落來地上請誰看。"]', '["花开花落兩悲歡，花與人還事一般。","开在枝间妨客折，落来地上請誰看。"]', '诗', 'shi', '', NULL, '題廣陵妓屏二首 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0bffd4b-fc60-4b81-a87e-6f78b072d594', '題東都妓館壁', '題东都妓館壁', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["一吸鸞笙裂太清，綠衣童子步虛聲。","玉樓喚醒千年夢，碧桃枝上金雞鳴。"]', '["一吸鸾笙裂太清，綠衣童子步虛声。","玉楼喚醒千年梦，碧桃枝上金雞鳴。"]', '诗', 'shi', '', NULL, '題東都妓館壁 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fdbb63-2d58-48ba-b7b9-4ca8c2c93e3c', '崔中舉進士遊岳陽遇真人錄沁園春詞詰其姓名薦之李守排戶而入惟見留詩于壁', '崔中舉進士游岳陽遇真人錄沁园春词詰其姓名薦之李守排戶而入惟见留诗于壁', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["腹內嬰兒養已成，且居廛市暫娛情。","無端措大剛饒舌，却入白雲深處行。"]', '["腹內嬰兒養已成，且居廛市暫娛情。","無端措大剛饒舌，却入白云深处行。"]', '诗', 'shi', '', NULL, '崔中舉進士遊岳陽遇真人錄沁園春詞詰其姓名薦之李守排戶而入惟見留詩于壁 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48ff3ef-b33b-4c90-9587-a5a03f05ca66', '題詩紫極宮', '題诗紫極宮', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["宮門一閑入，臨水憑欄立。","無人知我來，朱頂鶴聲急。"]', '["宮门一闲入，臨水憑欄立。","無人知我来，朱頂鹤声急。"]', '诗', 'shi', '', NULL, '題詩紫極宮 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e008712-a49b-4447-9c6b-881523f48470', '閑題', '闲題', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["獨自行來獨自坐，無限世人不識我。","惟有城南老樹精，分明知道神仙過。"]', '["独自行来独自坐，無限世人不識我。","惟有城南老樹精，分明知道神仙過。"]', '诗', 'shi', '', NULL, '閑題 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84ec2fa-cf4b-4d49-90da-21884df659bd', '山隱', '山隐', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["松枯石老水縈迴，箇裏難教俗客來。","擡眼試看山外景，紛紛風急障黃埃。"]', '["松枯石老水縈迴，箇裏难教俗客来。","擡眼試看山外景，紛紛风急障黄埃。"]', '诗', 'shi', '', NULL, '山隱 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff9af08-5d70-4331-a818-d51aba1a781d', '絕句 一', '絕句 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["息精息氣養精神，精養丹田氣養身。","有人學得這般術，便是長生不死人。"]', '["息精息氣養精神，精養丹田氣養身。","有人学得這般術，便是长生不死人。"]', '诗', 'shi', '', NULL, '絕句 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73647d3-09be-4bea-b7c8-72f741d550dd', '絕句 二', '絕句 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["斗笠爲帆扇作舟，五湖四海任遨遊。","大千沙界須臾至，石爛松枯經幾秋。"]', '["斗笠爲帆扇作舟，五湖四海任遨游。","大千沙界須臾至，石爛松枯經幾秋。"]', '诗', 'shi', '', NULL, '絕句 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406a277d-9657-47f7-a85b-7e52dd93ba5a', '絕句 三', '絕句 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["或爲道士或爲僧，混俗和光別有能。","苦海翻成天上路，毘盧常照百千燈。"]', '["或爲道士或爲僧，混俗和光別有能。","苦海翻成天上路，毘盧常照百千灯。"]', '诗', 'shi', '', NULL, '絕句 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa6ab28-af29-4b8c-9a40-82c73c0923a8', '勸世', '勸世', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["一毫之善，與人方便。","一毫之惡，勸君莫作。","衣食隨緣，自然快樂。","筭是甚命，問什麽卜。","欺人是禍，饒人是福。","天眼昭昭，報應甚速。","諦聽吾言，神欽鬼伏。"]', '["一毫之善，與人方便。","一毫之惡，勸君莫作。","衣食隨緣，自然快乐。","筭是甚命，问什麽卜。","欺人是禍，饒人是福。","天眼昭昭，報應甚速。","諦听吾言，神欽鬼伏。"]', '诗', 'shi', '', NULL, '勸世 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f52d0c04-d75f-4f0c-bd6b-eb67876e816e', '𡏟頭坯歌', '𡏟头坯歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["𡏟頭坯，隨雨破，秪是未曾經水火。","若經水火燒成磚，留向世間住萬年。","稜角堅完不復壞，扣之聲韻堪磨鐫。","凡水火，尚成功，堅完萬物誰能同。","修行路上多少人，窮年煉養費精神。","不道未曾經水火，無常一旦臨君身。","既不悟，終不悔，死了猶來借精髓。","主持正念大艱辛，一失人身爲異類。","君不見洛陽富鄭公，說與金丹如盲聾。","執迷不悟修真理，焉知潛合造化功。","又不見九江張尚書，服藥失明神氣枯。","不知還丹本無質，翻餌金石何太愚。","又不見三衢趙樞密，參禪作鬼終不識。","修完外體在何邊，辯捷語言終不實。","𡏟頭坯，隨雨破，便似修行這幾箇。","大丈夫，超覺性，了盡空門不爲證。","伏羲傳道至于今，窮理盡性至於命。","了命如何是本元，先認坎離幷四正。","坎離即是真常家，見者超凡須入聖。","坎是虎，離是龍，二體本來同一宮。","龍吞虎啗居其中，離合浮沈初復終。","剝而復，否而泰，進退往來定交會。","弦而望，明而晦，消長盈虛相匹配。","神仙深入水晶宮，時飲醍醐清更醲。","餌之千日功便成，金筋玉骨身已輕。","此箇景象惟自身，上昇早得朝三清。","三清聖位我亦有，本來只奪乾坤精。","飲凡酒，食羶腥，補養元和沖更盈。","自融結，轉光明，變作珍珠飛玉京。","須臾六年腸不餒，血化白膏體難毀。","不食方爲真絕糧，真氣薰蒸肢體強。","既不食，超百億，口鼻都無凡喘息。","真人以踵凡以喉，從此真凡兩邊立。","到此遂成無漏身，胎息丹田湧真火。","老氏自此號嬰兒，火候九年都經過。","留形住世不知春，忽爾天門頂中破。","真人出現大神通，從此天仙可相賀。","聖賢三教不異門，昧者勞心休恁麽。","有識自愛生，有形終不滅。","歎愚人，空駕說。","愚人流蕩無則休，落趣循環幾時徹。","學人學人細尋覓，且須研究古金碧。","金碧參同不計年，妙中妙兮玄中玄。"]', '["𡏟头坯，隨雨破，秪是未曾經水火。","若經水火燒成磚，留向世间住万年。","稜角堅完不复壞，扣之声韻堪磨鐫。","凡水火，尚成功，堅完万物誰能同。","修行路上多少人，窮年煉養費精神。","不道未曾經水火，無常一旦臨君身。","既不悟，終不悔，死了猶来借精髓。","主持正念大艱辛，一失人身爲異類。","君不见洛陽富鄭公，说與金丹如盲聾。","執迷不悟修真理，焉知潛合造化功。","又不见九江張尚书，服藥失明神氣枯。","不知還丹本無質，翻餌金石何太愚。","又不见三衢趙樞密，參禪作鬼終不識。","修完外體在何邊，辯捷語言終不實。","𡏟头坯，隨雨破，便似修行這幾箇。","大丈夫，超覺性，了尽空门不爲證。","伏羲傳道至于今，窮理尽性至於命。","了命如何是本元，先認坎離幷四正。","坎離即是真常家，见者超凡須入聖。","坎是虎，離是龙，二體本来同一宮。","龙吞虎啗居其中，離合浮沈初复終。","剝而复，否而泰，進退往来定交會。","弦而望，明而晦，消长盈虛相匹配。","神仙深入水晶宮，时饮醍醐清更醲。","餌之千日功便成，金筋玉骨身已轻。","此箇景象惟自身，上昇早得朝三清。","三清聖位我亦有，本来只奪乾坤精。","饮凡酒，食羶腥，補養元和沖更盈。","自融結，轉光明，变作珍珠飞玉京。","須臾六年腸不餒，血化白膏體难毀。","不食方爲真絕糧，真氣薰蒸肢體強。","既不食，超百億，口鼻都無凡喘息。","真人以踵凡以喉，從此真凡兩邊立。","到此遂成無漏身，胎息丹田湧真火。","老氏自此號嬰兒，火候九年都經過。","留形住世不知春，忽爾天门頂中破。","真人出現大神通，從此天仙可相賀。","聖賢三教不異门，昧者勞心休恁麽。","有識自愛生，有形終不滅。","歎愚人，空駕说。","愚人流蕩無則休，落趣循环幾时徹。","学人学人細尋覓，且須研究古金碧。","金碧參同不計年，妙中妙兮玄中玄。"]', '诗', 'shi', '', NULL, '𡏟頭坯歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa8f930a-65ca-4044-ad7d-a75fc9c09bf5', '贈劉方處士', '贈劉方处士', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["六國愁看沉與浮，攜琴長歗出神州。","擬向煙霞煮白石，偶來城市見丹丘。","受得金華出世術，期於紫府駕雲遊。","年來摘得黃巖翠，琪樹參差連地肺。","露飄香隴玉苗滋，月上碧峰丹鶴唳。","洞天消息春正深，仙路往還俗難繼。","忽因乘興下白雲，與君邂逅於塵世。","塵世相逢開口希，共論太古同流志。","瑤琴寶瑟與君彈，瓊漿玉液勸我醉。","醉中亦話興亡事，云道總無珪組累。","浮世短景倏成空，石火電光看即逝。","韶年淑質曾非固，花面玉顏還作土。","芳樽但繼曉復昏，樂事不窮今與古。","何如識箇玄玄道，道在杳冥須細考。","壺中一粒化奇物，物外千年功力奧。","但能制得水中華，水火翻成金丹竈。","丹就人間不久居，自有碧霄元命誥。","玄洲暘谷悉可居，地壽天齡永相保。","鸞車鶴駕逐雲飛，迢迢瑤池應易到。","耳聞爭戰還傾覆，眼見妍華成枯槁。","唐家舊國盡荒蕪，漢室諸侯空白草。","蜉蝣世界實足悲，槿花性命莫遲遲。","珠璣溢屋非爲福，羅綺滿箱徒自危。","志士戒貪昔所重，達人忘欲寧自期。","劉方劉方審聽我，流光迅速如飛過。","陰媱果決用心除，尸鬼因循爲汝禍。","八瓊秘訣君自識，莫待鉛空車又破。","破車壞鉛須震驚，直遇伯陽應不可。","悠悠憂家復憂國，耗盡三田元宅火。","咫尺玄關若要開，憑君自解黃金鎖。"]', '["六国愁看沉與浮，携琴长歗出神州。","擬向煙霞煮白石，偶来城市见丹丘。","受得金华出世術，期於紫府駕云游。","年来摘得黄巖翠，琪樹參差連地肺。","露飄香隴玉苗滋，月上碧峰丹鹤唳。","洞天消息春正深，仙路往還俗难繼。","忽因乘兴下白云，與君邂逅於塵世。","塵世相逢开口希，共論太古同流志。","瑤琴寶瑟與君彈，瓊漿玉液勸我醉。","醉中亦話兴亡事，云道總無珪組累。","浮世短景倏成空，石火電光看即逝。","韶年淑質曾非固，花面玉顏還作土。","芳樽但繼晓复昏，乐事不窮今與古。","何如識箇玄玄道，道在杳冥須細考。","壺中一粒化奇物，物外千年功力奧。","但能制得水中华，水火翻成金丹竈。","丹就人间不久居，自有碧霄元命誥。","玄洲暘谷悉可居，地壽天齡永相保。","鸾车鹤駕逐云飞，迢迢瑤池應易到。","耳闻爭戰還傾覆，眼见妍华成枯槁。","唐家旧国尽荒蕪，漢室諸侯空白草。","蜉蝣世界實足悲，槿花性命莫遲遲。","珠璣溢屋非爲福，羅綺满箱徒自危。","志士戒貪昔所重，達人忘欲寧自期。","劉方劉方審听我，流光迅速如飞過。","陰媱果決用心除，尸鬼因循爲汝禍。","八瓊秘訣君自識，莫待鉛空车又破。","破车壞鉛須震驚，直遇伯陽應不可。","悠悠憂家复憂国，耗尽三田元宅火。","咫尺玄关若要开，憑君自解黄金鎖。"]', '诗', 'shi', '', NULL, '贈劉方處士 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd41be01-a579-49be-89cb-6e21b69bc4cb', '寄白龍洞劉道人', '寄白龙洞劉道人', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["玉走金飛兩曜忙，始聞花發又秋霜。","徒誇籛壽千年歲，也是雲中一電光。","一電光，何太疾，百年都來三萬日。","其間寒暑互煎熬，不覺童顏暗中失。","縱有兒孫滿眼前，却成恩愛轉牽纏。","及乎精竭身枯朽，誰解教伊暫駐顏。","延年之道既無計，不免將身歸逝水。","但看古往聖賢人，幾箇解留身在世。","身在世，也有方，只爲時人誤度量。","競向山中尋草藥，伏鉛制汞點丹陽。","點丹陽，事迥別，須向坎中求赤血。","取來離位制陰精，配合調和有時節。","時節正，用媒人，金翁姹女結親姻。","金翁偏愛騎白虎，姹女常駕赤龍身。","虎來靜坐秋江裏，龍向潭中奮身起。","兩獸相逢戰一場，波浪奔騰如鼎沸。","黃婆丁老助威靈，撼動乾坤走神鬼。","須臾戰罷雲氣收，種箇玄珠在泥底。","從此根芽漸長成，隨時灌溉抱真精。","十月脫胎吞入口，忽覺凡身已有靈。","此箇事，世間稀，不是等閑人得知。","宿世若無仙骨分，容易如何得遇之。","金液丹，宜便煉，大都光景急如箭。","要取魚，須結筌，何不收心煉取鉛？","莫教燭被風吹滅，六道輪迴難怨天。","近來世上人多詐，盡著布衣稱道者。","問他金木是何般，噤口不言如害啞。","却云服氣與休糧，別有門庭道路長。","豈不見陰君破迷歌裏說，太乙含真法最強。","莫怪言詞太狂劣，只爲時人難鑒別。","惟君心與我心同，方敢傾心與君說。"]', '["玉走金飞兩曜忙，始闻花發又秋霜。","徒誇籛壽千年歲，也是云中一電光。","一電光，何太疾，百年都来三万日。","其间寒暑互煎熬，不覺童顏暗中失。","縱有兒孫满眼前，却成恩愛轉牽纏。","及乎精竭身枯朽，誰解教伊暫駐顏。","延年之道既無計，不免將身归逝水。","但看古往聖賢人，幾箇解留身在世。","身在世，也有方，只爲时人誤度量。","競向山中尋草藥，伏鉛制汞点丹陽。","点丹陽，事迥別，須向坎中求赤血。","取来離位制陰精，配合調和有时節。","时節正，用媒人，金翁姹女結親姻。","金翁偏愛騎白虎，姹女常駕赤龙身。","虎来静坐秋江裏，龙向潭中奮身起。","兩獸相逢戰一場，波浪奔腾如鼎沸。","黄婆丁老助威靈，撼动乾坤走神鬼。","須臾戰罷云氣收，種箇玄珠在泥底。","從此根芽漸长成，隨时灌溉抱真精。","十月脫胎吞入口，忽覺凡身已有靈。","此箇事，世间稀，不是等闲人得知。","宿世若無仙骨分，容易如何得遇之。","金液丹，宜便煉，大都光景急如箭。","要取鱼，須結筌，何不收心煉取鉛？","莫教燭被风吹滅，六道輪迴难怨天。","近来世上人多詐，尽著布衣稱道者。","问他金木是何般，噤口不言如害啞。","却云服氣與休糧，別有门庭道路长。","豈不见陰君破迷歌裏说，太乙含真法最強。","莫怪言词太狂劣，只爲时人难鑒別。","惟君心與我心同，方敢傾心與君说。"]', '诗', 'shi', '', NULL, '寄白龍洞劉道人 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf23be31-cf66-4eab-9d99-c2083b6074bd', '贈喬二郎', '贈喬二郎', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["與君相見皇都裏，陶陶動便經年醉。","醉中往往愛藏真，亦不爲他名與利。","勸君休戀浮華榮，直須奔走煙霞程。","煙霞欲去如何去，先須肘後飛金晶。","金晶飛到上宮裏，上宮下宮通光明。","當時玉汞涓涓生，奔歸元海如雷聲。","從此夫妻相際會，歡娛踴躍情無外。","水火都來兩半間，卦候翻成地天泰。","一浮一沈陽煉陰，陰盡方知此理深。","到底根元是何物，分明只是水中金。","喬公喬公急下手，莫逐烏飛兼兔走。","何如脩煉作真人，塵世浮生終不久。","人道長生沒得來，自古至今有有有。"]', '["與君相见皇都裏，陶陶动便經年醉。","醉中往往愛藏真，亦不爲他名與利。","勸君休戀浮华榮，直須奔走煙霞程。","煙霞欲去如何去，先須肘後飞金晶。","金晶飞到上宮裏，上宮下宮通光明。","當时玉汞涓涓生，奔归元海如雷声。","從此夫妻相際會，歡娛踴躍情無外。","水火都来兩半间，卦候翻成地天泰。","一浮一沈陽煉陰，陰尽方知此理深。","到底根元是何物，分明只是水中金。","喬公喬公急下手，莫逐烏飞兼兔走。","何如脩煉作真人，塵世浮生終不久。","人道长生沒得来，自古至今有有有。"]', '诗', 'shi', '', NULL, '贈喬二郎 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2dd1c88-68a7-4054-bd14-edafb3798407', '鄂渚悟道歌', '鄂渚悟道歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["縱橫天際爲閑客，時遇季秋重陽節。","陰雲一布徧長空，膏澤連綿滋萬物。","因雨泥滑門不出，忽聞鄰舍語丹術。","試問鄰公可相傳，一言許肯更無難。","數篇奇怪文入手，一夜挑燈讀不了。","曉來日早纔看畢，不覺自醉如恍惚。","恍惚之中見有物，狀如日輪明突屼。","自言便是丹砂精，宜向鼎中烹凡質。","凡質本來不化真，化真須得真中物。","不用鉛，不用汞，還丹須向爐中種。","玄中之玄號真鉛，及至用鉛還不用。","或名龍，或名虎，或號嬰兒幷姹女。","丹砂一粒名千般，一中有一爲丹母。","火莫燃，水莫凍，修之煉之須珍重。","直待虎歗折顛峰，驪龍奪得玄珠弄。","龍吞玄寶忽昇飛，飛龍被我捉來騎。","一翥上朝歸碧落，碧落廣闊無東西。","無曉無夜無年月，無寒無暑無四時。","自從修到無爲地，始覺奇之又怪之。"]', '["縱橫天際爲闲客，时遇季秋重陽節。","陰云一布徧长空，膏澤連綿滋万物。","因雨泥滑门不出，忽闻鄰舍語丹術。","試问鄰公可相傳，一言許肯更無难。","數篇奇怪文入手，一夜挑灯读不了。","晓来日早纔看畢，不覺自醉如恍惚。","恍惚之中见有物，狀如日輪明突屼。","自言便是丹砂精，宜向鼎中烹凡質。","凡質本来不化真，化真須得真中物。","不用鉛，不用汞，還丹須向爐中種。","玄中之玄號真鉛，及至用鉛還不用。","或名龙，或名虎，或號嬰兒幷姹女。","丹砂一粒名千般，一中有一爲丹母。","火莫燃，水莫凍，修之煉之須珍重。","直待虎歗折顛峰，驪龙奪得玄珠弄。","龙吞玄寶忽昇飞，飞龙被我捉来騎。","一翥上朝归碧落，碧落廣闊無东西。","無晓無夜無年月，無寒無暑無四时。","自從修到無爲地，始覺奇之又怪之。"]', '诗', 'shi', '', NULL, '鄂渚悟道歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87142ad-8126-4f60-9f10-31346bceddd3', '又記', '又記', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["數載樂幽幽，欲逃寒暑逼。","不求名與利，猶恐身心役。","苦志慕黃庭，慇懃求道跡。","陰功暗心修，善行長日積。","世路果逢師，時人皆不識。","我師機行密，懷量性孤僻。","解把五行移，能將四象易。","傳余造化門，始悟希夷則。","服取兩般真，從頭路端的。","烹煎日月壺，不離乾坤側。","至道眼前觀，得之元咫尺。","真空空不空，真色色非色。","推倒玉葫蘆，迸出黃金液。","緊把赤龍頭，猛將驪珠吸。","吞歸臟腑中，奪得神仙力。","妙號一黍珠，延年千萬億。","同途聽我吟，與道相親益。","未曉真黃芽，徒勞遊紫陌。","把住赤烏魂，突出銀蟾魄。","未省此中玄，常流容易測。","三天應有路，九地終無厄。","守道且藏愚，忘機要混迹。","羣生莫相輕，已是蓬萊客。"]', '["數載乐幽幽，欲逃寒暑逼。","不求名與利，猶恐身心役。","苦志慕黄庭，慇懃求道跡。","陰功暗心修，善行长日積。","世路果逢師，时人皆不識。","我師機行密，懷量性孤僻。","解把五行移，能將四象易。","傳余造化门，始悟希夷則。","服取兩般真，從头路端的。","烹煎日月壺，不離乾坤側。","至道眼前观，得之元咫尺。","真空空不空，真色色非色。","推倒玉葫蘆，迸出黄金液。","緊把赤龙头，猛將驪珠吸。","吞归臟腑中，奪得神仙力。","妙號一黍珠，延年千万億。","同途听我吟，與道相親益。","未晓真黄芽，徒勞游紫陌。","把住赤烏魂，突出銀蟾魄。","未省此中玄，常流容易測。","三天應有路，九地終無厄。","守道且藏愚，忘機要混迹。","羣生莫相轻，已是蓬萊客。"]', '诗', 'shi', '', NULL, '又記 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1076a8a8-676e-46e7-a4bf-bc54597a6b17', '秘訣歌', '秘訣歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["求之不見，來即不見。","不見不見，君之素面。","火裏曾飛，水中亦見。","道路非遙，身心不戀。","又不知有返陰之龜，回陽之鴈。","遇即遇真人，達即達其神。","一萬二千甲子，這一壺流霞長春。","流霞流霞，本性一家。","飢餐日精，渴飲月華。","將甲子丁丑之歲，與君決破東門之大瓜。"]', '["求之不见，来即不见。","不见不见，君之素面。","火裏曾飞，水中亦见。","道路非遙，身心不戀。","又不知有返陰之龟，回陽之鴈。","遇即遇真人，達即達其神。","一万二千甲子，這一壺流霞长春。","流霞流霞，本性一家。","飢餐日精，渴饮月华。","將甲子丁丑之歲，與君決破东门之大瓜。"]', '诗', 'shi', '', NULL, '秘訣歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74099436-d234-4a4c-8b4e-f841ba404834', '勉牛生夏侯生', '勉牛生夏侯生', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["二秀才，二秀才兮非秀才，非秀才兮是仙才。","中華國裏親遭遇，仰面觀天笑眼開。","鶴形兮龜骨，龍吟兮虎顏。","我有至言相勸勉，願君兮勿猜勿猜。","但煦日吹月，嚥雨呵雷。","火寄冥宮，水濟丹臺。","金木交而土歸位，鉛汞分而丹露胎。","赤血換而白乳流，透九竅兮動百骸。","然然卷，然然舒，哀哀咍咍。","孩兒喘而不死，腹空虛兮長齋。","酬名利兮狂歌醉舞，酬富貴兮麻裰莎鞋。","甲子問時休記，看桑田變作黃埃。","青山白雲好居住，勸君歸去來兮歸去來。"]', '["二秀才，二秀才兮非秀才，非秀才兮是仙才。","中华国裏親遭遇，仰面观天笑眼开。","鹤形兮龟骨，龙吟兮虎顏。","我有至言相勸勉，願君兮勿猜勿猜。","但煦日吹月，嚥雨呵雷。","火寄冥宮，水濟丹台。","金木交而土归位，鉛汞分而丹露胎。","赤血換而白乳流，透九竅兮动百骸。","然然卷，然然舒，哀哀咍咍。","孩兒喘而不死，腹空虛兮长斋。","酬名利兮狂歌醉舞，酬富貴兮麻裰莎鞋。","甲子问时休記，看桑田变作黄埃。","青山白云好居住，勸君归去来兮归去来。"]', '诗', 'shi', '', NULL, '勉牛生夏侯生 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9503043-cc56-4eb9-acff-38e7ab244219', '題四明金鵝寺壁', '題四明金鵝寺壁', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["方丈有門出不鑰，見箇山童露雙脚。","問伊方丈何寂寥，道是虛空也不著。","聞此語，何欣欣，主翁豈是尋常人。","我來謁見不得見，謁心耿耿生埃塵。","歸去也，波浩渺，路入蓬萊山杳杳。","相思一上石樓時，雪晴海闊千峰曉。"]', '["方丈有门出不鑰，见箇山童露雙脚。","问伊方丈何寂寥，道是虛空也不著。","闻此語，何欣欣，主翁豈是尋常人。","我来謁见不得见，謁心耿耿生埃塵。","归去也，波浩渺，路入蓬萊山杳杳。","相思一上石楼时，雪晴海闊千峰晓。"]', '诗', 'shi', '', NULL, '題四明金鵝寺壁 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e454df-52ed-40a5-b0e6-a60519605ada', '谷神歌', '谷神歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["我有一腹空谷虛，言之道有又還無。","言之無兮不可捨，言之有兮不可居。","谷兮谷兮太玄妙，神兮神兮真大道。","保之守之不死名，修之煉之仙人號。","神得一以靈，谷得一以盈。","若人能守一，只此是長生。","本不遠離，身還不見。","煉之功若成，自然凡骨變。","谷神不死玄牝門，出入綿綿道若存。","修煉還須夜半子，河車般載上崑崙。","龍又吟，虎又歗，風雲際會黃婆叫。","火中姹女正含嬌，回觀水底嬰兒俏。","嬰兒姹女見黃婆，兒女相逢兩意和。","金殿玉堂門十二，金翁木母正來過。","重門過後牢關鎖，點檢斗牛先下火。","進火消陰始一陽，千歲仙桃初結果。","曲江東岸金烏飛，西岸清光玉兔輝。","烏兔走歸峰頂上，爐中姹女脫青衣。","脫却青衣露素體，嬰兒領入重幃裏。","十月情濃產一男，說道長生永不死。","勸君煉，勸君修，谷神不死此中求。","此中悟取玄微處，與君白日登瀛洲。"]', '["我有一腹空谷虛，言之道有又還無。","言之無兮不可捨，言之有兮不可居。","谷兮谷兮太玄妙，神兮神兮真大道。","保之守之不死名，修之煉之仙人號。","神得一以靈，谷得一以盈。","若人能守一，只此是长生。","本不远離，身還不见。","煉之功若成，自然凡骨变。","谷神不死玄牝门，出入綿綿道若存。","修煉還須夜半子，河车般載上崑崙。","龙又吟，虎又歗，风云際會黄婆叫。","火中姹女正含嬌，回观水底嬰兒俏。","嬰兒姹女见黄婆，兒女相逢兩意和。","金殿玉堂门十二，金翁木母正来過。","重门過後牢关鎖，点檢斗牛先下火。","進火消陰始一陽，千歲仙桃初結果。","曲江东岸金烏飞，西岸清光玉兔輝。","烏兔走归峰頂上，爐中姹女脫青衣。","脫却青衣露素體，嬰兒領入重幃裏。","十月情濃產一男，说道长生永不死。","勸君煉，勸君修，谷神不死此中求。","此中悟取玄微处，與君白日登瀛洲。"]', '诗', 'shi', '', NULL, '谷神歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a83d27e-3b6b-486c-938c-5524b9feb210', '修身訣', '修身訣', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["人命急如線，上下來往速如箭。","認得是元神，子後午前須至煉。","隨意出，隨意入，天地三才人得一。","既得一，勿遺失，失了永求無一物。","堪歎荒郊塚墓中，自古滅亡不知屈。"]', '["人命急如線，上下来往速如箭。","認得是元神，子後午前須至煉。","隨意出，隨意入，天地三才人得一。","既得一，勿遺失，失了永求無一物。","堪歎荒郊塚墓中，自古滅亡不知屈。"]', '诗', 'shi', '', NULL, '修身訣 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df16656e-76ed-4489-b152-ba12a11e560c', '長短句', '长短句', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["落魄且落魄，夜宿鄉村，朝遊城郭。","閑來無事玩青山，因來街市貨丹藥。","賣得錢，不算度，酤美酒，自斟酌。","醉後吟哦動鬼神，任意日頭向西落。"]', '["落魄且落魄，夜宿乡村，朝游城郭。","闲来無事玩青山，因来街市貨丹藥。","賣得錢，不算度，酤美酒，自斟酌。","醉後吟哦动鬼神，任意日头向西落。"]', '诗', 'shi', '', NULL, '長短句 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e404fba9-8b04-4b8d-9caf-325368542176', '直指大丹歌', '直指大丹歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三清宮殿隱崑巔，日月光浮起紫煙。","池沼泓泓翻玉液，樓臺疊疊運靈泉。","青龍乘火鉛爲汞，白虎騰波汞作鉛。","欲得坎男求匹偶，須憑離女結因緣。","黃婆設盡千般計，金鼎開成一朵蓮。","列女擎烏當左畔，將軍戴兔鎮西邊。","黑龜却伏紅爐下，朱雀還棲華閣前。","然後澄神窺見影，三周功就駕雲軿。"]', '["三清宮殿隐崑巔，日月光浮起紫煙。","池沼泓泓翻玉液，楼台叠叠運靈泉。","青龙乘火鉛爲汞，白虎腾波汞作鉛。","欲得坎男求匹偶，須憑離女結因緣。","黄婆設尽千般計，金鼎开成一朵蓮。","列女擎烏當左畔，將軍戴兔鎮西邊。","黑龟却伏紅爐下，朱雀還棲华閣前。","然後澄神窺见影，三周功就駕云軿。"]', '诗', 'shi', '', NULL, '直指大丹歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5efc3567-b3a9-49ee-940d-dd52aab171ac', '漁父詞一十八首 入定', '漁父词一十八首 入定', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["閉目藏真神思凝，杳冥中裏見吾宗。","無邊畔，迥朦朧，玄景觀來覺盡空。"]', '["閉目藏真神思凝，杳冥中裏见吾宗。","無邊畔，迥朦朧，玄景观来覺尽空。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 入定 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6eca962-dd06-464f-bec6-061b9c2ceaab', '漁父詞一十八首 初九', '漁父词一十八首 初九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["大道從來屬自然，空堂寂坐守機關。","三田寶，鎮長存，赤帝分明坐廣寒。"]', '["大道從来屬自然，空堂寂坐守機关。","三田寶，鎮长存，赤帝分明坐廣寒。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 初九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c736477-969b-4410-b4bb-db3e85a99a88', '漁父詞一十八首 玄用', '漁父词一十八首 玄用', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["日月交加曉夜奔，崑崙頂上定乾坤。","真鏡裏，實堪論，靉靉紅霞曉寂門。"]', '["日月交加晓夜奔，崑崙頂上定乾坤。","真镜裏，實堪論，靉靉紅霞晓寂门。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 玄用 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96f42a7-0a9e-4192-a934-39b0407eaa3b', '漁父詞一十八首 神効', '漁父词一十八首 神効', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["恍惚擒來得自然，偷他造化在其間。","神鼎內，火烹煎，盡歷陰陽結作丹。"]', '["恍惚擒来得自然，偷他造化在其间。","神鼎內，火烹煎，尽歷陰陽結作丹。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 神効 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15628e2-507c-4a38-8f7a-5f3b4920cd4a', '漁父詞一十八首 沐浴', '漁父词一十八首 沐浴', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["卯酉門中作用時，赤龍時蘸玉清池。","雲薄薄，雨微微，看取妖容露雪肌。"]', '["卯酉门中作用时，赤龙时蘸玉清池。","云薄薄，雨微微，看取妖容露雪肌。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 沐浴 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b13aea1b-3495-4bfa-a664-c662601a2884', '漁父詞一十八首 延壽', '漁父词一十八首 延壽', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["子午常餐日月精，玄關門戶啓還扃。","長如此，過平生，且把陰陽子細烹。"]', '["子午常餐日月精，玄关门戶啓還扃。","长如此，過平生，且把陰陽子細烹。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 延壽 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2145939-0bea-43b1-8b54-5321f04f53d6', '漁父詞一十八首 瑞鼎', '漁父词一十八首 瑞鼎', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["會合都從戊巳家，金鉛水汞莫須誇。","只此物，結丹砂，反覆陰陽色轉華。"]', '["會合都從戊巳家，金鉛水汞莫須誇。","只此物，結丹砂，反覆陰陽色轉华。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 瑞鼎 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f217a9f4-3305-4bc0-9e9d-cfc24d6c7535', '漁父詞一十八首 活得', '漁父词一十八首 活得', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["位立三才屬五行，陰陽合處便相生。","龍飛踴，虎狌獰，吐箇神珠各戰爭。"]', '["位立三才屬五行，陰陽合处便相生。","龙飞踴，虎狌獰，吐箇神珠各戰爭。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 活得 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151c0b94-0ed6-4fb0-bec8-4265385d5df4', '漁父詞一十八首 燦爛', '漁父词一十八首 燦爛', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["四象分明八卦周，乾坤男女論綢繆。","交會處，更嬌羞，轉覺情深玉體柔。"]', '["四象分明八卦周，乾坤男女論綢繆。","交會处，更嬌羞，轉覺情深玉體柔。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 燦爛 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d13a0c-b850-4e6f-ad75-fcb990e49db9', '漁父詞一十八首 鍊質', '漁父词一十八首 鍊質', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["運本還元於此尋，周流金鼎虎龍吟。","身不老，俗難侵，貌返童顏骨變金。"]', '["運本還元於此尋，周流金鼎虎龙吟。","身不老，俗难侵，貌返童顏骨变金。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 鍊質 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fcbf10-8f56-44b1-8735-1055fdab6a45', '漁父詞一十八首 神異', '漁父词一十八首 神異', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["還返初成立變童，瑞蓮開處色輝紅。","金鼎內，迥朦朧，換骨添筋處處通。"]', '["還返初成立变童，瑞蓮开处色輝紅。","金鼎內，迥朦朧，換骨添筋处处通。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 神異 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdfca188-646d-4d0f-8689-d1d25735da77', '漁父詞一十八首 知路', '漁父词一十八首 知路', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["那箇仙經述此方，參同大易顯陰陽。","須窮取，莫顛狂，會者名高道自昌。"]', '["那箇仙經述此方，參同大易显陰陽。","須窮取，莫顛狂，會者名高道自昌。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 知路 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2824a01b-48a4-4802-a83c-2e95dd658545', '漁父詞一十八首 朝帝', '漁父词一十八首 朝帝', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九轉功成數盡乾，開爐撥鼎見金丹。","餐餌了，別塵寰，足躡青雲突上天。"]', '["九轉功成數尽乾，开爐撥鼎见金丹。","餐餌了，別塵寰，足躡青云突上天。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 朝帝 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06af775-14c8-4ae2-b36e-7edd4a7e2e99', '漁父詞一十八首 方契理', '漁父词一十八首 方契理', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["舉世人生何所依，不求自己更求誰。","絕嗜慾，斷貪癡，莫把神明暗裏欺。"]', '["舉世人生何所依，不求自己更求誰。","絕嗜慾，斷貪癡，莫把神明暗裏欺。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 方契理 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17a2a6e-ab55-48e8-8eb1-5ad69cc4adda', '漁父詞一十八首 自無憂', '漁父词一十八首 自無憂', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["學道初從此處修，斷除貪愛別嬌柔。","長守靜，處深幽，服氣餐霞飽即休。"]', '["学道初從此处修，斷除貪愛別嬌柔。","长守静，处深幽，服氣餐霞飽即休。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 自無憂 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9103ca1-d1e8-4180-9bf2-42bcf2a044b7', '漁父詞一十八首 作甚物', '漁父词一十八首 作甚物', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["貪貴貪榮逐利名，追遊醉後戀歡情。","年不永，代君驚，一報身終那裏生。"]', '["貪貴貪榮逐利名，追游醉後戀歡情。","年不永，代君驚，一報身終那裏生。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 作甚物 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01415e00-b0bf-4abb-865a-0737f6d8253e', '漁父詞一十八首 疾瞥地', '漁父词一十八首 疾瞥地', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["萬劫千生得箇人，須知先世種來因。","速覺悟，出迷津，莫使輪迴受苦辛。"]', '["万劫千生得箇人，須知先世種来因。","速覺悟，出迷津，莫使輪迴受苦辛。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 疾瞥地 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6f9139-a6ca-4125-80d5-a539e710c5f8', '漁父詞一十八首 常自在', '漁父词一十八首 常自在', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["閉目尋真真自歸，玄珠一顆出輝輝。","終日翫，莫拋離，免使閻王遣使追。"]', '["閉目尋真真自归，玄珠一顆出輝輝。","終日翫，莫拋離，免使閻王遣使追。"]', '诗', 'shi', '', NULL, '漁父詞一十八首 常自在 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107374f2-b31c-4465-9771-ab27c350ebbc', '口占', '口占', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["非神亦非仙，非術亦非幻。","天地有終窮，桑田幾遷變。","身固非我有，財亦何足戀。","曷不從吾遊，騎鯨騰汗漫。"]', '["非神亦非仙，非術亦非幻。","天地有終窮，桑田幾遷变。","身固非我有，財亦何足戀。","曷不從吾游，騎鯨腾汗漫。"]', '诗', 'shi', '', NULL, '口占 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f5fe31-5618-4684-952e-d11dc835a94d', '敲爻歌', '敲爻歌', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["漢終唐國飄蓬客，所以敲爻不可測。","縱橫逆順沒遮欄，靜則無爲動是色。","也飲酒，也食肉，守定胭花斷淫慾。","行歌唱詠胭粉詞，持戒酒肉常充腹。","色是藥，酒是祿，酒色之中無拘束。","只因花酒悞長生，飲酒帶花神鬼哭。","不破戒，不犯淫，破戒真如性即沈。","犯淫壞失長生寶，得者須由道力人。","道力人，真散漢，酒是良朋花是伴。","花街柳巷覓真人，真人只在花街翫。","摘花戴飲長生酒，景裏無爲道自昌。","一任羣迷多笑怪，仙花仙酒是仙鄉。","到此鄉，非常客，姹女嬰兒生喜樂。","洞中常採四時花，時花結就長生藥。","長生藥，採花心，花蘂層層豔麗春。","時人不達花中理，一訣天機直萬金。","謝天地，感虛空，得遇仙師是祖宗。","附耳低言玄妙旨，提上蓬萊第一峰。","第一峰，是仙物，惟產金花生恍惚。","口口相傳不記文，須得靈根骨髓堅。","堅骨髓，煉靈根，片片桃花洞裏春。","七七白虎雙雙養，八八青龍總一斤。","真父母，送元宮，木母金公性本溫。","十二宮中蟾魄現，時時地魄降天魂。","鉛初就，汞初生，玉爐金鼎未經烹。","一夫一婦同天地，一男一女合乾坤。","庚要生，甲要生，生甲生庚道始萌。","拔取天根並地髓，白雪黃芽自長成。","鉛亦生，汞亦生，生汞生鉛一處烹。","烹煉不是精和液，天地乾坤日月精。","黃婆匹配得團圓，時刻無差口付傳。","八卦三元全藉汞，五行四象豈離鉛。","鉛生汞，汞生鉛，奪得乾坤造化權。","杳杳冥冥生恍惚，恍恍惚惚結成團。","性須空，意要專，莫遣猨猴取次攀。","花露初開切忌觸，鎖居上釜勿抽添。","玉爐中，文火爍，十二時中惟守一。","此時黃道會陰陽，三性元宮無漏泄。","氣若行，真火煉，莫使玄珠離寶殿。","加添火候切防危，初九潛龍不可煉。","消息火，刀圭變，大地黃芽都長遍。","五行數內一陽生，二十四氣排珠宴。","火足數，藥方成，便有龍吟虎嘯聲。","三鉛只得一鉛就，金果仙芽未現形。","再安爐，重立鼎，跨虎乘龍離凡境。","日精纔現月華凝，二八相交在壬丙。","龍汞結，虎鉛成，咫尺蓬萊秪一程。","坤鉛乾汞金丹祖，龍鉛虎汞最通靈。","達此理，道方成，三萬神龍護水晶。","守時定日明符刻，專心惟在意虔誠。","黑鉛過，採清真，一陣交鋒定太平。","三車搬運珍珠寶，送歸寶藏自通靈。","天神佑，地祇迎，混合乾坤日月精。","虎嘯一聲龍出窟，鸞飛鳳舞出金城。","硃砂配，水銀停，一派紅霞列太清。","鉛池迸出金光現，汞火流珠入帝京。","龍虎媾，外持盈，走聖飛靈在寶瓶。","一時辰內金丹就，上朝金闕紫雲生。","仙桃熟，摘取餌，萬化來朝天地喜。","齋戒等候一陽生，便進周天參同理。","參同理，煉金丹，水火薰蒸透百關。","養胎十月神丹結，男子懷胎豈等閑。","內丹成，外丹就，內外相接和諧偶。","結成一塊紫金丸，變化飛騰天地久。","丹入腹，非尋常，陰陽剝盡化純陽。","飛昇羽化三清客，名遂功成達上蒼。","三清客，駕瓊輿，跨鳳騰霄入太虛。","似此逍遙多快樂，遨遊三界最清奇。","太虛之上修真士，朗朗圓成一物無。","一物無，唯顯道，五方透出真人貌。","仙童仙女彩雲迎，五明宮內傳真誥。","傳真誥，話幽情，只是真鉛煉汞精。","聲聞緣覺冰消散，外道修羅縮項驚。","點枯骨，立成形，信道天梯似掌平。","九祖先靈得超脫，誰羨繁華貴與榮。","尋烈士，覓賢才，同安爐鼎化凡胎。","若是慳財幷惜寶，千萬神仙不肯來。","修真士，不妄說，妄說一句天公折。","萬劫塵沙道不成，七竅眼睛皆迸血。","貧窮子，發誓切，待把凡流盡提接。","同越蓬萊仙會中，凡景煎熬無了歇。","塵世短，更思量，洞裏乾坤日月長。","堅志苦心三二載，百千萬劫壽彌疆。","達聖道，顯真常，虎兕刀兵更不傷。","水火蛟龍無損害，拍手天宮笑一場。","這些功，真奇妙，分付與人誰肯要。","愚徒死戀色和財，所以神仙不肯召。","真至道，不擇人，豈論高低富與貧。","且饒帝子共王孫，須去繁華銼銳分。","嗔不除，憨不改，墮入輪迴生死海。","堆金積玉滿山川，神仙冷笑應不采。","名非貴，道極尊，聖聖賢賢顯子孫。","腰間跨玉騎驕馬，瞥見如同隙裏塵。","隙裏塵，石中火，何在留心爲久計。","苦苦煎熬喚不回，奪利爭名如鼎沸。","如鼎沸，永沈淪，失道迷真業所根。","有人平却心頭棘，便把天機說與君。","命要傳，性要悟，入聖超凡由汝做。","三清路上少人行，畜類門前爭入去。","報賢良，休慕顧，性命機關須守護。","若還缺一不芳菲，執著波查應失路。","只修性，不修命，此是修行第一病。","只修祖性不修丹，萬劫陰靈難入聖。","達命宗，迷祖性，恰以鑑容無寶鏡。","壽同天地一愚夫，權物家財無主柄。","性命雙修玄又玄，海底洪波駕法船。","生擒活捉蛟龍首，始知匠手不虛傳。"]', '["漢終唐国飄蓬客，所以敲爻不可測。","縱橫逆順沒遮欄，静則無爲动是色。","也饮酒，也食肉，守定胭花斷淫慾。","行歌唱詠胭粉词，持戒酒肉常充腹。","色是藥，酒是祿，酒色之中無拘束。","只因花酒悞长生，饮酒带花神鬼哭。","不破戒，不犯淫，破戒真如性即沈。","犯淫壞失长生寶，得者須由道力人。","道力人，真散漢，酒是良朋花是伴。","花街柳巷覓真人，真人只在花街翫。","摘花戴饮长生酒，景裏無爲道自昌。","一任羣迷多笑怪，仙花仙酒是仙乡。","到此乡，非常客，姹女嬰兒生喜乐。","洞中常採四时花，时花結就长生藥。","长生藥，採花心，花蘂層層豔丽春。","时人不達花中理，一訣天機直万金。","謝天地，感虛空，得遇仙師是祖宗。","附耳低言玄妙旨，提上蓬萊第一峰。","第一峰，是仙物，惟產金花生恍惚。","口口相傳不記文，須得靈根骨髓堅。","堅骨髓，煉靈根，片片桃花洞裏春。","七七白虎雙雙養，八八青龙總一斤。","真父母，送元宮，木母金公性本溫。","十二宮中蟾魄現，时时地魄降天魂。","鉛初就，汞初生，玉爐金鼎未經烹。","一夫一婦同天地，一男一女合乾坤。","庚要生，甲要生，生甲生庚道始萌。","拔取天根並地髓，白雪黄芽自长成。","鉛亦生，汞亦生，生汞生鉛一处烹。","烹煉不是精和液，天地乾坤日月精。","黄婆匹配得團圓，时刻無差口付傳。","八卦三元全藉汞，五行四象豈離鉛。","鉛生汞，汞生鉛，奪得乾坤造化權。","杳杳冥冥生恍惚，恍恍惚惚結成團。","性須空，意要專，莫遣猨猴取次攀。","花露初开切忌觸，鎖居上釜勿抽添。","玉爐中，文火爍，十二时中惟守一。","此时黄道會陰陽，三性元宮無漏泄。","氣若行，真火煉，莫使玄珠離寶殿。","加添火候切防危，初九潛龙不可煉。","消息火，刀圭变，大地黄芽都长遍。","五行數內一陽生，二十四氣排珠宴。","火足數，藥方成，便有龙吟虎嘯声。","三鉛只得一鉛就，金果仙芽未現形。","再安爐，重立鼎，跨虎乘龙離凡境。","日精纔現月华凝，二八相交在壬丙。","龙汞結，虎鉛成，咫尺蓬萊秪一程。","坤鉛乾汞金丹祖，龙鉛虎汞最通靈。","達此理，道方成，三万神龙護水晶。","守时定日明符刻，專心惟在意虔誠。","黑鉛過，採清真，一陣交鋒定太平。","三车搬運珍珠寶，送归寶藏自通靈。","天神佑，地祇迎，混合乾坤日月精。","虎嘯一声龙出窟，鸾飞鳳舞出金城。","硃砂配，水銀停，一派紅霞列太清。","鉛池迸出金光現，汞火流珠入帝京。","龙虎媾，外持盈，走聖飞靈在寶瓶。","一时辰內金丹就，上朝金闕紫云生。","仙桃熟，摘取餌，万化来朝天地喜。","斋戒等候一陽生，便進周天參同理。","參同理，煉金丹，水火薰蒸透百关。","養胎十月神丹結，男子懷胎豈等闲。","內丹成，外丹就，內外相接和諧偶。","結成一塊紫金丸，变化飞腾天地久。","丹入腹，非尋常，陰陽剝尽化純陽。","飞昇羽化三清客，名遂功成達上蒼。","三清客，駕瓊輿，跨鳳腾霄入太虛。","似此逍遙多快乐，遨游三界最清奇。","太虛之上修真士，朗朗圓成一物無。","一物無，唯显道，五方透出真人貌。","仙童仙女彩云迎，五明宮內傳真誥。","傳真誥，話幽情，只是真鉛煉汞精。","声闻緣覺冰消散，外道修羅縮項驚。","点枯骨，立成形，信道天梯似掌平。","九祖先靈得超脫，誰羨繁华貴與榮。","尋烈士，覓賢才，同安爐鼎化凡胎。","若是慳財幷惜寶，千万神仙不肯来。","修真士，不妄说，妄说一句天公折。","万劫塵沙道不成，七竅眼睛皆迸血。","貧窮子，發誓切，待把凡流尽提接。","同越蓬萊仙會中，凡景煎熬無了歇。","塵世短，更思量，洞裏乾坤日月长。","堅志苦心三二載，百千万劫壽彌疆。","達聖道，显真常，虎兕刀兵更不傷。","水火蛟龙無損害，拍手天宮笑一場。","這些功，真奇妙，分付與人誰肯要。","愚徒死戀色和財，所以神仙不肯召。","真至道，不擇人，豈論高低富與貧。","且饒帝子共王孫，須去繁华銼銳分。","嗔不除，憨不改，墮入輪迴生死海。","堆金積玉满山川，神仙冷笑應不采。","名非貴，道極尊，聖聖賢賢显子孫。","腰间跨玉騎驕马，瞥见如同隙裏塵。","隙裏塵，石中火，何在留心爲久計。","苦苦煎熬喚不回，奪利爭名如鼎沸。","如鼎沸，永沈淪，失道迷真業所根。","有人平却心头棘，便把天機说與君。","命要傳，性要悟，入聖超凡由汝做。","三清路上少人行，畜類门前爭入去。","報賢良，休慕顧，性命機关須守護。","若還缺一不芳菲，執著波查應失路。","只修性，不修命，此是修行第一病。","只修祖性不修丹，万劫陰靈难入聖。","達命宗，迷祖性，恰以鑑容無寶镜。","壽同天地一愚夫，權物家財無主柄。","性命雙修玄又玄，海底洪波駕法船。","生擒活捉蛟龙首，始知匠手不虛傳。"]', '诗', 'shi', '', NULL, '敲爻歌 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa9a412-f929-4b90-b539-ed7b915316b0', '三字訣', '三字訣', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["這箇道，非常道。","性命根，生死竅。","說著醜，行着妙。","人人憎，箇箇笑。","大關鍵，在顛倒。","莫厭穢，莫計較。","得他來，立見効。","地天泰，爲朕兆。","口對口，竅對竅。","吞入腹，自知道。","藥苗新，先天兆。","審眉間，行逆道。","滓質物，自繼紹。","二者餘，方絕妙。","要行持，令人叫。","氣要堅，神莫耗。","若不行，空老耄。","認得真，老還少。","不知音，莫語要。","此兒法，合大道。","精氣神，不老藥。","靜裏全，明中報。","乘鳳鸞，聽天詔。"]', '["這箇道，非常道。","性命根，生死竅。","说著醜，行着妙。","人人憎，箇箇笑。","大关鍵，在顛倒。","莫厭穢，莫計較。","得他来，立见効。","地天泰，爲朕兆。","口对口，竅对竅。","吞入腹，自知道。","藥苗新，先天兆。","審眉间，行逆道。","滓質物，自繼紹。","二者餘，方絕妙。","要行持，令人叫。","氣要堅，神莫耗。","若不行，空老耄。","認得真，老還少。","不知音，莫語要。","此兒法，合大道。","精氣神，不老藥。","静裏全，明中報。","乘鳳鸾，听天詔。"]', '诗', 'shi', '', NULL, '三字訣 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3eff3b2-57f9-4d08-bc14-4607508083c0', '百字碑', '百字碑', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["養氣忘言守，降心爲不爲。","動靜知宗祖，無事更尋誰。","真常須應物，應物要不迷。","不迷性自住，性住氣自回。","氣回丹自結，壺中配坎離。","陰陽生返復，普化一聲雷。","白雲朝頂上，甘露灑須彌。","自飲長生酒，逍遙誰得知。","坐聽無弦曲，明通造化機。","都來二十句，端的上天梯。"]', '["養氣忘言守，降心爲不爲。","动静知宗祖，無事更尋誰。","真常須應物，應物要不迷。","不迷性自住，性住氣自回。","氣回丹自結，壺中配坎離。","陰陽生返复，普化一声雷。","白云朝頂上，甘露灑須彌。","自饮长生酒，逍遙誰得知。","坐听無弦曲，明通造化機。","都来二十句，端的上天梯。"]', '诗', 'shi', '', NULL, '百字碑 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3afa4d47-2cb3-4bb2-a184-ce2006703663', '句', '句', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["莫道神仙無學處，古今多少上昇人。"]', '["莫道神仙無学处，古今多少上昇人。"]', '诗', 'shi', '', NULL, '句 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffe443f-f1de-4969-9518-6eebd13b1344', '四言詩', '四言诗', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["取金之精，合石之液。","列爲夫婦，結爲魂魄。","一體混沌，兩精感激。","河車覆載，鼎候無忒。","洪鑪烈火，烘燄翕赫。","煙未及黔，燄不假碧。","如畜扶桑，若藏霹靂。","姹女氣索，嬰兒聲寂。","透出兩儀，麗於四極。","壁立幾多，馬馳一驛。","宛其死矣，適然從革。","惡黜善遷，情回性易。","紫色內達，赤芒外射。","熠若火生，乍疑血滴。","號曰中環，退藏於密。","霧散五內，川流百脉。","骨變金植，顏駐玉澤。","陽德乃敷，陰功□積。","南宮度名，北斗落籍。"]', '["取金之精，合石之液。","列爲夫婦，結爲魂魄。","一體混沌，兩精感激。","河车覆載，鼎候無忒。","洪鑪烈火，烘燄翕赫。","煙未及黔，燄不假碧。","如畜扶桑，若藏霹靂。","姹女氣索，嬰兒声寂。","透出兩儀，丽於四極。","壁立幾多，马驰一驛。","宛其死矣，適然從革。","惡黜善遷，情回性易。","紫色內達，赤芒外射。","熠若火生，乍疑血滴。","號曰中环，退藏於密。","霧散五內，川流百脉。","骨变金植，顏駐玉澤。","陽德乃敷，陰功□積。","南宮度名，北斗落籍。"]', '诗', 'shi', '', NULL, '四言詩 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5002b25f-e00e-4fa1-bcd1-9436b6db5381', '留詩 一', '留诗 一', '596bb185-2411-4b1f-ab5f-6b67900295b4', '唐', '["昔在禹餘天，還依太上家。","忝以掌仙錄，去來乘煙霞。","暫下宛利城，渺然思金華。","自此非久住，雲上登香車。"]', '["昔在禹餘天，還依太上家。","忝以掌仙錄，去来乘煙霞。","暫下宛利城，渺然思金华。","自此非久住，云上登香车。"]', '诗', 'shi', '', NULL, '留詩 一 葉法善 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab93604f-f6a2-41a6-9e00-c83ad4155e26', '留詩 二', '留诗 二', '596bb185-2411-4b1f-ab5f-6b67900295b4', '唐', '["適向人間世，時復濟蒼生。","度人初行滿，輔國亦功成。","但念清微樂，誰忻下界榮。","門人好住此，翛然雲上征。"]', '["適向人间世，时复濟蒼生。","度人初行满，輔国亦功成。","但念清微乐，誰忻下界榮。","门人好住此，翛然云上征。"]', '诗', 'shi', '', NULL, '留詩 二 葉法善 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6858d5-204f-4875-8d42-55cab0fd33c9', '留詩 三', '留诗 三', '596bb185-2411-4b1f-ab5f-6b67900295b4', '唐', '["退仙時此地，去俗久爲榮。","今日登雲天，歸真遊上清。","泥丸空示世，騰舉不爲名。","爲報學仙者，知余朝玉京。"]', '["退仙时此地，去俗久爲榮。","今日登云天，归真游上清。","泥丸空示世，腾舉不爲名。","爲報学仙者，知余朝玉京。"]', '诗', 'shi', '', NULL, '留詩 三 葉法善 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d66d362-9b84-4205-9a92-3f6bfcde3652', '題登真洞', '題登真洞', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["修成金骨鍊歸真，洞鎖遺蹤不計春。","野草謾隨青嶺秀，閑花長對白雲新。","風搖翠篠敲寒玉，水激丹砂走素鱗。","自是神仙多變異，肯教踪跡掩紅塵。"]', '["修成金骨鍊归真，洞鎖遺蹤不計春。","野草謾隨青嶺秀，闲花长对白云新。","风搖翠篠敲寒玉，水激丹砂走素鱗。","自是神仙多变異，肯教踪跡掩紅塵。"]', '诗', 'shi', '', NULL, '題登真洞 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9226587f-a96d-47bc-9f9c-ae25a980b1b0', '負薪行', '負薪行', '83235b2a-8d01-4748-a1b7-01a047fd3010', '唐', '["負薪朝出賣，沽酒日西歸。","路人莫問歸何處，穿入白雲行翠微。"]', '["負薪朝出賣，沽酒日西归。","路人莫问归何处，穿入白云行翠微。"]', '诗', 'shi', '', NULL, '負薪行 許宣平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b2a680-a0ea-4b8f-854f-ac41947e560b', '庵壁題詩', '庵壁題诗', '83235b2a-8d01-4748-a1b7-01a047fd3010', '唐', '["隱居三十載，石室南山巔。","靜夜翫明月，清朝飲碧泉。","樵人歌壠上，谷鳥戲巖前。","樂矣不知老，都忘甲子年。"]', '["隐居三十載，石室南山巔。","静夜翫明月，清朝饮碧泉。","樵人歌壠上，谷鸟戲巖前。","乐矣不知老，都忘甲子年。"]', '诗', 'shi', '', NULL, '庵壁題詩 許宣平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e8f06c-6d43-4d1d-b073-cdb8214cb35d', '見李白詩又吟', '见李白诗又吟', '83235b2a-8d01-4748-a1b7-01a047fd3010', '唐', '["一池荷葉衣無盡，兩畝黃精食有餘。","又被人來尋討著，移庵不免更深居。"]', '["一池荷葉衣無尽，兩畝黄精食有餘。","又被人来尋討著，移庵不免更深居。"]', '诗', 'shi', '', NULL, '見李白詩又吟 許宣平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a6e032-6de3-44dc-b16c-b7d38d821080', '題壁', '題壁', '45ee775b-46ba-42f4-8dfd-0f856a527eb8', '唐', '["蜀路南行，燕師北至。","本擬白日昇天，且看黑龍飲渭。"]', '["蜀路南行，燕師北至。","本擬白日昇天，且看黑龙饮渭。"]', '诗', 'shi', '', NULL, '題壁 成真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e03f381-62b5-48de-99aa-572d9629291f', '對趙潁歌', '对趙潁歌', 'a2592a3b-d343-4edf-8160-56336972d6ab', '唐', '["人間幾日變桑田，誰識神仙洞裏天。","短促共知有□異，且須歡醉在生前。"]', '["人间幾日变桑田，誰識神仙洞裏天。","短促共知有□異，且須歡醉在生前。"]', '诗', 'shi', '', NULL, '對趙潁歌 朱子真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd774aec-85c1-4488-8fd4-9ae3257a32e6', '兜玄國懷歸詩', '兜玄国懷归诗', '450ce0d6-37e5-41c4-86ec-b9cea239522d', '唐', '["風軟景和煦，異香馥林塘。","登高一長望，信美非吾鄉。"]', '["风軟景和煦，異香馥林塘。","登高一长望，信美非吾乡。"]', '诗', 'shi', '', NULL, '兜玄國懷歸詩 申歡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1420e11e-7cfa-4092-a930-014a636b0f06', '題壁', '題壁', '3fb0213e-efec-47fe-9ed8-c6a95f466947', '唐', '["燕市人皆去，函關馬不歸。","若逢山下鬼，環上繫羅衣。"]', '["燕市人皆去，函关马不归。","若逢山下鬼，环上繫羅衣。"]', '诗', 'shi', '', NULL, '題壁 李遐周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e121ad9-27e9-4ad3-b2ac-6d674c5bb356', '遺簡詩 一', '遺簡诗 一', '871bae77-c7c2-434e-8f26-25b519527ac5', '唐', '["生我於虛，置我於無。","至精爲神，元氣爲軀。","散陽爲明，合陰爲符。","形爲灰土，神爲仙居。","衆垢將畢，萬事永除。"]', '["生我於虛，置我於無。","至精爲神，元氣爲軀。","散陽爲明，合陰爲符。","形爲灰土，神爲仙居。","衆垢將畢，万事永除。"]', '诗', 'shi', '', NULL, '遺簡詩 一 趙惠宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef9f438-750b-43ae-811a-6b67176e5d51', '遺簡詩 二', '遺簡诗 二', '871bae77-c7c2-434e-8f26-25b519527ac5', '唐', '["吾駕時馬，日月爲衛。","洞耀九霄，上謁天帝。","明明我衆，及我門人。","僞道養形，真道養神。","懋哉懋哉，餘無所陳。"]', '["吾駕时马，日月爲衛。","洞耀九霄，上謁天帝。","明明我衆，及我门人。","僞道養形，真道養神。","懋哉懋哉，餘無所陳。"]', '诗', 'shi', '', NULL, '遺簡詩 二 趙惠宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c064ff-2294-421d-83dd-4e4655dfca6a', '遇蓮葉二客詩', '遇蓮葉二客诗', '7a442fd8-06dc-45e0-9d0b-41d1fc1bd5ae', '唐', '["得飲攄公酒，復登攄公舟。","便得神體清，超遙曠無憂。"]', '["得饮攄公酒，复登攄公舟。","便得神體清，超遙曠無憂。"]', '诗', 'shi', '', NULL, '遇蓮葉二客詩 欒清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ff7fd7-7a17-4456-9f2a-7aed1bc35ad5', '蓮葉二客詩 一', '蓮葉二客诗 一', '7a442fd8-06dc-45e0-9d0b-41d1fc1bd5ae', '唐', '["行時雲作伴，坐即酒爲侶。","腹以元化充，衣將雲霞補。","紂虐與堯仁，可惜皆朽腐。"]', '["行时云作伴，坐即酒爲侶。","腹以元化充，衣將云霞補。","紂虐與堯仁，可惜皆朽腐。"]', '诗', 'shi', '', NULL, '蓮葉二客詩 一 欒清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6b778f-3db6-4e59-92eb-72a3e25af15e', '蓮葉二客詩 二', '蓮葉二客诗 二', '7a442fd8-06dc-45e0-9d0b-41d1fc1bd5ae', '唐', '["檝櫂無所假，超然信萍查。","朝浮旭日輝，夕蔭清月華。","營營功業人，朽骨成泥沙。"]', '["檝櫂無所假，超然信萍查。","朝浮旭日輝，夕蔭清月华。","營營功業人，朽骨成泥沙。"]', '诗', 'shi', '', NULL, '蓮葉二客詩 二 欒清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9694be4-7005-4bd1-9c46-b84c6674d617', '言志', '言志', '41d545bd-2c84-463b-bc6e-aeb73772469f', '唐', '["青山雲水窟，此地是吾家。","後夜流瓊液，凌晨咀綘霞。","琴彈碧玉調，鍊煉白硃砂。","寶鼎存金虎，元田養白鴉。","一瓢藏世界，三尺斬妖邪。","解造逡巡酒，能開頃刻花。","有人能學我，同去看仙葩。"]', '["青山云水窟，此地是吾家。","後夜流瓊液，凌晨咀綘霞。","琴彈碧玉調，鍊煉白硃砂。","寶鼎存金虎，元田養白鴉。","一瓢藏世界，三尺斬妖邪。","解造逡巡酒，能开頃刻花。","有人能学我，同去看仙葩。"]', '诗', 'shi', '', NULL, '言志 韓湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67279752-e2cc-476e-ac21-982b676df73e', '荅從叔愈', '荅從叔愈', '41d545bd-2c84-463b-bc6e-aeb73772469f', '唐', '["舉世都爲名利醉，伊予獨向道中醒。","他時定是飛昇去，衝破秋空一點青。"]', '["舉世都爲名利醉，伊予独向道中醒。","他时定是飞昇去，衝破秋空一点青。"]', '诗', 'shi', '', NULL, '荅從叔愈 韓湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba7295a-ca56-4e31-adc0-b0cab16f8e9b', '題院詩', '題院诗', 'de147700-de06-4c7b-afd5-ba1730effa1e', '唐', '["帖裏大還丹，多年色不移。","前宵盜喫却，今日碧空飛。","慙媿深珍重，珍重鄧天師。","他年煉得藥，留著與內芝。","吾師知此術，速煉莫爲遲。","三清專相待，大羅的有期。"]', '["帖裏大還丹，多年色不移。","前宵盜喫却，今日碧空飞。","慙媿深珍重，珍重鄧天師。","他年煉得藥，留著與內芝。","吾師知此術，速煉莫爲遲。","三清專相待，大羅的有期。"]', '诗', 'shi', '', NULL, '題院詩 侯道華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6130942b-218b-4584-a334-049c2950f64b', '贈樊夫人詩', '贈樊夫人诗', '61a052d7-24dc-4f91-8ab0-89f377ed1871', '唐', '["向爲胡越猶懷想，況遇天仙隔錦屏。","儻若玉京朝會去，願隨鸞鶴入青冥。"]', '["向爲胡越猶懷想，況遇天仙隔錦屏。","儻若玉京朝會去，願隨鸾鹤入青冥。"]', '诗', 'shi', '', NULL, '贈樊夫人詩 裴航 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d8d73a-2b9f-444c-8c67-d803f262e04e', '樊夫人荅裴航', '樊夫人荅裴航', '61a052d7-24dc-4f91-8ab0-89f377ed1871', '唐', '["一飲瓊漿百感生，玄霜擣盡見雲英。","藍橋便是神仙窟，何必崎嶇上玉清。"]', '["一饮瓊漿百感生，玄霜擣尽见云英。","藍橋便是神仙窟，何必崎嶇上玉清。"]', '诗', 'shi', '', NULL, '樊夫人荅裴航 裴航 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a7b498-a5e4-495e-a8d9-34e64ecd9a09', '題長安酒肆壁三絕句 一', '題长安酒肆壁三絕句 一', '9c34759e-1711-4083-89f7-ce0be63dabc4', '唐', '["坐臥常攜酒一壺，不教雙眼識皇都。","乾坤許大無名姓，疎散人中一丈夫。"]', '["坐臥常携酒一壺，不教雙眼識皇都。","乾坤許大無名姓，疎散人中一丈夫。"]', '诗', 'shi', '', NULL, '題長安酒肆壁三絕句 一 鍾離權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2685b5a6-273d-4d98-ac61-d8a17a4ff331', '題長安酒肆壁三絕句 二', '題长安酒肆壁三絕句 二', '9c34759e-1711-4083-89f7-ce0be63dabc4', '唐', '["得道高僧不易逢，幾時歸去願相從。","自言住處連滄海，別是蓬萊第一峯。"]', '["得道高僧不易逢，幾时归去願相從。","自言住处連滄海，別是蓬萊第一峯。"]', '诗', 'shi', '', NULL, '題長安酒肆壁三絕句 二 鍾離權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de51a0d-3b6c-46ec-b032-b85de06e27f8', '題長安酒肆壁三絕句 三', '題长安酒肆壁三絕句 三', '9c34759e-1711-4083-89f7-ce0be63dabc4', '唐', '["莫厭追歡笑語頻，尋思離亂好傷神。","閑來屈指從頭數，得見清平有幾人。"]', '["莫厭追歡笑語頻，尋思離亂好傷神。","闲来屈指從头數，得见清平有幾人。"]', '诗', 'shi', '', NULL, '題長安酒肆壁三絕句 三 鍾離權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e43db3-3677-4065-80af-2ff7b563df6b', '贈呂洞賓', '贈呂洞賓', '9c34759e-1711-4083-89f7-ce0be63dabc4', '唐', '["知君幸有英靈骨，所以教君心恍惚。","含元殿上水晶宮，分明指出神仙窟。","大丈夫，遇真訣，須要執持心猛烈。","五行匹配自刀圭，執取龜蛇顛倒訣。","三尸神，須打徹，進退天機明六甲。","知此三要萬神歸，來駕火龍離九闕。","九九道至成真日，三界四府朝元節。","氣翱翔兮神烜赫，蓬萊便是吾家宅。","羣仙會飲天樂喧，雙童引入昇玄客。","道心不退故傳君，立誓約言親灑血。","逢人兮莫亂說，遇友兮不須訣。","莫怪頻發此言辭，輕慢必有陰司折。","執手相別意如何，今日爲君重作歌。","說盡千般玄妙理，未必君心信也麽。","子後分明說與汝，保惜吾言上大羅。"]', '["知君幸有英靈骨，所以教君心恍惚。","含元殿上水晶宮，分明指出神仙窟。","大丈夫，遇真訣，須要執持心猛烈。","五行匹配自刀圭，執取龟蛇顛倒訣。","三尸神，須打徹，進退天機明六甲。","知此三要万神归，来駕火龙離九闕。","九九道至成真日，三界四府朝元節。","氣翱翔兮神烜赫，蓬萊便是吾家宅。","羣仙會饮天乐喧，雙童引入昇玄客。","道心不退故傳君，立誓約言親灑血。","逢人兮莫亂说，遇友兮不須訣。","莫怪頻發此言辞，轻慢必有陰司折。","執手相別意如何，今日爲君重作歌。","说尽千般玄妙理，未必君心信也麽。","子後分明说與汝，保惜吾言上大羅。"]', '诗', 'shi', '', NULL, '贈呂洞賓 鍾離權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b77783c9-fc25-49f0-af73-3c89891edaea', '登杭州秦望山', '登杭州秦望山', '0eaef23b-5383-4be6-976a-41930add50dd', '唐', '["太乙初分何處尋，空留曆數變人心。","九天日月移朝暮，萬里山川換古今。","風動水光吞遠嶠，雨添嵐氣沒高林。","秦皇謾作驅山計，滄海茫茫轉更深。"]', '["太乙初分何处尋，空留曆數变人心。","九天日月移朝暮，万里山川換古今。","风动水光吞远嶠，雨添嵐氣沒高林。","秦皇謾作驱山計，滄海茫茫轉更深。"]', '诗', 'shi', '', NULL, '登杭州秦望山 馬湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f88b6f4-aabc-4198-9c66-a22ba210b374', '題龍興觀壁', '題龙兴观壁', '0eaef23b-5383-4be6-976a-41930add50dd', '唐', '["世有無窮事，生知遂百春。","問程方外路，宜是上清人。"]', '["世有無窮事，生知遂百春。","问程方外路，宜是上清人。"]', '诗', 'shi', '', NULL, '題龍興觀壁 馬湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36ed1fb-1d31-4f9f-858f-fd003ab9fb5f', '又詩一首', '又诗一首', '0eaef23b-5383-4be6-976a-41930add50dd', '唐', '["昔日曾隨魏伯陽，無端醉臥紫金牀。","東君謂我多情賴，罰向人間作酒狂。"]', '["昔日曾隨魏伯陽，無端醉臥紫金牀。","东君謂我多情賴，罰向人间作酒狂。"]', '诗', 'shi', '', NULL, '又詩一首 馬湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9f7620-35b9-4737-b3c9-87db3f0c2860', '又詩二首 一', '又诗二首 一', '0eaef23b-5383-4be6-976a-41930add50dd', '唐', '["省悟前非一息間，更拋閑事棄塵寰。","徒誇美酒如瓊液，休戀嬌娥似玉顏。","含笑謾教情面厚，多愁還使鬢毛斑。","雲中幸有堪歸路，無限青山是我山。"]', '["省悟前非一息间，更拋闲事棄塵寰。","徒誇美酒如瓊液，休戀嬌娥似玉顏。","含笑謾教情面厚，多愁還使鬢毛斑。","云中幸有堪归路，無限青山是我山。"]', '诗', 'shi', '', NULL, '又詩二首 一 馬湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c05631-ea67-4273-ba77-c77f78e60eed', '又詩二首 二', '又诗二首 二', '0eaef23b-5383-4be6-976a-41930add50dd', '唐', '["何用燒丹學駐顏，鬧非城市靜非山。","時人若覓長生藥，對景無心是大還。"]', '["何用燒丹学駐顏，鬧非城市静非山。","时人若覓长生藥，对景無心是大還。"]', '诗', 'shi', '', NULL, '又詩二首 二 馬湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0902eb-22cb-4639-b618-a5a83c4d8567', '題壁', '題壁', '09581af2-993e-48be-aa3b-0cfaa4e3aafc', '唐', '["爭那金烏何，頭上飛不住。","紅爐漫燒藥，玉顏安可駐。","今年花發枝，明年葉落樹。","不如且飲酒，莫管流年度。"]', '["爭那金烏何，头上飞不住。","紅爐漫燒藥，玉顏安可駐。","今年花發枝，明年葉落樹。","不如且饮酒，莫管流年度。"]', '诗', 'shi', '', NULL, '題壁 張辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2469960f-96e9-4ade-8e94-bcb666d30843', '上鹽城令述德詩', '上鹽城令述德诗', '09581af2-993e-48be-aa3b-0cfaa4e3aafc', '唐', '["門風常有蕙蘭馨，鼎族家傳霸國名。","容貌靜懸秋月彩，文章高振海濤聲。","訟堂無事調琴軫，郡閣何妨醉玉觥。","今日東漸橋下水，一條從此鎮常清。"]', '["门风常有蕙蘭馨，鼎族家傳霸国名。","容貌静懸秋月彩，文章高振海濤声。","訟堂無事調琴軫，郡閣何妨醉玉觥。","今日东漸橋下水，一條從此鎮常清。"]', '诗', 'shi', '', NULL, '上鹽城令述德詩 張辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c8d669-ff49-4b68-9104-1406c1ff9e02', '謝令學道詩', '謝令学道诗', '09581af2-993e-48be-aa3b-0cfaa4e3aafc', '唐', '["何用梯媒向外求，長生只合內中修。","莫言大道人難得，自是行心不到頭。"]', '["何用梯媒向外求，长生只合內中修。","莫言大道人难得，自是行心不到头。"]', '诗', 'shi', '', NULL, '謝令學道詩 張辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c16ee6-926f-4146-8d53-108011c822e0', '別令詩', '別令诗', '09581af2-993e-48be-aa3b-0cfaa4e3aafc', '唐', '["張辭張辭自不會，天下經書在腹內。","身即騰騰處世間，心即逍遙出天外。"]', '["張辞張辞自不會，天下經书在腹內。","身即腾腾处世间，心即逍遙出天外。"]', '诗', 'shi', '', NULL, '別令詩 張辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701b58d5-3979-4156-b90b-73dbe335718e', '贈吳生', '贈吳生', 'acf90c47-6941-46f1-b3bf-115cb645e559', '唐', '["露下瑤簪濕，雲生石室寒。","星壇鸞鶴舞，丹竈虎龍蟠。"]', '["露下瑤簪濕，云生石室寒。","星壇鸾鹤舞，丹竈虎龙蟠。"]', '诗', 'shi', '', NULL, '贈吳生 陸禹臣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24ae6f4-b533-4057-a1f4-06b01bd1c8b6', '丈人山詩', '丈人山诗', '176c1d7e-fd3f-45c8-bd37-8059878605a1', '唐', '["春凍曉韉露重，夜寒幽枕雲生。","豈是與山無素，丈人著帽相迎。"]', '["春凍晓韉露重，夜寒幽枕云生。","豈是與山無素，丈人著帽相迎。"]', '诗', 'shi', '', NULL, '丈人山詩 李真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151dddf6-9644-48e4-9970-e3bdc0b29293', '醉歌', '醉歌', 'de0bae5f-b041-4c9a-b5c7-82f46d0e3622', '唐', '["琴彈碧玉調，藥鍊白硃砂。","解醞頃刻酒，能開非時花。"]', '["琴彈碧玉調，藥鍊白硃砂。","解醞頃刻酒，能开非时花。"]', '诗', 'shi', '', NULL, '醉歌 殷七七 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae09fd4b-5a05-4f49-8baa-92b272ba133a', '陽春曲', '陽春曲', 'de0bae5f-b041-4c9a-b5c7-82f46d0e3622', '唐', '["愁見唱陽春，令人離腸結。","郎去未歸家，柳自飄香雪。"]', '["愁见唱陽春，令人離腸結。","郎去未归家，柳自飄香雪。"]', '诗', 'shi', '', NULL, '陽春曲 殷七七 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74692b7f-e682-449f-bd73-51a04358018f', '寄杜光庭', '寄杜光庭', 'e0bc30ed-3383-4216-93ec-2294e8af708f', '唐', '["試問朝中爲宰相，何如林下作神仙。","一壺美酒一爐藥，飽聽松風清晝眠。"]', '["試问朝中爲宰相，何如林下作神仙。","一壺美酒一爐藥，飽听松风清晝眠。"]', '诗', 'shi', '', NULL, '寄杜光庭 張令問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c4e70b-35d7-45c8-8977-9fdbce83f51f', '上昇歌', '上昇歌', '8e7e58b5-f520-4dab-bbc9-411be91b64d5', '唐', '["玉皇有詔登仙職，龍吐雲兮鳳著力。","眼前驀地見樓臺，異草奇花不可識。","我向大羅觀世界，世界即如指掌大。","當時不爲上昇忙，一時提向瀛洲賣。"]', '["玉皇有詔登仙職，龙吐云兮鳳著力。","眼前驀地见楼台，異草奇花不可識。","我向大羅观世界，世界即如指掌大。","當时不爲上昇忙，一时提向瀛洲賣。"]', '诗', 'shi', '', NULL, '上昇歌 吳涵虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22dc0b13-2b20-49aa-bd3b-4a3eab8282a0', '荅常學士', '荅常学士', '76c208d7-2b04-4c2b-ad27-ccd3cd9c3655', '唐', '["罷修儒業罷修真，養拙藏愚春復春。","到老不疎林裏鹿，平生難見日邊人。","洞桃深處千林錦，巖雪鋪時萬草新。","深謝名賢遠相訪，求聞難博鳳爲鄰。"]', '["罷修儒業罷修真，養拙藏愚春复春。","到老不疎林裏鹿，平生难见日邊人。","洞桃深处千林錦，巖雪鋪时万草新。","深謝名賢远相訪，求闻难博鳳爲鄰。"]', '诗', 'shi', '', NULL, '荅常學士 李夢符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08bc5154-ff91-4308-9b25-134908d248d4', '漁父引二首 一', '漁父引二首 一', '76c208d7-2b04-4c2b-ad27-ccd3cd9c3655', '唐', '["林寺鐘聲度遠灘，半輪殘月落山前。","徐徐撥櫂却歸灣，浪疊朝霞錦繡翻。"]', '["林寺鐘声度远灘，半輪殘月落山前。","徐徐撥櫂却归灣，浪叠朝霞錦繡翻。"]', '诗', 'shi', '', NULL, '漁父引二首 一 李夢符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9feb4c7d-1c88-44ab-8666-3cd1060909fa', '漁父引二首 二', '漁父引二首 二', '76c208d7-2b04-4c2b-ad27-ccd3cd9c3655', '唐', '["漁弟漁兄喜到來，波官賽却坐江隈。","椰榆杓子木瘤杯，爛煮鱸魚滿案堆。"]', '["漁弟漁兄喜到来，波官賽却坐江隈。","椰榆杓子木瘤杯，爛煮鱸鱼满案堆。"]', '诗', 'shi', '', NULL, '漁父引二首 二 李夢符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('911e1eb6-40c9-45f9-825c-abf101e0a5de', '察考取狀荅', '察考取狀荅', '76c208d7-2b04-4c2b-ad27-ccd3cd9c3655', '唐', '["插花飲酒何妨事，樵唱漁歌不礙時。"]', '["插花饮酒何妨事，樵唱漁歌不礙时。"]', '诗', 'shi', '', NULL, '察考取狀荅 李夢符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3fa47cf-53a2-4ebd-b366-acfe05c8557d', '荅高安宰', '荅高安宰', 'fb120291-0e57-490b-a71a-2b85cf6afff2', '唐', '["何須問我道成時，紫府清都自有期。","手握藥苗人不識，體含金骨俗爭知。"]', '["何須问我道成时，紫府清都自有期。","手握藥苗人不識，體含金骨俗爭知。"]', '诗', 'shi', '', NULL, '荅高安宰 沈廷瑞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59daa901-97e9-402c-88d1-e872aecdf66a', '贈僧昭瑩', '贈僧昭瑩', 'fb120291-0e57-490b-a71a-2b85cf6afff2', '唐', '["南北東西路，人生會不無。","早曾依閣皂，又却上玄都。","雲片隨天闊，泉聲落石孤。","何期早相遇，樂共煮菖蒲。"]', '["南北东西路，人生會不無。","早曾依閣皂，又却上玄都。","云片隨天闊，泉声落石孤。","何期早相遇，乐共煮菖蒲。"]', '诗', 'shi', '', NULL, '贈僧昭瑩 沈廷瑞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19c256fd-7ab9-46ee-9820-d2130d4f1a90', '寄袁州陳智周', '寄袁州陳智周', 'fb120291-0e57-490b-a71a-2b85cf6afff2', '唐', '["名山相別後，別後會難期。","金鼎銷紅日，丹田老紫芝。","訪君雖有路，懷我豈無詩。","休羨繁華事，百年能幾時。"]', '["名山相別後，別後會难期。","金鼎銷紅日，丹田老紫芝。","訪君雖有路，懷我豈無诗。","休羨繁华事，百年能幾时。"]', '诗', 'shi', '', NULL, '寄袁州陳智周 沈廷瑞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38023806-187f-4330-ab5e-c855138f78cc', '壟穴遺詩', '壟穴遺诗', 'fb120291-0e57-490b-a71a-2b85cf6afff2', '唐', '["虛勞營殯玉山前，殯後那知已脫蟬。","應是元神歸洞府，更無遺魄在黃泉。","靈臺已得修真訣，塵世空留悟道篇。","堪歎浮生今古事，北邙山下草芊芊。"]', '["虛勞營殯玉山前，殯後那知已脫蟬。","應是元神归洞府，更無遺魄在黄泉。","靈台已得修真訣，塵世空留悟道篇。","堪歎浮生今古事，北邙山下草芊芊。"]', '诗', 'shi', '', NULL, '壟穴遺詩 沈廷瑞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13265525-1365-43f6-805d-2a9ca38051e5', '大言詩', '大言诗', '3209fc43-e9af-4674-ad02-308f77f87d79', '唐', '["線作長江扇作天，靸鞵拋向海東邊。","蓬萊信道無多路，只在譚生拄杖前。"]', '["線作长江扇作天，靸鞵拋向海东邊。","蓬萊信道無多路，只在譚生拄杖前。"]', '诗', 'shi', '', NULL, '大言詩 譚峭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ab7f2b-ca9d-4dd1-8dd8-868ed3b897f7', '大言詩', '大言诗', '3209fc43-e9af-4674-ad02-308f77f87d79', '唐', '["線大長江扇大天，屐鞋抛在海東邉。","世間多少閒蟲豸，盡在郯生柱杖前。"]', '["線大长江扇大天，屐鞋抛在海东邉。","世间多少閒蟲豸，尽在郯生柱杖前。"]', '诗', 'shi', '', NULL, '大言詩 譚峭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f178f79d-49d0-4718-ab4b-0766bebff106', '句', '句', '3209fc43-e9af-4674-ad02-308f77f87d79', '唐', '["雲外星霜如走電，世間娛樂似拋磚。"]', '["云外星霜如走電，世间娛乐似拋磚。"]', '诗', 'shi', '', NULL, '句 譚峭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3187489-b4b9-463e-90cd-6a1a6b886bb6', '望江南詞詠鼓', '望江南词詠鼓', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["江南鼓，梭肚兩頭欒。","釘著不知侵骨髓，打來只是沒心肝，空腹被人謾。"]', '["江南鼓，梭肚兩头欒。","釘著不知侵骨髓，打来只是沒心肝，空腹被人謾。"]', '诗', 'shi', '', NULL, '望江南詞詠鼓 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11384e72-8496-49fb-9e75-bb9b7e5f75ae', '題茶陵縣門', '題茶陵縣门', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["茶陵一道好長街，兩畔栽柳不栽槐。","夜後不聞更漏鼓，只聽鎚芒織草鞋。"]', '["茶陵一道好长街，兩畔栽柳不栽槐。","夜後不闻更漏鼓，只听鎚芒织草鞋。"]', '诗', 'shi', '', NULL, '題茶陵縣門 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('770a3699-aaaf-4d82-9365-ea98a7e11eb4', '題酒樓壁', '題酒楼壁', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["此生生在此生先，何事從玄不復玄。","已在淮南雞犬後，而今便到玉皇前。"]', '["此生生在此生先，何事從玄不复玄。","已在淮南雞犬後，而今便到玉皇前。"]', '诗', 'shi', '', NULL, '題酒樓壁 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82428546-4568-4fc9-a9d2-904138ce7b1e', '題遊帷觀真君殿後', '題游帷观真君殿後', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["日日祥雲瑞氣連，儂家應作大神仙。","筆頭灑起風雷力，劒下驅馳造化權。","更與戎夷添禮樂，永教胡虜絕烽煙。","列仙功業只如此，直上三清第一天。"]', '["日日祥云瑞氣連，儂家應作大神仙。","笔头灑起风雷力，劒下驱驰造化權。","更與戎夷添禮乐，永教胡虜絕烽煙。","列仙功業只如此，直上三清第一天。"]', '诗', 'shi', '', NULL, '題遊帷觀真君殿後 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('757347e0-66d3-4dca-aec4-27375416c9e0', '留題閣皂觀', '留題閣皂观', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["花洞門前吠似雷，險聲流斷俗塵埃。","雨噴山脚毒龍起，月照松梢孤鶴回。","蘿幕秋高添碧翠，畫簾時捲到樓臺。","兩壇詩客何年去，去後門關更不開。"]', '["花洞门前吠似雷，險声流斷俗塵埃。","雨噴山脚毒龙起，月照松梢孤鹤回。","蘿幕秋高添碧翠，畫簾时捲到楼台。","兩壇诗客何年去，去後门关更不开。"]', '诗', 'shi', '', NULL, '留題閣皂觀 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5311947c-cc06-45fa-a3b9-6903b6ba3196', '湖南闖齋吟', '湖南闖斋吟', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["誰人能識白元君，上士由來盡見聞。","避世早空南火宅，植田高種北山雲。","雞能抱卵心常聽，蟬到成形殼自分。","學取大羅些子術，免教松下作孤墳。"]', '["誰人能識白元君，上士由来尽见闻。","避世早空南火宅，植田高種北山云。","雞能抱卵心常听，蟬到成形殼自分。","学取大羅些子術，免教松下作孤墳。"]', '诗', 'shi', '', NULL, '湖南闖齋吟 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029cd8ac-1e4f-49b9-a96f-44f386cef74b', '游溧陽霞泉寺限白字', '游溧陽霞泉寺限白字', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["近枕吳溪與越峰，前朝恩賜雲泉額。","竹林晴見鴈塔高，石室曾棲幾禪伯。","荒碑字沒莓苔深，古池香泛荷花白。","客有經年別故林，落日啼猨情脉脉。"]', '["近枕吳溪與越峰，前朝恩賜云泉額。","竹林晴见鴈塔高，石室曾棲幾禪伯。","荒碑字沒莓苔深，古池香泛荷花白。","客有經年別故林，落日啼猨情脉脉。"]', '诗', 'shi', '', NULL, '游溧陽霞泉寺限白字 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f01eac0-5610-492a-96fc-92724fefeb05', '幽棲觀', '幽棲观', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["仙翁上昇去，丹井寄晴壑。","山色接天台，湖光照寥廓。","玉洞絕無人，老檜猶棲鶴。","我欲掣青蛇，他時沖碧落。"]', '["仙翁上昇去，丹井寄晴壑。","山色接天台，湖光照寥廓。","玉洞絕無人，老檜猶棲鹤。","我欲掣青蛇，他时沖碧落。"]', '诗', 'shi', '', NULL, '幽棲觀 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e344500b-6f32-40d0-a033-8ec28957d131', '題茅山觀', '題茅山观', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["嘗恨清風千載鬱，洞天今得恣遊遨。","松楸一色古壇靜，鸞鶴不來青漢高。","茅氏井寒丹已化，玄宗碑斷夢仍勞。","分明有箇長生路，休向紅塵歎二毛。"]', '["嘗恨清风千載鬱，洞天今得恣游遨。","松楸一色古壇静，鸾鹤不来青漢高。","茅氏井寒丹已化，玄宗碑斷梦仍勞。","分明有箇长生路，休向紅塵歎二毛。"]', '诗', 'shi', '', NULL, '題茅山觀 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb75de9-d138-49e1-b555-aa47f02d6c93', '題扇', '題扇', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["哦吟但寫胸中妙，飲酒能忘身後名。","但願長閑有詩酒，一溪風月共清明。"]', '["哦吟但寫胸中妙，饮酒能忘身後名。","但願长闲有诗酒，一溪风月共清明。"]', '诗', 'shi', '', NULL, '題扇 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ab3503-da82-4e82-8f94-eaff0d5c5748', '上徐舍人鉉', '上徐舍人鉉', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["幾宵煙月鎖樓臺，欲寄侯門薦禰才。","滿面塵埃人不識，謾隨流水出山來。"]', '["幾宵煙月鎖楼台，欲寄侯门薦禰才。","满面塵埃人不識，謾隨流水出山来。"]', '诗', 'shi', '', NULL, '上徐舍人鉉 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8acf6436-7fa8-4831-b6a4-643280964e1f', '句', '句', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["道既學不得，仙從何處來？臥久似慵伸雪項，立遲猶未整霜衣。"]', '["道既学不得，仙從何处来？臥久似慵伸雪項，立遲猶未整霜衣。"]', '诗', 'shi', '', NULL, '句 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ee1fb5-a686-4bc9-bf8d-831e5753a700', '醉吟', '醉吟', 'b1b6af52-4c6c-4790-b410-8ba504db70c6', '唐', '["閬苑花前是醉鄉，踏翻王母九霞觴。","羣仙拍手嫌輕薄，謫向人間作酒狂。"]', '["閬苑花前是醉乡，踏翻王母九霞觴。","羣仙拍手嫌轻薄，謫向人间作酒狂。"]', '诗', 'shi', '', NULL, '醉吟 許碏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d45e348-8d73-492c-9bb5-f861401edfc3', '題南嶽招仙觀壁上', '題南嶽招仙观壁上', 'b1b6af52-4c6c-4790-b410-8ba504db70c6', '唐', '["洪鑪烹鍛人性命，器用不同分皆定。","妖精鬼魅鬬神通，只自干邪不干正。","黃口小兒初學行，唯知日月東西生。","還爲萬靈威聖力，移月在南日在北。","玉爲玉兮石是石，蘊棄深泥終不易。","鄧通餓死嚴陵貧，帝王豈是無人力。","丈夫未達莫相侵，攀龍附鳳捐精神。"]', '["洪鑪烹鍛人性命，器用不同分皆定。","妖精鬼魅鬬神通，只自干邪不干正。","黄口小兒初学行，唯知日月东西生。","還爲万靈威聖力，移月在南日在北。","玉爲玉兮石是石，蘊棄深泥終不易。","鄧通餓死嚴陵貧，帝王豈是無人力。","丈夫未達莫相侵，攀龙附鳳捐精神。"]', '诗', 'shi', '', NULL, '題南嶽招仙觀壁上 許碏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af4e1b7-02c6-44e2-b16e-08300d1adbbe', '武陵春色', '武陵春色', '13238663-39e9-43eb-ac89-61b06b239419', '唐', '["武陵春色好，十二酒家樓。","大醉方回首，逢人不舉頭。","是非都不采，名利混然休。","戴箇星冠子，浮沈逐世流。"]', '["武陵春色好，十二酒家楼。","大醉方回首，逢人不舉头。","是非都不采，名利混然休。","戴箇星冠子，浮沈逐世流。"]', '诗', 'shi', '', NULL, '武陵春色 張白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f95c75-54d3-4704-9de9-dba4496547f4', '贈酒店崔氏', '贈酒店崔氏', '13238663-39e9-43eb-ac89-61b06b239419', '唐', '["武陵城裏崔家酒，地上應無天上有。","南遊道士飲一斗，臥向白雲深洞口。"]', '["武陵城裏崔家酒，地上應無天上有。","南游道士饮一斗，臥向白云深洞口。"]', '诗', 'shi', '', NULL, '贈酒店崔氏 張白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7498f96-bf20-487e-8848-e869dcedc134', '哭陸先生', '哭陸先生', '13238663-39e9-43eb-ac89-61b06b239419', '唐', '["六親慟哭還復蘇，我笑先生淚箇無。","脫履定歸天上去，空墳留入武陵圖。"]', '["六親慟哭還复蘇，我笑先生泪箇無。","脫履定归天上去，空墳留入武陵圖。"]', '诗', 'shi', '', NULL, '哭陸先生 張白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7428746-e5a0-4882-8a85-b76b89f1c015', '市中狂吟', '市中狂吟', 'e195ea7f-e2c4-4758-8b70-fe09e3a4f892', '唐', '["一間茅屋，尚自修治。","任狂風吹，連簷破碎。","枓栱斜欹，看著倒也。","牆壁作散土一堆，主人翁永不來歸。"]', '["一间茅屋，尚自修治。","任狂风吹，連簷破碎。","枓栱斜欹，看著倒也。","牆壁作散土一堆，主人翁永不来归。"]', '诗', 'shi', '', NULL, '市中狂吟 段穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf1aab6d-94f2-469f-8748-f42fba97aea9', '詩', '诗', 'c5960ebd-4307-436d-9a40-fe85545c25a8', '唐', '["常欲棲山島，閑眠玉洞寒。","丹哥時引舞，來去跨雲鸞。"]', '["常欲棲山島，闲眠玉洞寒。","丹哥时引舞，来去跨云鸾。"]', '诗', 'shi', '', NULL, '詩 趙自然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb6044a-62c2-43ca-b244-76bee822f232', '大丹詩四首 一', '大丹诗四首 一', 'be6f2e10-bc7d-4bdc-b30b-8fc24e78a0ac', '唐', '["混沌未分我獨存，包含四象立乾坤。","還丹須向此中覓，得此方爲至妙門。"]', '["混沌未分我独存，包含四象立乾坤。","還丹須向此中覓，得此方爲至妙门。"]', '诗', 'shi', '', NULL, '大丹詩四首 一 李浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755328d6-8ae0-495e-ae31-0377b3f8f6fc', '大丹詩四首 二', '大丹诗四首 二', 'be6f2e10-bc7d-4bdc-b30b-8fc24e78a0ac', '唐', '["煮石烹金煉太元，神仙不肯等閑傳。","人能認得其中理，奪盡乾坤造化權。"]', '["煮石烹金煉太元，神仙不肯等闲傳。","人能認得其中理，奪尽乾坤造化權。"]', '诗', 'shi', '', NULL, '大丹詩四首 二 李浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b1b651-8200-4b28-b666-edfe638460cb', '大丹詩四首 三', '大丹诗四首 三', 'be6f2e10-bc7d-4bdc-b30b-8fc24e78a0ac', '唐', '["百首荒辭義亦深，因傳同道決疑心。","華池本是真神水，神水元來是白金。"]', '["百首荒辞義亦深，因傳同道決疑心。","华池本是真神水，神水元来是白金。"]', '诗', 'shi', '', NULL, '大丹詩四首 三 李浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae12a93d-7147-4aa8-a375-1dad3b24a46c', '大丹詩四首 四', '大丹诗四首 四', 'be6f2e10-bc7d-4bdc-b30b-8fc24e78a0ac', '唐', '["取將白金爲鼎器，鼎成潛伏汞來侵。","汞入金鼎終年盡，產出靈砂似太陰。"]', '["取將白金爲鼎器，鼎成潛伏汞来侵。","汞入金鼎終年尽，產出靈砂似太陰。"]', '诗', 'shi', '', NULL, '大丹詩四首 四 李浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01c75d6-9182-4429-8e42-1ab52d7e45a5', '自吟', '自吟', '45bcf246-b21e-4571-b912-bd61b12e5428', '唐', '["曾見秦皇架石橋，海神忙迫漲驚潮。","蓬萊隔海雖難到，直上三清却不遙。"]', '["曾见秦皇架石橋，海神忙迫漲驚潮。","蓬萊隔海雖难到，直上三清却不遙。"]', '诗', 'shi', '', NULL, '自吟 徐釣者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b3c234-7cd9-4ab4-a001-4d57fa62c592', '踏歌', '踏歌', '8e3fbb7c-b6b9-44e6-8398-8693990db2e5', '唐', '["踏歌踏歌藍采和，世界能幾何。","紅顏三春樹，流年一擲梭。","古人混混去不返，今人紛紛來更多。","朝騎鸞鳳到碧落，暮見桑田生白波。","長景明暉在空際，金銀宮闕高嵯峨。"]', '["踏歌踏歌藍采和，世界能幾何。","紅顏三春樹，流年一擲梭。","古人混混去不返，今人紛紛来更多。","朝騎鸾鳳到碧落，暮见桑田生白波。","长景明暉在空際，金銀宮闕高嵯峨。"]', '诗', 'shi', '', NULL, '踏歌 藍采和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bbe42bc-0412-46ec-b8e1-a58ae1f4d95e', '同沈恭子遊虎丘寺有作', '同沈恭子游虎丘寺有作', '1b35c21d-a64a-4c88-8712-e4f1dfabbbe6', '唐', '["我本長殷周，遭罹歷秦漢。","四瀆與五嶽，名山盡幽竄。","及此寰區中，始有近峰翫。","近峰何鬱鬱，平湖渺瀰漫。","吟俯川之陰，步上山之岸。","山川共澄澈，光彩交凌亂。","白雲蓊欲歸，青松忽消半。","客去川島靜，人來山鳥散。","谷深中見日，崖幽曉非旦。","聞子盛遊遨，風流足詞翰。","嘉茲好松石，一言常累嘆。","勿謂余鬼神，忻君共幽贊。"]', '["我本长殷周，遭罹歷秦漢。","四瀆與五嶽，名山尽幽竄。","及此寰區中，始有近峰翫。","近峰何鬱鬱，平湖渺瀰漫。","吟俯川之陰，步上山之岸。","山川共澄澈，光彩交凌亂。","白云蓊欲归，青松忽消半。","客去川島静，人来山鸟散。","谷深中见日，崖幽晓非旦。","闻子盛游遨，风流足词翰。","嘉茲好松石，一言常累嘆。","勿謂余鬼神，忻君共幽贊。"]', '诗', 'shi', '', NULL, '同沈恭子遊虎丘寺有作 清遠道士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e11e9ac-3f88-4891-903f-1fa15b16e46f', '遊春臺詩 一', '游春台诗 一', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["玉幢亘碧虛，此乃真人居。","裴回仍未進，邪省猶難除。"]', '["玉幢亘碧虛，此乃真人居。","裴回仍未進，邪省猶难除。"]', '诗', 'shi', '', NULL, '遊春臺詩 一 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc2a766e-12b5-48b0-a013-cb7b703e87a6', '遊春臺詩 二', '游春台诗 二', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["日落煙水黯，驪珠色豈昏。","寒光射萬里，霜縞遍千門。"]', '["日落煙水黯，驪珠色豈昏。","寒光射万里，霜縞遍千门。"]', '诗', 'shi', '', NULL, '遊春臺詩 二 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5ac119-58ff-4416-85f7-3e5cc6d77e46', '遊春臺詩 三', '游春台诗 三', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["玉魄東方開，嫦娥逐影來。","洗心兼滌目，怳若遊春臺。"]', '["玉魄东方开，嫦娥逐影来。","洗心兼滌目，怳若游春台。"]', '诗', 'shi', '', NULL, '遊春臺詩 三 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64069405-dd7d-4745-b1c1-9cef66185a84', '遊春臺詩 四', '游春台诗 四', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["清波滔碧天，烏藏黯黮連。","二儀不辨處，忽吐清光圓。"]', '["清波滔碧天，烏藏黯黮連。","二儀不辨处，忽吐清光圓。"]', '诗', 'shi', '', NULL, '遊春臺詩 四 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3405e8f-7046-4d8c-adb6-00179a11d247', '遊春臺詩 五', '游春台诗 五', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["烏沈海西岸，蟾吐天東頭。"]', '["烏沈海西岸，蟾吐天东头。"]', '诗', 'shi', '', NULL, '遊春臺詩 五 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e095f4c2-a53c-44b8-a3ec-32dc4091e0c0', '遊春臺詩 六', '游春台诗 六', 'e33bcbb7-61d5-4bfb-be0a-13ce9a670032', '唐', '["鳳凰三十六，碧天高太清。","元君夫人蹋雲語，冷風颯颯吹鵝笙。"]', '["鳳凰三十六，碧天高太清。","元君夫人蹋云語，冷风颯颯吹鵝笙。"]', '诗', 'shi', '', NULL, '遊春臺詩 六 春臺仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13f9d44-c003-4e31-9b8c-754bac6316ca', '醉吟', '醉吟', 'c5d0facc-ceb2-460e-9168-c3cafff5ab6a', '唐', '["陽春時節天氣和，萬物芳盛人如何。","素秋時節天地肅，榮秀叢林立衰促。","有同人世當少年，壯心儀貌皆儼然。","一旦形羸又髮白，舊遊空使淚連連。"]', '["陽春时節天氣和，万物芳盛人如何。","素秋时節天地肅，榮秀叢林立衰促。","有同人世當少年，壯心儀貌皆儼然。","一旦形羸又髮白，旧游空使泪連連。"]', '诗', 'shi', '', NULL, '醉吟 酒肆布衣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd6bf69-f889-404e-81cd-0ffeafc12703', '又吟', '又吟', 'c5d0facc-ceb2-460e-9168-c3cafff5ab6a', '唐', '["有形皆朽孰不知，休吟春景與秋時。","爭如且醉長安酒，榮華零悴總奚爲。"]', '["有形皆朽孰不知，休吟春景與秋时。","爭如且醉长安酒，榮华零悴總奚爲。"]', '诗', 'shi', '', NULL, '又吟 酒肆布衣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1351909f-b4e7-40ce-a690-1d1d197c1799', '嫁女詩 一', '嫁女诗 一', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["勸君酒，爲君悲且吟。","自從頻見市朝改，無復瑤池宴樂心。"]', '["勸君酒，爲君悲且吟。","自從頻见市朝改，無复瑤池宴乐心。"]', '诗', 'shi', '', NULL, '嫁女詩 一 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8ff655-ce5a-4aaf-8020-eb6b25a5031e', '嫁女詩 二', '嫁女诗 二', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["奉君酒，休嘆市朝非。","早知無復瑤池興，悔駕驊騮草草歸。"]', '["奉君酒，休嘆市朝非。","早知無复瑤池兴，悔駕驊騮草草归。"]', '诗', 'shi', '', NULL, '嫁女詩 二 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5cc0be-253a-4c2c-b2e3-bb4547ce3707', '嫁女詩 三', '嫁女诗 三', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["八馬迴乘汗漫風，猶思往事憩昭宮。","宴移玄圃情方洽，樂奏鈞天曲未終。","斜漢露凝殘月冷，流霞杯泛曙光紅。","崑崙回首不知處，疑是酒酣魂夢中。"]', '["八马迴乘汗漫风，猶思往事憩昭宮。","宴移玄圃情方洽，乐奏鈞天曲未終。","斜漢露凝殘月冷，流霞杯泛曙光紅。","崑崙回首不知处，疑是酒酣魂梦中。"]', '诗', 'shi', '', NULL, '嫁女詩 三 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063483cc-84e5-4744-8ee7-ece291ccee2e', '嫁女詩 四', '嫁女诗 四', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["一曲笙歌瑤水濱，曾留逸足駐征輪。","人間甲子週千歲，靈境杯觴初一巡。","玉兔銀河終不夜，奇花好樹鎮長春。","悄知碧海饒詞句，歌向俗流疑誤人。"]', '["一曲笙歌瑤水濱，曾留逸足駐征輪。","人间甲子週千歲，靈境杯觴初一巡。","玉兔銀河終不夜，奇花好樹鎮长春。","悄知碧海饒词句，歌向俗流疑誤人。"]', '诗', 'shi', '', NULL, '嫁女詩 四 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4301493-2219-4e5a-ab4b-0272c4773196', '嫁女詩 五', '嫁女诗 五', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["珠露金風下界秋，漢家陵樹冷脩脩。","當時不得仙桃力，尋作浮塵飄隴頭。"]', '["珠露金风下界秋，漢家陵樹冷脩脩。","當时不得仙桃力，尋作浮塵飄隴头。"]', '诗', 'shi', '', NULL, '嫁女詩 五 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533fd12d-45c9-4a3a-a295-14ac997ddf7d', '嫁女詩 六', '嫁女诗 六', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["五十餘年四海清，自親丹藥得長生。","若言盡是仙桃力，看取神仙簿上名。"]', '["五十餘年四海清，自親丹藥得长生。","若言尽是仙桃力，看取神仙簿上名。"]', '诗', 'shi', '', NULL, '嫁女詩 六 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4d2800-7e04-4363-822c-68f231e6955a', '嫁女詩 七', '嫁女诗 七', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["月照驪山露泣花，似悲先帝早昇遐。","至今猶有長生鹿，時遶溫泉望翠華。"]', '["月照驪山露泣花，似悲先帝早昇遐。","至今猶有长生鹿，时遶溫泉望翠华。"]', '诗', 'shi', '', NULL, '嫁女詩 七 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450aa66d-85e8-4233-ae45-2b245b69ebcf', '嫁女詩 八', '嫁女诗 八', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["幽薊煙塵別九重，貴妃湯殿罷歌鐘。","中宵扈從無全杖，大駕蒼黃發六龍。","妝匣尚留金翡翠，暖池猶浸玉芙蓉。","荆榛一閉朝元路，唯有悲風吹晚松。"]', '["幽薊煙塵別九重，貴妃湯殿罷歌鐘。","中宵扈從無全杖，大駕蒼黄發六龙。","妝匣尚留金翡翠，暖池猶浸玉芙蓉。","荆榛一閉朝元路，唯有悲风吹晚松。"]', '诗', 'shi', '', NULL, '嫁女詩 八 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38880671-e1c7-4c4a-a793-59c8a983b551', '嫁女詩 九', '嫁女诗 九', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["上清神女，玉京仙郎。","樂此今夕，和鳴鳳凰。","鳳凰和鳴，將翱將翔。","與天齊休，慶流無央。"]', '["上清神女，玉京仙郎。","乐此今夕，和鳴鳳凰。","鳳凰和鳴，將翱將翔。","與天齊休，慶流無央。"]', '诗', 'shi', '', NULL, '嫁女詩 九 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52cb1bfd-de19-49dd-9e67-05bea3195c8d', '嫁女詩 十', '嫁女诗 十', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["玉爲質兮花爲顏，蟬爲鬢兮雲爲鬟。","何勞傅粉兮施渥丹，早出娉婷兮縹緲間。"]', '["玉爲質兮花爲顏，蟬爲鬢兮云爲鬟。","何勞傅粉兮施渥丹，早出娉婷兮縹緲间。"]', '诗', 'shi', '', NULL, '嫁女詩 十 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff86a73d-8b4f-4479-a406-b2448c64cfa1', '嫁女詩 十一', '嫁女诗 十一', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["水晶帳開銀燭明，風搖珠珮連雲清。","休勻紅粉飾花態，早駕雙鸞朝玉京。"]', '["水晶帳开銀燭明，风搖珠珮連云清。","休勻紅粉飾花態，早駕雙鸾朝玉京。"]', '诗', 'shi', '', NULL, '嫁女詩 十一 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ac397c-37de-485d-8187-447f37a27200', '嫁女詩 十二', '嫁女诗 十二', '8838e1cf-5e8c-4d2a-b018-2cf7067070e6', '唐', '["三星在天銀河迴，人間曙色東方來。","玉苗瓊蕊亦宜夜，莫使一花衝曉開。"]', '["三星在天銀河迴，人间曙色东方来。","玉苗瓊蕊亦宜夜，莫使一花衝晓开。"]', '诗', 'shi', '', NULL, '嫁女詩 十二 嵩嶽諸仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5618c22-4c31-4d2d-953f-0defc39fbb45', '吟 一', '吟 一', '095cb255-6269-4f6c-a01a-dd3b1d4c024f', '唐', '["餌柏身輕疊嶂間，是非無意到塵寰。","冠裳暫備論浮世，一餉雲遊碧落間。"]', '["餌柏身轻叠嶂间，是非無意到塵寰。","冠裳暫備論浮世，一餉云游碧落间。"]', '诗', 'shi', '', NULL, '吟 一 芙蓉古丈夫　毛女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae38509-509e-47a6-aabd-a7c8754cb5ac', '吟 二', '吟 二', '095cb255-6269-4f6c-a01a-dd3b1d4c024f', '唐', '["誰知古是與今非，閑躡青霞與翠微。","簫管秦樓應寂寂，彩雲空惹薜蘿衣。"]', '["誰知古是與今非，闲躡青霞與翠微。","簫管秦楼應寂寂，彩云空惹薜蘿衣。"]', '诗', 'shi', '', NULL, '吟 二 芙蓉古丈夫　毛女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337c322e-6d63-449d-ad4e-06b51857913e', '授炙轂子歌二首 一', '授炙轂子歌二首 一', 'ec6faf1a-9af1-4ae6-8c3e-f80489ec3449', '唐', '["木津天魂，金液地魄。","坎離運行寬無成，金木有數秦晉合。","近効宜六旬，遠期三載闊。"]', '["木津天魂，金液地魄。","坎離運行寬無成，金木有數秦晉合。","近効宜六旬，远期三載闊。"]', '诗', 'shi', '', NULL, '授炙轂子歌二首 一 希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf4f6b0e-d404-4189-a02b-f1495a3b69e7', '授炙轂子歌二首 二', '授炙轂子歌二首 二', 'ec6faf1a-9af1-4ae6-8c3e-f80489ec3449', '唐', '["魄微入魂牝牡結，陽呴陰滋神鬼滅。","千歌萬讚皆未決，古往今來拋日月。"]', '["魄微入魂牝牡結，陽呴陰滋神鬼滅。","千歌万讚皆未決，古往今来拋日月。"]', '诗', 'shi', '', NULL, '授炙轂子歌二首 二 希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f8c2bb6-8a4a-4be1-87cd-54807999f16f', '李泌庭黑石詩', '李泌庭黑石诗', '9a8cb198-8116-42d8-86cd-29b0fb88f69e', '唐', '["神真鍊形年未足，化爲我子功相續。","丞相瘞之刻玄玉，仙路何長死何促。"]', '["神真鍊形年未足，化爲我子功相續。","丞相瘞之刻玄玉，仙路何长死何促。"]', '诗', 'shi', '', NULL, '李泌庭黑石詩 隱者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4baf8178-97f7-4e0c-be1c-025d5a6931a8', '戲吟', '戲吟', '625a7d23-7e53-46cc-ae77-2f09161e093b', '唐', '["無事到揚州，相攜上酒樓。","藥囊爲贈別，千載更何求。"]', '["無事到揚州，相携上酒楼。","藥囊爲贈別，千載更何求。"]', '诗', 'shi', '', NULL, '戲吟 廣陵道士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb950ba-8c7b-4aad-926f-4a2a22fe4c13', '授馬氏女詩', '授马氏女诗', '8b70f119-5016-4690-af93-9c3e225c44e0', '唐', '["女是寄生枝，男是冬青木。","冬青駕白鵝，寄生跨黃鹿。","若遇寇相凌，穩便拋家族。","早早上三清，莫候丹砂熟。"]', '["女是寄生枝，男是冬青木。","冬青駕白鵝，寄生跨黄鹿。","若遇寇相凌，穩便拋家族。","早早上三清，莫候丹砂熟。"]', '诗', 'shi', '', NULL, '授馬氏女詩 黃冠野夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ef8ed5-8172-4253-9845-e5920076cb47', '歌', '歌', '8f8c2050-7e34-45f1-b2d1-aed7de8b4f3e', '唐', '["尾閭不禁滄溟竭，九轉神丹都謾說。","惟有班龍頂上珠，能補玉堂關下穴。"]', '["尾閭不禁滄溟竭，九轉神丹都謾说。","惟有班龙頂上珠，能補玉堂关下穴。"]', '诗', 'shi', '', NULL, '歌 蜀中酒閣道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43708d2-ea9b-4a67-b8aa-7229835c2036', '吟', '吟', 'd83a6208-99d7-4a65-94db-303538784579', '唐', '["西去長沙東上船，思量此事已千年。","長春殿掩無人掃，滿眼梨花哭杜鵑。"]', '["西去长沙东上船，思量此事已千年。","长春殿掩無人掃，满眼梨花哭杜鵑。"]', '诗', 'shi', '', NULL, '吟 章江書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1dddb66-ccc3-43b1-ac6a-ddd1b9001d20', '示邊洞元', '示邊洞元', 'e55b1d48-f876-4c1a-b468-0bcb9b44db6b', '唐', '["邂逅相逢萼嶺邊，對傾浮蟻共談玄。","擬將劒法親傳授，却爲迷人未有緣。"]', '["邂逅相逢萼嶺邊，对傾浮蟻共談玄。","擬將劒法親傳授，却爲迷人未有緣。"]', '诗', 'shi', '', NULL, '示邊洞元 萼嶺書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ed6d48-5c52-4ca3-b1ee-6fe17cd73101', '示胡二郎歌', '示胡二郎歌', 'f34546d5-328d-4f7f-9b85-6935ba045698', '唐', '["欲究丹砂理，幽玄無處尋。","不離鉛與汞，無出水中金。","金欲煉時須得水，水遇土兮終不起。","但知火候不參差，自得還丹微妙旨。","人世分明知有死，剛只留心戀朱紫。","豈知光景片時間，將謂人生長似此。","何不迴心師至道？免逐年光虛自老。","臨樽只解醉醺酣，對鏡方知漸枯槁。","二郎切切聽我語，仙鄉咫尺無寒暑。","與君說盡只如斯，莫戀嬌奢不肯去。","感君恩義言方苦，火急迴心求出路。","吟成數句贈君辭，不覺便成今與古。"]', '["欲究丹砂理，幽玄無处尋。","不離鉛與汞，無出水中金。","金欲煉时須得水，水遇土兮終不起。","但知火候不參差，自得還丹微妙旨。","人世分明知有死，剛只留心戀朱紫。","豈知光景片时间，將謂人生长似此。","何不迴心師至道？免逐年光虛自老。","臨樽只解醉醺酣，对镜方知漸枯槁。","二郎切切听我語，仙乡咫尺無寒暑。","與君说尽只如斯，莫戀嬌奢不肯去。","感君恩義言方苦，火急迴心求出路。","吟成數句贈君辞，不覺便成今與古。"]', '诗', 'shi', '', NULL, '示胡二郎歌 成都醉道士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5cd8f3-6231-4f39-9b20-ac738434e4e7', '貽白永年詩', '貽白永年诗', '10289b54-a8b6-4176-8a2d-0eefd9aaa134', '唐', '["清秋無所事，乘露出遙天。","憑杖樵人語，相期白永年。"]', '["清秋無所事，乘露出遙天。","憑杖樵人語，相期白永年。"]', '诗', 'shi', '', NULL, '貽白永年詩 樵夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776e7e9f-f5de-4ebf-ab98-20b301a94a74', '留詩', '留诗', 'd2d9b4c9-c51e-434e-a4ab-99957c01da8b', '唐', '["我有衣中珠，不嫌衣上塵。","我有長生理，不厭有生身。","江南神仙窟，吾當混其真。","不嫌市井諠，來救世間人。","蘇子跡已往，顓蒙事可親。","莫言東海變，天地有長春。"]', '["我有衣中珠，不嫌衣上塵。","我有长生理，不厭有生身。","江南神仙窟，吾當混其真。","不嫌市井諠，来救世间人。","蘇子跡已往，顓蒙事可親。","莫言东海变，天地有长春。"]', '诗', 'shi', '', NULL, '留詩 李公佐僕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2615c5d4-457d-42fc-816f-82bb85b0bbed', '酒盡君莫沽', '酒尽君莫沽', 'f8bf1496-21e3-4196-9c42-757cf8ccb938', '唐', '["酒盡君莫沽，壺傾我當發。","城市多囂塵，還山弄明月。"]', '["酒尽君莫沽，壺傾我當發。","城市多囂塵，還山弄明月。"]', '诗', 'shi', '', NULL, '酒盡君莫沽 木客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78239a47-56a4-4a63-97d7-82947fdeb06f', '西山吟', '西山吟', '8b365d0f-1e8b-4db5-b350-17dfa2adee9b', '唐', '["自從明府歸仙後，出入塵寰直至今。","不是藏名混時俗，賣藥沽酒要安心。"]', '["自從明府归仙後，出入塵寰直至今。","不是藏名混时俗，賣藥沽酒要安心。"]', '诗', 'shi', '', NULL, '西山吟 許大 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3f3711-b1b2-4126-8f37-f609a74e9a96', '東洛貨丹', '东洛貨丹', 'cf71610e-d897-476b-8eff-df837c539186', '唐', '["三千功滿去升天，一住人間數百年。","華表他時却歸日，滄溟應恐變桑田。"]', '["三千功满去升天，一住人间數百年。","华表他时却归日，滄溟應恐变桑田。"]', '诗', 'shi', '', NULL, '東洛貨丹 許學士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e2b8a8-5aee-4673-be41-955b3c460333', '天關回到世吟', '天关回到世吟', 'cf71610e-d897-476b-8eff-df837c539186', '唐', '["九霄雲路奇哉險，曾把沖身入太和。","今日東歸渾似夢，望崖回首隔天波。"]', '["九霄云路奇哉險，曾把沖身入太和。","今日东归渾似梦，望崖回首隔天波。"]', '诗', 'shi', '', NULL, '天關回到世吟 許學士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d07d9ba2-5d63-4c03-b970-9e05a2b88a57', '送青城丈人酒', '送青城丈人酒', 'be254030-a3fd-4ddf-9841-a4d921d32e02', '唐', '["深羨青城好洞天，白龍一覺已千年。","鋪雲枕石長松下，朝退看書盡日眠。"]', '["深羨青城好洞天，白龙一覺已千年。","鋪云枕石长松下，朝退看书尽日眠。"]', '诗', 'shi', '', NULL, '送青城丈人酒 紫微孫處士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96e2a57c-2297-40e9-9b09-530ead194007', '送王懿昌酒', '送王懿昌酒', 'be254030-a3fd-4ddf-9841-a4d921d32e02', '唐', '["將知骨分到仙鄉，酒飲金華玉液漿。","莫道人間只如此，回頭已是一年強。"]', '["將知骨分到仙乡，酒饮金华玉液漿。","莫道人间只如此，回头已是一年強。"]', '诗', 'shi', '', NULL, '送王懿昌酒 紫微孫處士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2e54ceb-225e-47e3-891b-81284d3fb345', '送太乙真君酒', '送太乙真君酒', 'ec3fe065-f45e-4c8f-b4dd-1499bc01f739', '唐', '["峨嵋仙府靜沈沈，玉液金華莫厭斟。","凡客欲知真一洞，劒門西北五雲深。"]', '["峨嵋仙府静沈沈，玉液金华莫厭斟。","凡客欲知真一洞，劒门西北五云深。"]', '诗', 'shi', '', NULL, '送太乙真君酒 青城丈人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3092192-fdea-4e98-a34f-19d7cb0e06ec', '送紫微處士酒', '送紫微处士酒', 'c32d7bbb-cd64-46b8-8d0c-f5e5dc0bf388', '唐', '["此中何必羨青城，玉樹雲棲不記名。","悶即乘龍遊紫府，北辰南斗逐君行。"]', '["此中何必羨青城，玉樹云棲不記名。","悶即乘龙游紫府，北辰南斗逐君行。"]', '诗', 'shi', '', NULL, '送紫微處士酒 太乙真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9bc3391-8069-4dc8-b356-af49d180854a', '題法雲寺雙檜', '題法云寺雙檜', '8105e39c-4ad6-4607-91d1-0f0241223be7', '唐', '["謝郎雙檜綠於雲，昏曉濃陰色未分。","若竝毫宮仙鹿跡，定知高峭不如君。"]', '["謝郎雙檜綠於云，昏晓濃陰色未分。","若竝毫宮仙鹿跡，定知高峭不如君。"]', '诗', 'shi', '', NULL, '題法雲寺雙檜 方壺居士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f76ddf2-da35-4984-b91b-75c1ef2ce11f', '隋堤詞', '隋堤词', '8105e39c-4ad6-4607-91d1-0f0241223be7', '唐', '["嘗憶江都大業秋，曾隨鑾蹕戲龍舟。","傷心一覺興亡夢，堤柳無情識世愁。"]', '["嘗憶江都大業秋，曾隨鑾蹕戲龙舟。","傷心一覺兴亡梦，堤柳無情識世愁。"]', '诗', 'shi', '', NULL, '隋堤詞 方壺居士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2394c7-642a-4cfa-83b2-dd495e88863a', '畫地吟', '畫地吟', 'bb0b03da-d61c-4703-bd9e-905297dacb7f', '唐', '["學得丹青數萬年，人間幾度變桑田。","桑田雖變丹青在，誰向丹青合得仙。"]', '["学得丹青數万年，人间幾度变桑田。","桑田雖变丹青在，誰向丹青合得仙。"]', '诗', 'shi', '', NULL, '畫地吟 太白山玄士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d336a7f5-22b8-41fe-869d-b217e6c8e2a1', '貨丹吟', '貨丹吟', '98d87f0f-7ce6-4fdf-b5ad-5c1f839cb309', '唐', '["尋仙何必三山上，但使神存九竅清。","煉得綿綿元氣定，自然不食亦長生。"]', '["尋仙何必三山上，但使神存九竅清。","煉得綿綿元氣定，自然不食亦长生。"]', '诗', 'shi', '', NULL, '貨丹吟 鄰道場人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05959fee-eb71-40e6-8a05-98b1827b5574', '靈響詞 一', '靈响词 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["此響非俗響，心知是靈仙。","不曾離耳裏，高下如秋蟬。"]', '["此响非俗响，心知是靈仙。","不曾離耳裏，高下如秋蟬。"]', '诗', 'shi', '', NULL, '靈響詞 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ed2d16-92a6-4f2d-baa8-ceac17823765', '靈響詞 二', '靈响词 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["入夜聲則厲，在晝聲則微。","神靈斥衆惡，與我作風威。"]', '["入夜声則厲，在晝声則微。","神靈斥衆惡，與我作风威。"]', '诗', 'shi', '', NULL, '靈響詞 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2359ceff-0750-479a-ae74-bbeb8b415895', '靈響詞 三', '靈响词 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["妙響無住時，晝夜常輪迴。","那是偶然事，上界特使來。"]', '["妙响無住时，晝夜常輪迴。","那是偶然事，上界特使来。"]', '诗', 'shi', '', NULL, '靈響詞 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e1534f6-8e4a-48d4-98cb-30335eebfb64', '靈響詞 四', '靈响词 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["何以辨靈應，事須得梯媒。","自從靈響降，如有真人來。"]', '["何以辨靈應，事須得梯媒。","自從靈响降，如有真人来。"]', '诗', 'shi', '', NULL, '靈響詞 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff45d27-8f28-46a4-a864-d6c853b02bc2', '靈響詞 五', '靈响词 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["存念長在心，展轉無停音。","可憐清爽夜，靜聽秋蟬吟。"]', '["存念长在心，展轉無停音。","可怜清爽夜，静听秋蟬吟。"]', '诗', 'shi', '', NULL, '靈響詞 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f67387d-9060-4b9f-8e1f-c66fe91bf46b', '度世古玄歌', '度世古玄歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["始青之下月與日，兩半同升合爲一。","大如彈丸甘如蜜，出彼玉堂入金室，子若得之慎勿失。"]', '["始青之下月與日，兩半同升合爲一。","大如彈丸甘如蜜，出彼玉堂入金室，子若得之慎勿失。"]', '诗', 'shi', '', NULL, '度世古玄歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ddf5ce-7454-4a70-b615-fde66abf7146', '鬻丹砂醉吟', '鬻丹砂醉吟', 'f452c505-affe-4c68-9da0-00c1b029c694', '唐', '["心田但使靈芝長，氣海常教法水朝。","功滿自然留不住，更將何物馭丹霄。"]', '["心田但使靈芝长，氣海常教法水朝。","功满自然留不住，更將何物馭丹霄。"]', '诗', 'shi', '', NULL, '鬻丹砂醉吟 劉道昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('111f978a-abf0-4c47-973a-438ae907d768', '龜市告別', '龟市告別', 'f452c505-affe-4c68-9da0-00c1b029c694', '唐', '["還丹功滿氣成胎，九百年來混俗埃。","自此三山一歸去，無因重到世間來。"]', '["還丹功满氣成胎，九百年来混俗埃。","自此三山一归去，無因重到世间来。"]', '诗', 'shi', '', NULL, '龜市告別 劉道昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20aabd19-401a-4bfe-8e76-9d8ecee24de2', '摘紫芝', '摘紫芝', '62410533-978b-4a02-adb8-5dad6b385a04', '唐', '["偶游洞府到芝田，星月茫茫欲曙天。","雖則似離塵世了，不知何處偶真仙。"]', '["偶游洞府到芝田，星月茫茫欲曙天。","雖則似離塵世了，不知何处偶真仙。"]', '诗', 'shi', '', NULL, '摘紫芝 李太玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d64337-d60d-4f53-ad11-24095c57d3c4', '玉女舞霓裳', '玉女舞霓裳', '62410533-978b-4a02-adb8-5dad6b385a04', '唐', '["舞勢隨風散復收，歌聲似磬韻還幽。","千迴赴節填詞處，嬌眼如波入鬢流。"]', '["舞勢隨风散复收，歌声似磬韻還幽。","千迴赴節填词处，嬌眼如波入鬢流。"]', '诗', 'shi', '', NULL, '玉女舞霓裳 李太玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad52fb8-67f9-4608-a9e8-e008fcd611b6', '翫月詩 一', '翫月诗 一', 'fc7ad00b-5ce7-45eb-a007-804307f0f425', '唐', '["曲龍橋頂翫瀛洲，凡骨空陪汗漫流。","不假丹梯躡霄漢，水晶盤冷桂花秋。"]', '["曲龙橋頂翫瀛洲，凡骨空陪汗漫流。","不假丹梯躡霄漢，水晶盤冷桂花秋。"]', '诗', 'shi', '', NULL, '翫月詩 一 曲龍山仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('187e98d1-5166-4068-a6d5-7522ae508f29', '翫月詩 二', '翫月诗 二', 'fc7ad00b-5ce7-45eb-a007-804307f0f425', '唐', '["月砌瑤階泉滴乳，玉簫催鳳和煙舞。","青城丈人何處遊，玄鶴唳天雲一縷。"]', '["月砌瑤階泉滴乳，玉簫催鳳和煙舞。","青城丈人何处游，玄鹤唳天云一縷。"]', '诗', 'shi', '', NULL, '翫月詩 二 曲龍山仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202bd0c0-4003-4749-a804-f28a5995b752', '翫月詩 三', '翫月诗 三', 'fc7ad00b-5ce7-45eb-a007-804307f0f425', '唐', '["造化天橋碧海東，玉輪還過輾晴虹。","霓襟似拂瀛洲頂，顥氣潛消橐籥中。"]', '["造化天橋碧海东，玉輪還過輾晴虹。","霓襟似拂瀛洲頂，顥氣潛消橐籥中。"]', '诗', 'shi', '', NULL, '翫月詩 三 曲龍山仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c11ac9c-ae64-4654-9968-b1fdb2302d3a', '翫月詩 四', '翫月诗 四', 'fc7ad00b-5ce7-45eb-a007-804307f0f425', '唐', '["危橋橫石架雲端，跨鹿登臨景象寬。","顥魄洗煙澄碧落，桂花低拂玉簪寒。"]', '["危橋橫石架云端，跨鹿登臨景象寬。","顥魄洗煙澄碧落，桂花低拂玉簪寒。"]', '诗', 'shi', '', NULL, '翫月詩 四 曲龍山仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b285612-82cf-4ef7-8533-af42833beee6', '句', '句', '0ebd2390-2c48-490c-ab34-9f5a5d991aa8', '唐', '["夜坐空庭月色微，一樹寒梅發兩枝。"]', '["夜坐空庭月色微，一樹寒梅發兩枝。"]', '诗', 'shi', '', NULL, '句 陳復休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('422d7b14-d3e8-4064-ac77-18e1ca55734b', '句', '句', '014095b5-fe7a-4cce-b331-582e6fce2c83', '唐', '["不緣過去行方便，安得今朝會碧虛。"]', '["不緣過去行方便，安得今朝會碧虛。"]', '诗', 'shi', '', NULL, '句 鄭冠卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5d86f6-d66f-4463-9634-3753e9e5ce87', '句', '句', '66c92cc2-0574-4710-9029-c27a02b3e1cc', '唐', '["竹籬疎見浦，茅屋漏通星。"]', '["竹籬疎见浦，茅屋漏通星。"]', '诗', 'shi', '', NULL, '句 陳蓬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b05e5a-b124-44b7-8cb9-149888bfe281', '句', '句', '03128eb6-28a2-4101-8e63-9836d3a9db04', '唐', '["惟有松杉空弄月，更無雲鶴暗迷人。","露凝金盞滴殘酒，檀點佳人噴異香。"]', '["惟有松杉空弄月，更無云鹤暗迷人。","露凝金盞滴殘酒，檀点佳人噴異香。"]', '诗', 'shi', '', NULL, '句 伊夢昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40abdb78-a574-4b93-9a1a-1946075a5537', '與薛昭合婚詩 一', '與薛昭合婚诗 一', '10327fcb-8ba2-429f-a773-b355ecf28609', '唐', '["臉花不綻幾含幽，今夕陽春獨換秋。","我守孤燈無白日，寒雲隴上更添愁。"]', '["臉花不綻幾含幽，今夕陽春独換秋。","我守孤灯無白日，寒云隴上更添愁。"]', '诗', 'shi', '', NULL, '與薛昭合婚詩 一 張雲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668d0d0b-807b-4e5f-8716-c85bcdd20eb8', '與薛昭合婚詩 二', '與薛昭合婚诗 二', '10327fcb-8ba2-429f-a773-b355ecf28609', '唐', '["幽谷啼鶯整羽翰，犀沈玉冷自長歎。","月華不向扃泉戶，露滴松枝一夜寒。"]', '["幽谷啼鶯整羽翰，犀沈玉冷自长歎。","月华不向扃泉戶，露滴松枝一夜寒。"]', '诗', 'shi', '', NULL, '與薛昭合婚詩 二 張雲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('003f3fa7-49f4-4e11-a072-d290bccc1e56', '與薛昭合婚詩 三', '與薛昭合婚诗 三', '10327fcb-8ba2-429f-a773-b355ecf28609', '唐', '["韶光不見分成塵，曾餌金丹忽有神。","不意薛生攜舊律，獨開幽谷一枝春。"]', '["韶光不见分成塵，曾餌金丹忽有神。","不意薛生携旧律，独开幽谷一枝春。"]', '诗', 'shi', '', NULL, '與薛昭合婚詩 三 張雲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fffd2c-1820-4b38-a14e-7d5481c8fc25', '與薛昭合婚詩 四', '與薛昭合婚诗 四', '10327fcb-8ba2-429f-a773-b355ecf28609', '唐', '["誤入宮垣漏網人，月華靜洗玉階塵。","自疑飛到蓬萊頂，瓊豔三枝半夜春。"]', '["誤入宮垣漏網人，月华静洗玉階塵。","自疑飞到蓬萊頂，瓊豔三枝半夜春。"]', '诗', 'shi', '', NULL, '與薛昭合婚詩 四 張雲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e723de9-7675-492d-b821-06f1af9b9294', '留別盧陲', '留別盧陲', '66fe0cd6-d18a-4b16-8872-94379c6f99f8', '唐', '["得之一元，匪受自天。","太老之真，無上之僊。","光含影藏，形于自然。","真安匪求，神之久留。","淑美其真，體性剛柔。","丹霄碧虛，上聖之儔。","百歲之後，空餘墳丘。"]', '["得之一元，匪受自天。","太老之真，無上之僊。","光含影藏，形于自然。","真安匪求，神之久留。","淑美其真，體性剛柔。","丹霄碧虛，上聖之儔。","百歲之後，空餘墳丘。"]', '诗', 'shi', '', NULL, '留別盧陲 崔少玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da4409b-3d2a-448d-bdff-b6356db6e80a', '歌', '歌', 'cccd4a27-ed1e-4efc-b07f-3ff6ea282167', '唐', '["笑看滄海欲成塵，王母花前別衆真。","千歲却歸天上去，一心珍重世間人。"]', '["笑看滄海欲成塵，王母花前別衆真。","千歲却归天上去，一心珍重世间人。"]', '诗', 'shi', '', NULL, '歌 戚逍遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0759d92a-c588-46e9-a778-8f11692c4afc', '錦城春望', '錦城春望', '2252af62-3cc1-4fbc-9c87-10904228715c', '唐', '["和風裝點錦城春，細雨如絲壓玉塵。","漫把詩情訪奇景，豔花濃酒屬閑人。"]', '["和风裝点錦城春，細雨如絲壓玉塵。","漫把诗情訪奇景，豔花濃酒屬闲人。"]', '诗', 'shi', '', NULL, '錦城春望 卓英英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee7eda5-12d4-49ac-bd9f-d23ed459da96', '理笙', '理笙', '2252af62-3cc1-4fbc-9c87-10904228715c', '唐', '["頻倚銀屏理鳳笙，調中幽意起春情。","因思往事成惆悵，不得緱山和一聲。"]', '["頻倚銀屏理鳳笙，調中幽意起春情。","因思往事成惆悵，不得緱山和一声。"]', '诗', 'shi', '', NULL, '理笙 卓英英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e23250-e1b5-4761-a191-4febf347709c', '遊福感寺荅少年', '游福感寺荅少年', '2252af62-3cc1-4fbc-9c87-10904228715c', '唐', '["牡丹未及開時節，況是秋風莫近前。","留待來年二三月，一枝和露壓神仙。"]', '["牡丹未及开时節，況是秋风莫近前。","留待来年二三月，一枝和露壓神仙。"]', '诗', 'shi', '', NULL, '遊福感寺荅少年 卓英英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b807c4a1-cd03-4076-b007-aedcf4e59e21', '荅玄士', '荅玄士', '2252af62-3cc1-4fbc-9c87-10904228715c', '唐', '["數載幽欄種牡丹，裹香包豔待神仙。","神仙既有丹青術，攜取何妨入洞天。"]', '["數載幽欄種牡丹，裹香包豔待神仙。","神仙既有丹青術，携取何妨入洞天。"]', '诗', 'shi', '', NULL, '荅玄士 卓英英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc6928d-c9d6-4136-8802-05c4aa96ac8f', '和卓英英錦城春望', '和卓英英錦城春望', '4d474f2a-46a8-4749-8646-8d5b45ef79a2', '唐', '["蠶市初開處處春，九衢明豔起香塵。","世間總有浮華事，爭及仙山出世人。"]', '["蠶市初开处处春，九衢明豔起香塵。","世间總有浮华事，爭及仙山出世人。"]', '诗', 'shi', '', NULL, '和卓英英錦城春望 眉娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4436e7-02b4-4391-a4cd-4da467111030', '和卓英英理笙', '和卓英英理笙', '4d474f2a-46a8-4749-8646-8d5b45ef79a2', '唐', '["但於閨閣熟吹笙，太白真仙自有情。","他日丹霄驂白鳳，何愁子晉不聞聲。"]', '["但於閨閣熟吹笙，太白真仙自有情。","他日丹霄驂白鳳，何愁子晉不闻声。"]', '诗', 'shi', '', NULL, '和卓英英理笙 眉娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b1eac8-0b17-4bc9-a58e-b6489172b0a1', '太白山玄士畫地吟', '太白山玄士畫地吟', '4d474f2a-46a8-4749-8646-8d5b45ef79a2', '唐', '["學得丹青數萬年，人間幾度變桑田。","桑田雖變丹青在，誰向丹青合得仙。"]', '["学得丹青數万年，人间幾度变桑田。","桑田雖变丹青在，誰向丹青合得仙。"]', '诗', 'shi', '', NULL, '太白山玄士畫地吟 眉娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604cb9a3-0a04-425c-ab63-be76101ff193', '荅張鬱歌 一', '荅張鬱歌 一', '438c3647-8cae-4d10-9623-791fd3687d7a', '唐', '["彩雲入帝鄉，白鶴又回翔。","久留深不可，蓬島路遐長。"]', '["彩云入帝乡，白鹤又回翔。","久留深不可，蓬島路遐长。"]', '诗', 'shi', '', NULL, '荅張鬱歌 一 洛川仙女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b932a380-a7d4-4c61-99d9-fb092de80735', '荅張鬱歌 二', '荅張鬱歌 二', '438c3647-8cae-4d10-9623-791fd3687d7a', '唐', '["空愛長生術，不是長生人。","今日洛川別，可惜洞中春。"]', '["空愛长生術，不是长生人。","今日洛川別，可惜洞中春。"]', '诗', 'shi', '', NULL, '荅張鬱歌 二 洛川仙女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ef2b1e-4baa-49e4-8c2f-cd508ef9aefb', '張鬱洛川沿步吟', '張鬱洛川沿步吟', '438c3647-8cae-4d10-9623-791fd3687d7a', '唐', '["浮生如夢能幾何，浮生復更憂患多。","無人與我長生術，洛川春日且長歌。"]', '["浮生如梦能幾何，浮生复更憂患多。","無人與我长生術，洛川春日且长歌。"]', '诗', 'shi', '', NULL, '張鬱洛川沿步吟 洛川仙女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0585f71e-3c84-4580-b91c-5d213eed607e', '題玉壺贈元柳二子', '題玉壺贈元柳二子', '15692778-99c2-44e2-b4de-3db37474bf56', '唐', '["來從一葉舟中來，去向百花橋上去。","若到人間扣玉壺，鴛鴦自解分明語。"]', '["来從一葉舟中来，去向百花橋上去。","若到人间扣玉壺，鴛鴦自解分明語。"]', '诗', 'shi', '', NULL, '題玉壺贈元柳二子 南溟夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8766390-3e63-4a71-85a8-516cab5ee53e', '會真詩 一', '會真诗 一', '3ce11688-b5e0-41e8-87a0-9c42fe66e237', '唐', '["人世徒紛擾，其生似夢華。","誰言今昔裏，俯首視雲霞。"]', '["人世徒紛擾，其生似梦华。","誰言今昔裏，俯首視云霞。"]', '诗', 'shi', '', NULL, '會真詩 一 雲臺峰五女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c983ffdd-1e10-4cb7-bcf7-a202671fbef6', '會真詩 二', '會真诗 二', '3ce11688-b5e0-41e8-87a0-9c42fe66e237', '唐', '["幾劫澄煩思，今身僅小成。","誓將雲外隱，不向世間存。"]', '["幾劫澄煩思，今身僅小成。","誓將云外隐，不向世间存。"]', '诗', 'shi', '', NULL, '會真詩 二 雲臺峰五女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de3ced0-a7ca-4ee4-a30e-992a33b16bee', '會真詩 三', '會真诗 三', '3ce11688-b5e0-41e8-87a0-9c42fe66e237', '唐', '["綽約離塵世，從容上太清。","雲衣無綻日，鶴駕沒遙程。"]', '["綽約離塵世，從容上太清。","云衣無綻日，鹤駕沒遙程。"]', '诗', 'shi', '', NULL, '會真詩 三 雲臺峰五女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befc1b90-edf1-48e1-b402-447816929e52', '會真詩 四', '會真诗 四', '3ce11688-b5e0-41e8-87a0-9c42fe66e237', '唐', '["華嶽無三尺，東瀛僅一杯。","入雲騎彩鳳，歌舞上蓬萊。"]', '["华嶽無三尺，东瀛僅一杯。","入云騎彩鳳，歌舞上蓬萊。"]', '诗', 'shi', '', NULL, '會真詩 四 雲臺峰五女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2ce37a-a9f4-461b-81dd-3f06bf24fc88', '會真詩 五', '會真诗 五', '3ce11688-b5e0-41e8-87a0-9c42fe66e237', '唐', '["共作雲山侶，俱辭世界塵。","靜思前日事，拋却幾年身。"]', '["共作云山侶，俱辞世界塵。","静思前日事，拋却幾年身。"]', '诗', 'shi', '', NULL, '會真詩 五 雲臺峰五女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8580c305-a052-4d7b-be42-0579ca839a92', '仙詩五首 一', '仙诗五首 一', 'bd2ac499-1ded-48ca-99d6-d430c23377d3', '唐', '["道啓真心覺漸清，天教絕粒應精誠。","雲外仙歌笙管合，花間風引步虛聲。"]', '["道啓真心覺漸清，天教絕粒應精誠。","云外仙歌笙管合，花间风引步虛声。"]', '诗', 'shi', '', NULL, '仙詩五首 一 吳清妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf88b4d-2563-4679-b475-992b21e89510', '仙詩五首 二', '仙诗五首 二', 'bd2ac499-1ded-48ca-99d6-d430c23377d3', '唐', '["□□□□□□□，□君隱處當一星。","□□蓮花山頭飯，黃精仙人掌上經。"]', '["□□□□□□□，□君隐处當一星。","□□蓮花山头飯，黄精仙人掌上經。"]', '诗', 'shi', '', NULL, '仙詩五首 二 吳清妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d9bab0-0e0a-46dd-8cb8-5d95385d6f51', '仙詩五首 三', '仙诗五首 三', 'bd2ac499-1ded-48ca-99d6-d430c23377d3', '唐', '["飛鳥莫到人莫攀，一隱十年不下山。","袖中短書誰爲達，華山道士賣藥還。"]', '["飞鸟莫到人莫攀，一隐十年不下山。","袖中短书誰爲達，华山道士賣藥還。"]', '诗', 'shi', '', NULL, '仙詩五首 三 吳清妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a280c6-9c12-4703-bb5e-e149f72e1a86', '仙詩五首 四', '仙诗五首 四', 'bd2ac499-1ded-48ca-99d6-d430c23377d3', '唐', '["日落焚香坐醮壇，庭花露濕漸更闌。","淨水仙童調玉液，春宵羽客化金丹。"]', '["日落焚香坐醮壇，庭花露濕漸更闌。","淨水仙童調玉液，春宵羽客化金丹。"]', '诗', 'shi', '', NULL, '仙詩五首 四 吳清妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eaa249d-615d-41cf-8873-5a9976993c7d', '仙詩五首 五', '仙诗五首 五', 'bd2ac499-1ded-48ca-99d6-d430c23377d3', '唐', '["攝念精思引彩霞，焚香虛室對煙花。","道合雲霄遊紫府，湛然真境瑞皇家。"]', '["攝念精思引彩霞，焚香虛室对煙花。","道合云霄游紫府，湛然真境瑞皇家。"]', '诗', 'shi', '', NULL, '仙詩五首 五 吳清妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c557591c-b092-4a60-914e-ace3a9662646', '贈封陟', '贈封陟', 'f6ac9e1f-612c-4c40-9147-c395b45c5c08', '唐', '["謫居蓬島別瑤池，春媚煙花有所思。","爲愛君心能潔白，願操箕帚奉屏幃。"]', '["謫居蓬島別瑤池，春媚煙花有所思。","爲愛君心能潔白，願操箕帚奉屏幃。"]', '诗', 'shi', '', NULL, '贈封陟 上元夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73f06b8-f693-4843-8408-3d0ca2ee49f7', '再贈', '再贈', 'f6ac9e1f-612c-4c40-9147-c395b45c5c08', '唐', '["弄玉有夫皆得道，劉綱兼室盡登仙。","君能仔細窺朝露，須逐雲車拜洞天。"]', '["弄玉有夫皆得道，劉綱兼室尽登仙。","君能仔細窺朝露，須逐云车拜洞天。"]', '诗', 'shi', '', NULL, '再贈 上元夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97103e07-6a9e-425d-9670-0e6b2abaa7cd', '留別', '留別', 'f6ac9e1f-612c-4c40-9147-c395b45c5c08', '唐', '["蕭郎不顧鳳樓人，雲澀回車淚臉新。","愁想蓬瀛歸去路，難窺舊苑碧桃春。"]', '["蕭郎不顧鳳楼人，云澀回车泪臉新。","愁想蓬瀛归去路，难窺旧苑碧桃春。"]', '诗', 'shi', '', NULL, '留別 上元夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c1865a-d2d0-4ca1-83da-4e8df710425c', '題寺廊柱 一', '題寺廊柱 一', '448556a5-81ff-49a9-a673-ab54bd4a1891', '唐', '["皇子陂頭好月明，忘却華筵到曉行。","煙收山低翠黛橫，折得荷花遠恨生。"]', '["皇子陂头好月明，忘却华筵到晓行。","煙收山低翠黛橫，折得荷花远恨生。"]', '诗', 'shi', '', NULL, '題寺廊柱 一 慈恩塔院女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc000e0-7f7b-4cb7-8ccb-a01e324c212b', '題寺廊柱 二', '題寺廊柱 二', '448556a5-81ff-49a9-a673-ab54bd4a1891', '唐', '["湖水團團夜如鏡，碧樹紅花相掩映。","北斗闌干移曉柄，有似佳期常不定。"]', '["湖水團團夜如镜，碧樹紅花相掩映。","北斗闌干移晓柄，有似佳期常不定。"]', '诗', 'shi', '', NULL, '題寺廊柱 二 慈恩塔院女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52160537-660c-4cf7-9fb6-5ea26145534b', '后土夫人', '后土夫人', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["偶引羣仙到世間，熏風殿裏醉華筵。","等閑貪賞不歸去，愁殺韋郎一覺眠。"]', '["偶引羣仙到世间，熏风殿裏醉华筵。","等闲貪賞不归去，愁殺韋郎一覺眠。"]', '诗', 'shi', '', NULL, '后土夫人 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('456df2e5-f564-4d94-a0cc-3cf62fde77a7', '王母', '王母', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["滄海成塵幾萬秋，碧桃花發長春愁。","不來便是數千載，周穆漢皇何處遊。"]', '["滄海成塵幾万秋，碧桃花發长春愁。","不来便是數千載，周穆漢皇何处游。"]', '诗', 'shi', '', NULL, '王母 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d641d0-1dc1-4b4e-a62d-fa5576be8e26', '麻姑', '麻姑', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["世間何事不潸然，得失人情命不延。","適向蔡家廳上飲，回頭已見一千年。"]', '["世间何事不潸然，得失人情命不延。","適向蔡家廳上饮，回头已见一千年。"]', '诗', 'shi', '', NULL, '麻姑 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb1148b-3c1e-4f98-9928-320b83fee19a', '上元夫人', '上元夫人', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["思量往事一愁容，阿母曾邀到漢宮。","城闕不存人不見，茂陵荒草恨無窮。"]', '["思量往事一愁容，阿母曾邀到漢宮。","城闕不存人不见，茂陵荒草恨無窮。"]', '诗', 'shi', '', NULL, '上元夫人 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c0f856-2b4a-4783-a522-f7718bd59150', '弄玉', '弄玉', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["采鳳飛來到禁闈，便隨王母駐瑤池。","如今記得秦樓上，偷見蕭郎惱妾時。"]', '["采鳳飞来到禁闈，便隨王母駐瑤池。","如今記得秦楼上，偷见蕭郎惱妾时。"]', '诗', 'shi', '', NULL, '弄玉 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd81341-a406-47e6-a78b-9066e0b7c61f', '太真', '太真', '8b6b015c-4be6-42fe-831d-a3210e03be80', '唐', '["春夢悠揚生下界，一堪成笑一堪悲。","馬嵬不是無情地，自遇蓬萊睡覺時。"]', '["春梦悠揚生下界，一堪成笑一堪悲。","马嵬不是無情地，自遇蓬萊睡覺时。"]', '诗', 'shi', '', NULL, '太真 蜀宮羣仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0da69e-ce8a-4514-b0d5-760ed1016cfc', '贈郭翰二首 一', '贈郭翰二首 一', 'a4baa483-5875-4547-9b9a-0f2ca379d4d6', '唐', '["河漢雖云闊，三秋尚有期。","情人終已矣，良㑹更何時。"]', '["河漢雖云闊，三秋尚有期。","情人終已矣，良㑹更何时。"]', '诗', 'shi', '', NULL, '贈郭翰二首 一 織女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c47168f-c084-4099-8046-fb7be4580bba', '贈郭翰二首 二', '贈郭翰二首 二', 'a4baa483-5875-4547-9b9a-0f2ca379d4d6', '唐', '["朱閣臨清溪，瓊宮銜紫房。","佳情期在此，只是斷人腸。"]', '["朱閣臨清溪，瓊宮銜紫房。","佳情期在此，只是斷人腸。"]', '诗', 'shi', '', NULL, '贈郭翰二首 二 織女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('666eb7bb-1b7c-42eb-aa52-8d5d3500f998', '郭翰酬織女 一', '郭翰酬织女 一', 'a4baa483-5875-4547-9b9a-0f2ca379d4d6', '唐', '["人世將天上，由來不可期。","誰知一迴顧，更作兩相思。"]', '["人世將天上，由来不可期。","誰知一迴顧，更作兩相思。"]', '诗', 'shi', '', NULL, '郭翰酬織女 一 織女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a38b6c-36ac-4361-bfd3-d8dd66500e7c', '郭翰酬織女 二', '郭翰酬织女 二', 'a4baa483-5875-4547-9b9a-0f2ca379d4d6', '唐', '["贈枕猶香澤，啼衣尚淚痕。","玉顏霄漢裏，空有往來魂。"]', '["贈枕猶香澤，啼衣尚泪痕。","玉顏霄漢裏，空有往来魂。"]', '诗', 'shi', '', NULL, '郭翰酬織女 二 織女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e79c1c-d4ef-4711-9e85-2003c2885cb3', '書任生案 一', '书任生案 一', '20da54d0-5232-4aa2-93e9-1f0332647110', '唐', '["我本籍上清，謫居遊五岳。","以君無俗累，來勸神仙學。"]', '["我本籍上清，謫居游五岳。","以君無俗累，来勸神仙学。"]', '诗', 'shi', '', NULL, '書任生案 一 嵩山女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c788d7f-06cd-4bd1-85f1-05fe4635be8a', '書任生案 二', '书任生案 二', '20da54d0-5232-4aa2-93e9-1f0332647110', '唐', '["葛洪還有婦，王母亦有夫。","神仙盡靈匹，君意合何如。"]', '["葛洪還有婦，王母亦有夫。","神仙尽靈匹，君意合何如。"]', '诗', 'shi', '', NULL, '書任生案 二 嵩山女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f35c52-ab86-453e-a912-44d97f6e6f4a', '臨去書贈', '臨去书贈', '20da54d0-5232-4aa2-93e9-1f0332647110', '唐', '["君子既執迷，無由達情素。","明月海山上，秋風獨歸去。"]', '["君子既執迷，無由達情素。","明月海山上，秋风独归去。"]', '诗', 'shi', '', NULL, '臨去書贈 嵩山女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad08d113-def2-47f4-aa66-8be02d8569cd', '與趙旭叩柱歌', '與趙旭叩柱歌', '6531fb83-1f37-4bdf-b1eb-09fadae4d320', '唐', '["白雲飄飄星漢斜，獨行窈窕浮雲車。","仙郎獨邀青童君，結情羅帳連心花。"]', '["白云飄飄星漢斜，独行窈窕浮云车。","仙郎独邀青童君，結情羅帳連心花。"]', '诗', 'shi', '', NULL, '與趙旭叩柱歌 青童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e0e4cc-8aa7-485e-a4e6-c431d5f7de3f', '題壁', '題壁', 'cec1cc0a-b6ed-4253-8051-0c9976acb1d6', '唐', '["南枝向暖北枝寒。","一種春花有兩般，憑仗高樓莫吹笛。","大家留取倚闌看。"]', '["南枝向暖北枝寒。","一種春花有兩般，憑仗高楼莫吹笛。","大家留取倚闌看。"]', '诗', 'shi', '', NULL, '題壁 觀梅女仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64683c2c-14ef-4e70-914f-157119d76128', '歌', '歌', '2c8a7966-2824-4087-b0d5-c56ca08c3cb1', '唐', '["若能相伴陟仙壇，應得文簫駕綵鸞。","自有繡襦幷甲帳，瑤臺不怕雪霜寒。"]', '["若能相伴陟仙壇，應得文簫駕綵鸾。","自有繡襦幷甲帳，瑤台不怕雪霜寒。"]', '诗', 'shi', '', NULL, '歌 吳彩鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb951c92-6c9a-4713-b7ee-f5aac3e5e9f9', '臨化絕句', '臨化絕句', 'e6d1da1c-715d-41f2-860c-eee1268b2fb4', '唐', '["翫水登山無足時，諸仙頻下聽吟詩。","此心不戀居人世，唯見天邊雙鶴飛。"]', '["翫水登山無足时，諸仙頻下听吟诗。","此心不戀居人世，唯见天邊雙鹤飞。"]', '诗', 'shi', '', NULL, '臨化絕句 王氏女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c968049f-8c49-4ce4-aca2-4b06ccb86bf7', '贈華山遊人 一', '贈华山游人 一', '28529176-223d-465b-b8ba-0d8294abc696', '唐', '["藥苗不滿笥，又更上危巔。","回首歸去路，相將入翠煙。"]', '["藥苗不满笥，又更上危巔。","回首归去路，相將入翠煙。"]', '诗', 'shi', '', NULL, '贈華山遊人 一 毛女正美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d5a8af8-2649-4c59-85af-827412c6370e', '贈華山遊人 二', '贈华山游人 二', '28529176-223d-465b-b8ba-0d8294abc696', '唐', '["曾折松枝爲寶櫛，又編栗葉代羅襦。","有時問却秦宮事，笑撚山花望太虛。"]', '["曾折松枝爲寶櫛，又編栗葉代羅襦。","有时问却秦宮事，笑撚山花望太虛。"]', '诗', 'shi', '', NULL, '贈華山遊人 二 毛女正美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2448d0a8-c93e-4850-a6bd-dbd0605b2338', '在紫霄夫人席上作', '在紫霄夫人席上作', '558537ad-5fe0-45ba-b144-efdbbd0e6f47', '唐', '["昔時訓子西河上，漢使經過問妾緣。","自到仙山不知老，凡間喚作幾千年。"]', '["昔时訓子西河上，漢使經過问妾緣。","自到仙山不知老，凡间喚作幾千年。"]', '诗', 'shi', '', NULL, '在紫霄夫人席上作 桃花夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5575eaf9-280a-4cf0-9a9b-e1d1f3ce55e4', '荅孫玄照', '荅孫玄照', '296233df-7311-4e03-bd17-e385ff43205e', '唐', '["鴛鴦相見不相隨，籠裏籠前整羽衣。","但得他時人放去，水中長作一雙飛。"]', '["鴛鴦相见不相隨，籠裏籠前整羽衣。","但得他时人放去，水中长作一雙飞。"]', '诗', 'shi', '', NULL, '荅孫玄照 王仙仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2831f1-9de1-4bb8-8a1b-aa7abaa12011', '孫玄照琴中歌贈王仙仙', '孫玄照琴中歌贈王仙仙', '296233df-7311-4e03-bd17-e385ff43205e', '唐', '["相如曾作鳳兮吟，昔被文君會此音。","今日孤鸞還獨語，痛哉仙子不彈琴。"]', '["相如曾作鳳兮吟，昔被文君會此音。","今日孤鸾還独語，痛哉仙子不彈琴。"]', '诗', 'shi', '', NULL, '孫玄照琴中歌贈王仙仙 王仙仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0c5185-5175-4a19-bfed-4f735ff4e6da', '臨刑賦', '臨刑賦', '2d1ef479-a477-4fbf-bc9f-37a6acd3a6d1', '唐', '["聖主何曾識仲都，可嗟社稷在須臾。","市東便是神仙窟，何必乘舟泛五湖。"]', '["聖主何曾識仲都，可嗟社稷在須臾。","市东便是神仙窟，何必乘舟泛五湖。"]', '诗', 'shi', '', NULL, '臨刑賦 楊損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3906ea25-4f0e-43fa-b512-f43828046322', '別遙見詩', '別遙见诗', '4b3b4adf-4bf2-4b0f-b2ef-d10362c252ac', '唐', '["手攀橋柱立，滴淚天河滿。"]', '["手攀橋柱立，滴泪天河满。"]', '诗', 'shi', '', NULL, '別遙見詩 妙女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1545e3-905f-43de-858c-98374a6b76d9', '宴柳毅詩 一', '宴柳毅诗 一', '19f0aa73-2e8b-489d-82fe-011eecd37f97', '唐', '["大天蒼蒼兮大地茫茫，人各有志兮何可思量。","狐神鼠聖兮薄社依牆，雷霆一發兮其孰敢當。","荷貞人兮信義長，令骨肉兮還故鄉，永言慚愧兮何時忘。"]', '["大天蒼蒼兮大地茫茫，人各有志兮何可思量。","狐神鼠聖兮薄社依牆，雷霆一發兮其孰敢當。","荷貞人兮信義长，令骨肉兮還故乡，永言慚愧兮何时忘。"]', '诗', 'shi', '', NULL, '宴柳毅詩 一 洞庭龍君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d050685-8416-4e78-a6ac-096fe27fded1', '宴柳毅詩 二', '宴柳毅诗 二', '19f0aa73-2e8b-489d-82fe-011eecd37f97', '唐', '["上天配合兮生死有途，此不當婦兮彼不當夫。","腹心辛苦兮涇水之隅，風霜滿鬢兮雨雪羅襦。","賴明公兮引素書，令肉骨兮家如初，永言珍重兮無時無。"]', '["上天配合兮生死有途，此不當婦兮彼不當夫。","腹心辛苦兮涇水之隅，风霜满鬢兮雨雪羅襦。","賴明公兮引素书，令肉骨兮家如初，永言珍重兮無时無。"]', '诗', 'shi', '', NULL, '宴柳毅詩 二 洞庭龍君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697772c3-7516-49b7-a8ef-a5312c2ae623', '宴柳毅詩 三', '宴柳毅诗 三', '19f0aa73-2e8b-489d-82fe-011eecd37f97', '唐', '["碧雲悠悠兮涇水東流，傷嗟美人兮雨泣花愁。","尺書遠達兮以解君憂，哀冤果雪兮還處其休。","荷君和雅兮感甘羞，山家寂寞兮難久留，欲將辭去兮悲綢繆。"]', '["碧云悠悠兮涇水东流，傷嗟美人兮雨泣花愁。","尺书远達兮以解君憂，哀冤果雪兮還处其休。","荷君和雅兮感甘羞，山家寂寞兮难久留，欲將辞去兮悲綢繆。"]', '诗', 'shi', '', NULL, '宴柳毅詩 三 洞庭龍君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965332d6-1602-4003-a7d8-d69eaff9e5f1', '鑄鏡歌', '鑄镜歌', '83a77ab1-1e4e-4f5a-9e83-f0ecb2c5bc59', '唐', '["盤龍盤龍，隱於鏡中。","分野有象，變化無窮。","興雲吐霧，行雨生風。","上清仙子，來獻聖聰。"]', '["盤龙盤龙，隐於镜中。","分野有象，变化無窮。","兴云吐霧，行雨生风。","上清仙子，来獻聖聰。"]', '诗', 'shi', '', NULL, '鑄鏡歌 龍護老人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056dfdd9-a76a-46e6-ab01-a96184e9e738', '示韋泛祿命', '示韋泛祿命', 'a3b00368-dd35-4db6-b5d9-019a21630686', '唐', '["前陽復後楊，後楊年年強，七月之節歸玄鄉。"]', '["前陽复後楊，後楊年年強，七月之節归玄乡。"]', '诗', 'shi', '', NULL, '示韋泛祿命 冥吏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b57e62-f23e-498d-8c97-432593281217', '贈僧', '贈僧', 'f00aadc4-7521-400e-975f-e1843580e98a', '唐', '["卓立不求名出家，長懷片志在青霞。","今日英雄氣衝蓋，誰能久坐寶蓮花。"]', '["卓立不求名出家，长懷片志在青霞。","今日英雄氣衝蓋，誰能久坐寶蓮花。"]', '诗', 'shi', '', NULL, '贈僧 滕傳胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a119d44-ab04-4a6a-abee-d8e05dd71c13', '贈人', '贈人', 'f00aadc4-7521-400e-975f-e1843580e98a', '唐', '["平生才不足，立身信有餘。","自歎無大故，君子莫相疎。"]', '["平生才不足，立身信有餘。","自歎無大故，君子莫相疎。"]', '诗', 'shi', '', NULL, '贈人 滕傳胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ff9483-06a6-4aed-a300-34a8205c8bf6', '鄭鋒宅神詩 一', '鄭鋒宅神诗 一', 'f00aadc4-7521-400e-975f-e1843580e98a', '唐', '["浦口潮來初淼漫，蓮舟搖颺採花難。","春心不愜空歸去，會待潮回更折看。"]', '["浦口潮来初淼漫，蓮舟搖颺採花难。","春心不愜空归去，會待潮回更折看。"]', '诗', 'shi', '', NULL, '鄭鋒宅神詩 一 滕傳胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40eba435-4026-4127-b9c3-d9d5491689e2', '鄭鋒宅神詩 二', '鄭鋒宅神诗 二', 'f00aadc4-7521-400e-975f-e1843580e98a', '唐', '["忽然湖上片雲飛，不覺舟中雨濕衣。","折得蓮花渾忘却，空將荷葉蓋頭歸。"]', '["忽然湖上片云飞，不覺舟中雨濕衣。","折得蓮花渾忘却，空將荷葉蓋头归。"]', '诗', 'shi', '', NULL, '鄭鋒宅神詩 二 滕傳胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7957fca4-d2bb-4cbf-98c6-0c54d1b96533', '與鄭德璘奇遇詩 一', '與鄭德璘奇遇诗 一', 'f1a0e5f1-402e-4ae8-b0cc-0a42ea1eb030', '唐', '["物觸輕舟心自知，風恬煙靜月光微。","夜深江上解愁思，拾得紅蕖香惹衣。"]', '["物觸轻舟心自知，风恬煙静月光微。","夜深江上解愁思，拾得紅蕖香惹衣。"]', '诗', 'shi', '', NULL, '與鄭德璘奇遇詩 一 水府君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f8d7f0-aa2b-40a6-9c64-ce4fdf23ce64', '與鄭德璘奇遇詩 二', '與鄭德璘奇遇诗 二', 'f1a0e5f1-402e-4ae8-b0cc-0a42ea1eb030', '唐', '["纖手垂鉤對水窗，紅蕖秋色豔長江。","既能解珮投交甫，更有明珠乞一雙。"]', '["纖手垂鉤对水窗，紅蕖秋色豔长江。","既能解珮投交甫，更有明珠乞一雙。"]', '诗', 'shi', '', NULL, '與鄭德璘奇遇詩 二 水府君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c037d762-fb09-4928-9f9f-05dca5c10e38', '與鄭德璘奇遇詩 三', '與鄭德璘奇遇诗 三', 'f1a0e5f1-402e-4ae8-b0cc-0a42ea1eb030', '唐', '["湖面狂風且莫吹，浪花初綻月光微。","沈潛暗想橫波淚，得共鮫人相對垂。"]', '["湖面狂风且莫吹，浪花初綻月光微。","沈潛暗想橫波泪，得共鮫人相对垂。"]', '诗', 'shi', '', NULL, '與鄭德璘奇遇詩 三 水府君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc34854f-5433-4682-967e-204482515030', '與鄭德璘奇遇詩 四', '與鄭德璘奇遇诗 四', 'f1a0e5f1-402e-4ae8-b0cc-0a42ea1eb030', '唐', '["洞庭風軟荻花秋，新沒青娥細浪愁。","淚滴白蘋君不見，月明江上有輕鷗。"]', '["洞庭风軟荻花秋，新沒青娥細浪愁。","泪滴白蘋君不见，月明江上有轻鷗。"]', '诗', 'shi', '', NULL, '與鄭德璘奇遇詩 四 水府君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8830b52-1653-44d8-935e-3ef94afe5616', '與鄭德璘奇遇詩 五', '與鄭德璘奇遇诗 五', 'f1a0e5f1-402e-4ae8-b0cc-0a42ea1eb030', '唐', '["昔日江頭菱芡人，蒙君數飲松醪春。","活君家室以爲報，珍重長沙鄭德璘。"]', '["昔日江头菱芡人，蒙君數饮松醪春。","活君家室以爲報，珍重长沙鄭德璘。"]', '诗', 'shi', '', NULL, '與鄭德璘奇遇詩 五 水府君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8414dd83-1032-4cbb-acfa-8b8d67edc13e', '笑巫詩', '笑巫诗', '6f8d7cdf-b777-4953-985e-16fbdfef978b', '唐', '["魍魎何曾見，頭旋即下神。","圖他衫子段，詐道大王嗔。"]', '["魍魎何曾见，头旋即下神。","圖他衫子段，詐道大王嗔。"]', '诗', 'shi', '', NULL, '笑巫詩 李序 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('443aef9a-d576-404a-b4b6-fc2fb7ff074a', '霅溪夜宴詩 一', '霅溪夜宴诗 一', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["濁波揚揚兮凝曉霧，公無渡河兮公竟渡。","風號水激兮呼不聞，提衣看入兮中流去。","浪排衣兮隨步沒，沈屍深入兮蛟螭窟。","蛟螭盡醉兮君血乾，推出黃沙兮泛君骨。","當時君死兮妾何適，遂就波瀾兮合魂魄。","願持精衛銜石心，窮斷河源塞泉脉。"]', '["濁波揚揚兮凝晓霧，公無渡河兮公竟渡。","风號水激兮呼不闻，提衣看入兮中流去。","浪排衣兮隨步沒，沈屍深入兮蛟螭窟。","蛟螭尽醉兮君血乾，推出黄沙兮泛君骨。","當时君死兮妾何適，遂就波瀾兮合魂魄。","願持精衛銜石心，窮斷河源塞泉脉。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 一 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfe1fcc2-c0f2-4ef9-8d0e-bb66936b1741', '霅溪夜宴詩 二', '霅溪夜宴诗 二', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["悲風淅淅兮波緜緜，蘆花萬里兮凝蒼煙。","虬螭窟宅兮淵且玄，排波疊浪兮沈我天。","所覆不全兮身寧全，溢眸恨血兮徒漣漣。","誓將柔荑抉鋸牙之喙，空水府而藏其腥涎。","青娥翠黛兮沈江壖，碧雲斜月兮空嬋娟。","吞聲飲恨兮語無力，徒揚哀怨兮登歌筵。"]', '["悲风淅淅兮波緜緜，蘆花万里兮凝蒼煙。","虬螭窟宅兮淵且玄，排波叠浪兮沈我天。","所覆不全兮身寧全，溢眸恨血兮徒漣漣。","誓將柔荑抉鋸牙之喙，空水府而藏其腥涎。","青娥翠黛兮沈江壖，碧云斜月兮空嬋娟。","吞声饮恨兮語無力，徒揚哀怨兮登歌筵。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 二 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('766e405b-c3d9-423e-81bd-aca8596462c1', '霅溪夜宴詩 三', '霅溪夜宴诗 三', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["白露漙兮西風高，碧波萬里兮翻洪濤。","莫言天下至柔者，載舟覆舟皆我曹。"]', '["白露漙兮西风高，碧波万里兮翻洪濤。","莫言天下至柔者，載舟覆舟皆我曹。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 三 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9115c233-20ce-4533-b5ed-d1a33161a813', '霅溪夜宴詩 四', '霅溪夜宴诗 四', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["君不見夜來渡口擁千艘，中載萬姓之脂膏。","當樓船泛泛於疊浪，恨珠貝又輕於鴻毛。","又不見朝來津亭維一舠，中有一士青其袍。","赴宰邑之良日，任波吼而風號。","是知溺名溺利者，不免爲水府之腥臊。"]', '["君不见夜来渡口擁千艘，中載万姓之脂膏。","當楼船泛泛於叠浪，恨珠貝又轻於鴻毛。","又不见朝来津亭維一舠，中有一士青其袍。","赴宰邑之良日，任波吼而风號。","是知溺名溺利者，不免爲水府之腥臊。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 四 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac380cb-d3c5-4039-87fc-0682da7a9dc7', '霅溪夜宴詩 五', '霅溪夜宴诗 五', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["山勢縈迴水脉分，水光山色翠連雲。","四時盡入詩人詠，役殺吳興柳使君。"]', '["山勢縈迴水脉分，水光山色翠連云。","四时尽入诗人詠，役殺吳兴柳使君。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 五 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c5b310-a463-4e68-861c-8aae7e1d3726', '霅溪夜宴詩 六', '霅溪夜宴诗 六', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["渺渺煙波接九疑，幾人經此泣江蘺。","年年綠水青山色，不改重華南狩時。"]', '["渺渺煙波接九疑，幾人經此泣江蘺。","年年綠水青山色，不改重华南狩时。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 六 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e70c5f9-e934-413c-a3b1-ae9f91df6e87', '霅溪夜宴詩 七', '霅溪夜宴诗 七', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["浪闊波澄秋氣涼，沈沈水殿夜初長。","自憐休退五湖客，何幸追陪百谷王。","香裊碧雲飄几席，觥飛白玉豔椒漿。","酒酣獨泛扁舟去，笑入琴高不死鄉。"]', '["浪闊波澄秋氣涼，沈沈水殿夜初长。","自怜休退五湖客，何幸追陪百谷王。","香裊碧云飄几席，觥飞白玉豔椒漿。","酒酣独泛扁舟去，笑入琴高不死乡。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 七 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed06c39c-7949-4516-af8d-e2c14c51adaf', '霅溪夜宴詩 八', '霅溪夜宴诗 八', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["珠光龍耀火燑燑，夜接朝雲宴渚宮。","鳳管清吹淒極浦，朱弦間奏冷秋空。","論心幸遇同歸友，揣分慙無輔佐功。","雲雨各飛真境後，不堪波上起悲風。"]', '["珠光龙耀火燑燑，夜接朝云宴渚宮。","鳳管清吹淒極浦，朱弦间奏冷秋空。","論心幸遇同归友，揣分慙無輔佐功。","云雨各飞真境後，不堪波上起悲风。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 八 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('509185c6-c881-45f1-890f-cc013387158d', '霅溪夜宴詩 九', '霅溪夜宴诗 九', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["鳳鶱鶱以降瑞兮，患山雞之雜飛。","玉溫溫以呈器兮，因碔砆之爭輝。","當侯門之四闢兮，墐嘉謨之重扉。","既瑞器而無庸兮，宜昏暗之相微。","徒刳石以爲舟兮，顧沿流而志違。","將刻木而作羽兮，與超騰之理非。","矜孑孑於空江兮，靡羣援之可依。","血淋淋而滂流兮，顧江魚之腹而將歸。","西風蕭蕭兮湘水悠悠，白芷芳歇兮江蘺秋。","日晼晼兮川雲收，櫂四起兮悲風幽。","羈魂汨沒兮我名永浮，碧波雖涸兮厥譽長流。","向使甘言盛行於曩昔，豈今日居君王之座頭。","是知貪名徇祿而隨世磨滅者，雖正寢之死乎無得與吾儔。","當鼎足之嘉會兮，獲周旋於君侯。","雕盤玉豆兮羅珍羞，金巵瓊斝兮方獻酬。","敢寫心兮歌一曲，無誚余持杯以淹留。"]', '["鳳鶱鶱以降瑞兮，患山雞之杂飞。","玉溫溫以呈器兮，因碔砆之爭輝。","當侯门之四闢兮，墐嘉謨之重扉。","既瑞器而無庸兮，宜昏暗之相微。","徒刳石以爲舟兮，顧沿流而志違。","將刻木而作羽兮，與超腾之理非。","矜孑孑於空江兮，靡羣援之可依。","血淋淋而滂流兮，顧江鱼之腹而將归。","西风蕭蕭兮湘水悠悠，白芷芳歇兮江蘺秋。","日晼晼兮川云收，櫂四起兮悲风幽。","羈魂汨沒兮我名永浮，碧波雖涸兮厥譽长流。","向使甘言盛行於曩昔，豈今日居君王之座头。","是知貪名徇祿而隨世磨滅者，雖正寢之死乎無得與吾儔。","當鼎足之嘉會兮，獲周旋於君侯。","雕盤玉豆兮羅珍羞，金巵瓊斝兮方獻酬。","敢寫心兮歌一曲，無誚余持杯以淹留。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 九 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b3782b-ad35-487d-bf76-69c5762a54d7', '霅溪夜宴詩 十', '霅溪夜宴诗 十', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["行殿秋未晚，水宮風初涼。","誰言此中夜，得接朝宗行。","靈鼉振鼕鼕，神龍耀煌煌。","紅樓壓波起，翠幄連雲張。","玉簫冷吟秋，瑤瑟清含商。","賢臻江湖叟，貴列川瀆王。","諒予衰俗人，無能振頹綱。","分辭皆亂世，樂寐蛟螭鄉。","棲遲幽島間，幾見波成桑。","爾來盡流俗，難與傾壺觴。","今日登華筵，稍覺神揚揚。","方歡滄浪侶，遽恐白日光。","海人瑞錦前，豈敢言文章。","聊歌靈境會，此會誠難忘。"]', '["行殿秋未晚，水宮风初涼。","誰言此中夜，得接朝宗行。","靈鼉振鼕鼕，神龙耀煌煌。","紅楼壓波起，翠幄連云張。","玉簫冷吟秋，瑤瑟清含商。","賢臻江湖叟，貴列川瀆王。","諒予衰俗人，無能振頹綱。","分辞皆亂世，乐寐蛟螭乡。","棲遲幽島间，幾见波成桑。","爾来尽流俗，难與傾壺觴。","今日登华筵，稍覺神揚揚。","方歡滄浪侶，遽恐白日光。","海人瑞錦前，豈敢言文章。","聊歌靈境會，此會誠难忘。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 十 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9e7fbd-6435-4971-bdef-2b42415f7011', '霅溪夜宴詩 十一', '霅溪夜宴诗 十一', 'cb844b51-85f1-4d0a-ab45-39aaad45029a', '唐', '["雪集大野兮血波洶洶，玄黃交戰兮吳無全隴。","既霸業之將墜，宜嘉謨之不從。","國步顛蹶兮吾道遘凶，處鴟夷之大困，入淵泉之九重。","上帝愍余之非辜兮，俾大江鼓怒其冤蹤。","所以鞭浪山而疾驅波岳，亦粗足展余拂鬱之心胸。","當靈境之良宴兮，謬尊俎之相容。","擊簫鼓兮撞歌鐘，吳謳越舞兮歡未極。","遽軍城曉鼓之鼕鼕，願保上善之柔德，何行樂之地兮難相逢。"]', '["雪集大野兮血波洶洶，玄黄交戰兮吳無全隴。","既霸業之將墜，宜嘉謨之不從。","国步顛蹶兮吾道遘凶，处鴟夷之大困，入淵泉之九重。","上帝愍余之非辜兮，俾大江鼓怒其冤蹤。","所以鞭浪山而疾驱波岳，亦粗足展余拂鬱之心胸。","當靈境之良宴兮，謬尊俎之相容。","擊簫鼓兮撞歌鐘，吳謳越舞兮歡未極。","遽軍城晓鼓之鼕鼕，願保上善之柔德，何行乐之地兮难相逢。"]', '诗', 'shi', '', NULL, '霅溪夜宴詩 十一 水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77abf3f4-f065-4ba8-9bce-17f486ac7f72', '爲劉洪作 一', '爲劉洪作 一', '5595ee65-b5dd-465c-a8ba-0ae3a66d93ee', '唐', '["烏烏在虛飛，玄駒遂野依。","名今編戶籍，翠過葉生稀。"]', '["烏烏在虛飞，玄駒遂野依。","名今編戶籍，翠過葉生稀。"]', '诗', 'shi', '', NULL, '爲劉洪作 一 輔國將軍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e3277e-8819-45cf-9266-4054a13253b5', '爲劉洪作 二', '爲劉洪作 二', '5595ee65-b5dd-465c-a8ba-0ae3a66d93ee', '唐', '["箇樹枝條朽，三花五面啼。","移家朝度日，誰覺。"]', '["箇樹枝條朽，三花五面啼。","移家朝度日，誰覺。"]', '诗', 'shi', '', NULL, '爲劉洪作 二 輔國將軍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d9b6cf-8b79-4a29-92ca-c904ab71934d', '語', '語', '0a0ce98b-0407-4698-b645-4c415e4155cf', '唐', '["三珠併一珠，驢馬沒人驅。","歲月甲庚午，中興戊己土。"]', '["三珠併一珠，驢马沒人驱。","歲月甲庚午，中兴戊己土。"]', '诗', 'shi', '', NULL, '語 太白山神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f941d2-1358-4c09-933f-eb71c6357671', '月夜吟', '月夜吟', '7fc6b64e-dafb-4594-a504-237661b0d69f', '唐', '["夜月明皎皎，綠波空悠悠。"]', '["夜月明皎皎，綠波空悠悠。"]', '诗', 'shi', '', NULL, '月夜吟 瀵水神 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141fdb68-9238-4009-ae59-d94bec621805', '荅鄭生歌', '荅鄭生歌', '120cbfcc-a4d2-4948-9ce3-d63280469804', '唐', '["泝青山兮江之隅，拖湘波兮褭綠裾。","荷拳拳兮情未舒，匪同歸兮將焉如。"]', '["泝青山兮江之隅，拖湘波兮褭綠裾。","荷拳拳兮情未舒，匪同归兮將焉如。"]', '诗', 'shi', '', NULL, '荅鄭生歌 湘中蛟女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7826f39-117b-4bf5-9fce-436d18586bc2', '風光詞', '风光词', '120cbfcc-a4d2-4948-9ce3-d63280469804', '唐', '["隆佳秀兮昭盛時，播薰綠兮淑華歸。","故里荑與處萼兮，潛重房以飾姿。","見雅態之韶華兮，蒙長靄以爲幃。","醉融光兮渺渺瀰瀰，迷千里兮涵煙眉，晨陶陶兮暮熙熙。","舞嫋娜之穠條兮，娉盈盈以披遲。","酡遊顏兮倡蔓卉縠，流倩電兮石髮髓施。"]', '["隆佳秀兮昭盛时，播薰綠兮淑华归。","故里荑與处萼兮，潛重房以飾姿。","见雅態之韶华兮，蒙长靄以爲幃。","醉融光兮渺渺瀰瀰，迷千里兮涵煙眉，晨陶陶兮暮熙熙。","舞嫋娜之穠條兮，娉盈盈以披遲。","酡游顏兮倡蔓卉縠，流倩電兮石髮髓施。"]', '诗', 'shi', '', NULL, '風光詞 湘中蛟女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f794197-d3b9-4aae-85ed-3541006e307a', '鄭生詩', '鄭生诗', '120cbfcc-a4d2-4948-9ce3-d63280469804', '唐', '["情無垠兮水湯湯，懷佳期兮屬三湘。"]', '["情無垠兮水湯湯，懷佳期兮屬三湘。"]', '诗', 'shi', '', NULL, '鄭生詩 湘中蛟女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aafb29e-81e1-4b71-9d05-80410e0f40b4', '感懷詩', '感懷诗', '113c1ea2-c36f-41b9-9a39-50203c32f2e8', '唐', '["海門連洞庭，每去三千里。","十載一歸來，辛苦瀟湘水。"]', '["海门連洞庭，每去三千里。","十載一归来，辛苦瀟湘水。"]', '诗', 'shi', '', NULL, '感懷詩 龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fbb2e17-e94c-4516-b541-e721cca3a118', '寄張無頗 一', '寄張無頗 一', '959734cc-303c-4d65-9b80-396ba36477cc', '唐', '["羞解明璫尋漢渚，但憑春夢訪天涯。","紅樓日暮鶯飛去，愁殺深宮落砌花。"]', '["羞解明璫尋漢渚，但憑春梦訪天涯。","紅楼日暮鶯飞去，愁殺深宮落砌花。"]', '诗', 'shi', '', NULL, '寄張無頗 一 廣利王女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ced1bb5-7b43-4459-a8e0-f0d9d0014b56', '寄張無頗 二', '寄張無頗 二', '959734cc-303c-4d65-9b80-396ba36477cc', '唐', '["燕語春泥墮錦筵，情愁無意整花鈿。","寒閨欹枕不成夢，香炷金爐自褭煙。"]', '["燕語春泥墮錦筵，情愁無意整花鈿。","寒閨欹枕不成梦，香炷金爐自褭煙。"]', '诗', 'shi', '', NULL, '寄張無頗 二 廣利王女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d1ac0c-f49b-4d0b-94eb-ea6e79092fc1', '與崔渥冥會雜詩 一', '與崔渥冥會杂诗 一', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["萬里同心別九重，定知涉歷此相逢。","誰人翻向羣峰路，不得蒼梧徇玉容。"]', '["万里同心別九重，定知涉歷此相逢。","誰人翻向羣峰路，不得蒼梧徇玉容。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 一 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3020d487-d5dc-4f3e-802d-e1f1ea003791', '與崔渥冥會雜詩 二', '與崔渥冥會杂诗 二', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["春鳥交交引思濃，豈期塵跡拜仙宮。","鸞歌鳳舞飄珠翠，疑是陽臺一夢中。"]', '["春鸟交交引思濃，豈期塵跡拜仙宮。","鸾歌鳳舞飄珠翠，疑是陽台一梦中。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 二 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cef843e-8225-4e51-87f8-2d709a782dd8', '與崔渥冥會雜詩 三', '與崔渥冥會杂诗 三', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["鸞輿昔日出蒲關，一去蒼梧更不還。","若是不留千古恨，湘江何事竹猶斑。"]', '["鸾輿昔日出蒲关，一去蒼梧更不還。","若是不留千古恨，湘江何事竹猶斑。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 三 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b8bbc6-048e-4938-ad95-34f19c7ce0b7', '與崔渥冥會雜詩 四', '與崔渥冥會杂诗 四', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["愁聞黃鳥夜關關，潙汭春來有夢還。","遺美代移刊勒絕，唯聞留得淚痕斑。"]', '["愁闻黄鸟夜关关，潙汭春来有梦還。","遺美代移刊勒絕，唯闻留得泪痕斑。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 四 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b953c9d-da28-4147-9eaf-d4607001fe55', '與崔渥冥會雜詩 五', '與崔渥冥會杂诗 五', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["方承恩寵醉金杯，豈爲干戈驟到來。","亡國破家皆有恨，捧心無語淚蘇臺。"]', '["方承恩寵醉金杯，豈爲干戈驟到来。","亡国破家皆有恨，捧心無語泪蘇台。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 五 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('542a2f65-cb67-4f19-bf56-965f0edaecd7', '與崔渥冥會雜詩 六', '與崔渥冥會杂诗 六', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["桃花流水兩堪傷，洞口煙波月漸長。","莫道仙家無別恨，至今垂淚憶劉郎。"]', '["桃花流水兩堪傷，洞口煙波月漸长。","莫道仙家無別恨，至今垂泪憶劉郎。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 六 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc1333f-f7dd-4e44-ad83-1dd21fe29bd6', '與崔渥冥會雜詩 七', '與崔渥冥會杂诗 七', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["涇陽平野草初春，遙望家鄉淚滴頻。","當此不知多少恨，至今空憶在靈姻。"]', '["涇陽平野草初春，遙望家乡泪滴頻。","當此不知多少恨，至今空憶在靈姻。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 七 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6daa9b40-b7e8-4388-92c4-27645aa6f0a3', '與崔渥冥會雜詩 八', '與崔渥冥會杂诗 八', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["目斷魂銷正惘然，九疑山際路漫漫。","何人知得心中恨，空有湘江竹萬竿。"]', '["目斷魂銷正惘然，九疑山際路漫漫。","何人知得心中恨，空有湘江竹万竿。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 八 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f5453e-2077-43f8-9a93-708e8dd8fbeb', '與崔渥冥會雜詩 九', '與崔渥冥會杂诗 九', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["常說仙家事不同，偶陪花月此宵中。","錦屏銀燭皆堪恨，惆悵紗窗向曉風。"]', '["常说仙家事不同，偶陪花月此宵中。","錦屏銀燭皆堪恨，惆悵紗窗向晓风。"]', '诗', 'shi', '', NULL, '與崔渥冥會雜詩 九 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd610be8-c732-4411-ae13-b806d8db8716', '又湘妃詩四首 一', '又湘妃诗四首 一', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["渺渺三湘萬里程，淚篁幽石助芳貞。","孤雲目斷蒼梧野，不得攀龍到玉京。"]', '["渺渺三湘万里程，泪篁幽石助芳貞。","孤云目斷蒼梧野，不得攀龙到玉京。"]', '诗', 'shi', '', NULL, '又湘妃詩四首 一 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc001ad-91a5-465b-81b0-f0513ba718df', '又湘妃詩四首 二', '又湘妃诗四首 二', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["碧杜紅蘅縹渺香，冰絲彈月弄清涼。","峰巒一一俱相似，九處堪疑九斷腸。"]', '["碧杜紅蘅縹渺香，冰絲彈月弄清涼。","峰巒一一俱相似，九处堪疑九斷腸。"]', '诗', 'shi', '', NULL, '又湘妃詩四首 二 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9153130-6590-4d1f-9080-2c55a996ca1e', '又湘妃詩四首 三', '又湘妃诗四首 三', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["玉輦金根去不回，湘川秋晚楚弦哀。","自從泣盡江蘺血，夜夜愁風怨雨來。"]', '["玉輦金根去不回，湘川秋晚楚弦哀。","自從泣尽江蘺血，夜夜愁风怨雨来。"]', '诗', 'shi', '', NULL, '又湘妃詩四首 三 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d27094-2012-4793-b7b9-45c28c060292', '又湘妃詩四首 四', '又湘妃诗四首 四', '1254b266-51f0-4fa8-ad88-0f284905521e', '唐', '["少將風月怨平湖，見盡扶桑水到枯。","相約杏花壇上去，畫闌紅子鬬摴蒲。"]', '["少將风月怨平湖，见尽扶桑水到枯。","相約杏花壇上去，畫闌紅子鬬摴蒲。"]', '诗', 'shi', '', NULL, '又湘妃詩四首 四 湘妃廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb728bd-1a66-4652-9d7f-de75ced9d144', '與何光遠贈荅詩 一', '與何光远贈荅诗 一', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["簷上簷前燕語新，花開柳發自傷神。","誰能將我相思意，說與江隈解佩人。"]', '["簷上簷前燕語新，花开柳發自傷神。","誰能將我相思意，说與江隈解佩人。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 一 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44fe8661-7ad4-4554-85de-960d2e8b1b2e', '與何光遠贈荅詩 二', '與何光远贈荅诗 二', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["坐久風吹綠綺寒，九天月照水精盤。","不思却返沈潛去，爲惜春光一夜歡。"]', '["坐久风吹綠綺寒，九天月照水精盤。","不思却返沈潛去，爲惜春光一夜歡。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 二 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5ca666-7cc9-4c01-aaa6-1c427df0f43f', '與何光遠贈荅詩 三', '與何光远贈荅诗 三', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["澹蕩春光物象饒，一枝瓊豔不勝嬌。","若能許解相思佩，何羨星天渡鵲橋。"]', '["澹蕩春光物象饒，一枝瓊豔不勝嬌。","若能許解相思佩，何羨星天渡鵲橋。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 三 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9710904-e560-4927-a85c-00031ef685ec', '與何光遠贈荅詩 四', '與何光远贈荅诗 四', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["玉漏涓涓銀漢清，鵲橋新架路初成。","催妝既要裁篇詠，鳳吹鸞歌早會迎。"]', '["玉漏涓涓銀漢清，鵲橋新架路初成。","催妝既要裁篇詠，鳳吹鸾歌早會迎。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 四 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea5f153-e506-4a55-910b-ab8538dc4691', '與何光遠贈荅詩 五', '與何光远贈荅诗 五', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["寶車輾駐彩雲開，誤到蓬萊頂上來。","瓊室既登花得折，永將凡骨逐風雷。"]', '["寶车輾駐彩云开，誤到蓬萊頂上来。","瓊室既登花得折，永將凡骨逐风雷。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 五 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f9eaea-b8cc-4c8a-ba88-9b6cf6810371', '與何光遠贈荅詩 六', '與何光远贈荅诗 六', 'e81d2b69-9268-4763-bfbc-fdb7d825ef11', '唐', '["負妾當時寤寐求，從茲粉面阻綢繆。","宮空月苦瑤雲斷，寂寞巴江水自流。"]', '["負妾當时寤寐求，從茲粉面阻綢繆。","宮空月苦瑤云斷，寂寞巴江水自流。"]', '诗', 'shi', '', NULL, '與何光遠贈荅詩 六 明月潭龍女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69451d07-5998-4bce-bf4d-6c6746449bf8', '寄紫蓋陽居士', '寄紫蓋陽居士', '8a9c4763-96b6-43e0-aa12-3115895f66d4', '唐', '["落葉棲鴉掩廟扉，菟絲金縷舊羅衣。","渡頭明月好攜手，獨自待郎郎不歸。"]', '["落葉棲鴉掩廟扉，菟絲金縷旧羅衣。","渡头明月好携手，独自待郎郎不归。"]', '诗', 'shi', '', NULL, '寄紫蓋陽居士 黃陵美人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458115a3-e80e-4ed1-bb63-c52418a6828a', '贈謝府君', '贈謝府君', '7cde51dc-f581-476b-a2cb-cdf9288f8130', '唐', '["玉釵空中墮，金釧色已歇。","獨泣謝春風，秋夜傷明月。"]', '["玉釵空中墮，金釧色已歇。","独泣謝春风，秋夜傷明月。"]', '诗', 'shi', '', NULL, '贈謝府君 吳興神女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6752206-b0e9-4179-87b2-e7e3e9a10d3b', '冢上荅太宗', '冢上荅太宗', 'bc59fd76-bc70-4308-9068-a3ff86830d3d', '唐', '["我昔勝君昔，君今勝我今。","榮華各異代，何用苦追尋。"]', '["我昔勝君昔，君今勝我今。","榮华各異代，何用苦追尋。"]', '诗', 'shi', '', NULL, '冢上荅太宗 慕容垂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf874dae-4f48-4794-aa63-95f599206f80', '遺畫工詩', '遺畫工诗', '22b3f19e-5321-4686-95c4-3d3b3e24fa63', '唐', '["握手不能別，撫膺聊自傷。","痛矣時陰短，悲哉泉路長。","松林驚野吹，荒隧落寒霜。","言離何以贈，留心內典章。"]', '["握手不能別，撫膺聊自傷。","痛矣时陰短，悲哉泉路长。","松林驚野吹，荒隧落寒霜。","言離何以贈，留心內典章。"]', '诗', 'shi', '', NULL, '遺畫工詩 釋明解 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('265812c5-0f1a-45fa-a5d3-2b8dbd7792cb', '夜吟', '夜吟', '5626e740-46ec-48a4-86df-b058a38dec75', '唐', '["秋逕填黃葉，寒摧露草根。","猨聲一叫斷，客淚數重痕。"]', '["秋逕填黄葉，寒摧露草根。","猨声一叫斷，客泪數重痕。"]', '诗', 'shi', '', NULL, '夜吟 巴峽鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f00bab2-b8ec-460e-aaa8-98cdc3bccaa9', '媿謝詩', '媿謝诗', '6a6af607-af61-4cfd-9ff4-10c6c514d1d1', '唐', '["我本邯鄲士，祇役死河湄。","不得家人哭，勞君行路悲。"]', '["我本邯鄲士，祇役死河湄。","不得家人哭，勞君行路悲。"]', '诗', 'shi', '', NULL, '媿謝詩 河[湄]鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b895e2f9-93cd-427c-9be7-13970593e675', '擲裴武公詩', '擲裴武公诗', 'd89ed47b-1ea6-46dd-88da-fcd31fcad0eb', '唐', '["屢策羸驂歷亂峋，叢嵐映日晝如曛。","長橋駕險浮天漢，危棧通岐觸岫雲。","却念淮陰空得計，又嗟忠武不堪聞。","廢興盡係前生數，休衒英雄勇冠軍。"]', '["屢策羸驂歷亂峋，叢嵐映日晝如曛。","长橋駕險浮天漢，危棧通岐觸岫云。","却念淮陰空得計，又嗟忠武不堪闻。","廢兴尽係前生數，休衒英雄勇冠軍。"]', '诗', 'shi', '', NULL, '擲裴武公詩 介胄鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a77f0c-e26e-4849-a742-670c9e1d39b3', '死後詩', '死後诗', 'd28e2059-56a6-4f3e-acf0-f40c92ccf9de', '唐', '["忽作無期別，沈冥恨有餘。","長安雖不遠，無信可傳書。"]', '["忽作無期別，沈冥恨有餘。","长安雖不远，無信可傳书。"]', '诗', 'shi', '', NULL, '死後詩 李叔霽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9436ddf6-87b6-4e44-8d7e-4d3220ae35cb', '洋州館夜吟', '洋州館夜吟', '91778728-0732-44e3-95f3-5cc2bd468d4d', '唐', '["門依楚水岸，身寄洋州館。","望月獨相思，塵襟淚痕滿。"]', '["门依楚水岸，身寄洋州館。","望月独相思，塵襟泪痕满。"]', '诗', 'shi', '', NULL, '洋州館夜吟 竇裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554e18b1-2974-4494-9944-d27e97065a68', '獻元載', '獻元載', 'e6c2666f-8831-4da8-844d-3d1d5d1b99d3', '唐', '["城東城西舊居處，城裏飛花亂如絮。","海燕銜泥欲下來，屋裏無人却飛去。"]', '["城东城西旧居处，城裏飞花亂如絮。","海燕銜泥欲下来，屋裏無人却飞去。"]', '诗', 'shi', '', NULL, '獻元載 書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff3423b6-1ade-4d54-9d47-2fa0ba78c92c', '詩二首 一', '诗二首 一', '2540078a-c541-4be1-86d8-52a36c70be21', '唐', '["高松多悲風，蕭蕭清且哀。","南山接幽壠，幽壠空崔嵬。","白日徒昭昭，不照長夜臺。","雖知生者樂，魂魄安能迴。","況復念所親，慟哭心肝摧。","慟哭更何言，哀哉復哀哉。"]', '["高松多悲风，蕭蕭清且哀。","南山接幽壠，幽壠空崔嵬。","白日徒昭昭，不照长夜台。","雖知生者乐，魂魄安能迴。","況复念所親，慟哭心肝摧。","慟哭更何言，哀哉复哀哉。"]', '诗', 'shi', '', NULL, '詩二首 一 虎丘山石壁鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163e52ed-0a3f-4f3e-b7d2-a43aad65bb5f', '詩二首 二', '诗二首 二', '2540078a-c541-4be1-86d8-52a36c70be21', '唐', '["神仙不可學，形化空遊魂。","白日非我朝，青松爲我門。","雖復隔幽顯，猶知念子孫。","何以遣悲惋，萬物歸其根。","寄語世上人，莫厭臨芳尊。","莊生問枯骨，三樂成虛言。"]', '["神仙不可学，形化空游魂。","白日非我朝，青松爲我门。","雖复隔幽显，猶知念子孫。","何以遣悲惋，万物归其根。","寄語世上人，莫厭臨芳尊。","莊生问枯骨，三乐成虛言。"]', '诗', 'shi', '', NULL, '詩二首 二 虎丘山石壁鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e70b481-13a4-4a55-9327-ec26f9096d33', '祭後見石上詩', '祭後见石上诗', '2540078a-c541-4be1-86d8-52a36c70be21', '唐', '["幽明雖異路，平昔忝攻文。","欲知潛昧處，山北兩孤墳。"]', '["幽明雖異路，平昔忝攻文。","欲知潛昧处，山北兩孤墳。"]', '诗', 'shi', '', NULL, '祭後見石上詩 虎丘山石壁鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef69a36-6030-45ba-b243-11b9157ac147', '詠浮雲', '詠浮云', '0b4b67db-24f2-4112-9d6e-db1da7f217ae', '唐', '["虛虛復空空，瞬息天地中。","假合成此像，吾亦非吾躬。"]', '["虛虛复空空，瞬息天地中。","假合成此像，吾亦非吾躬。"]', '诗', 'shi', '', NULL, '詠浮雲 陸憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cfd10dd-1cf4-4e85-895a-63bae64ee479', '呈李續', '呈李續', '88084306-21ee-442d-b4e2-9be6b7ca15f1', '唐', '["我有敵國讐，無人可爲雪。","每至秦隴頭，遊魂自嗚咽。"]', '["我有敵国讐，無人可爲雪。","每至秦隴头，游魂自嗚咽。"]', '诗', 'shi', '', NULL, '呈李續 韓弇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abfa3388-e75a-455c-9f10-499dac079933', '和崔侍御', '和崔侍御', '6832a93d-2e1c-48bc-82a1-d347d50ca6ca', '唐', '["千歲荒臺隳路隅，一煩太守重椒塗。","感君拂拭意何極，贈爾美婦與明珠。"]', '["千歲荒台隳路隅，一煩太守重椒塗。","感君拂拭意何極，贈爾美婦與明珠。"]', '诗', 'shi', '', NULL, '和崔侍御 尉佗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e818217-d7dc-4d98-ae45-6675788245e4', '贈竇丞', '贈竇丞', '3a0c0cd3-b06f-4a51-9d3b-699e78f54450', '唐', '["冥路杳杳人不知，不用苦說使人悲。","喜得逢君傳家信，後會茫茫何處期。"]', '["冥路杳杳人不知，不用苦说使人悲。","喜得逢君傳家信，後會茫茫何处期。"]', '诗', 'shi', '', NULL, '贈竇丞 劉溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1f726d-58a6-4851-bef6-0b22061762eb', '敘幽冤', '敘幽冤', '8a9c539c-5e23-44c9-8304-000b3e1f85c7', '唐', '["痛填心兮不能語，寸斷腸兮訴何處。","春生萬物妾不生，更恨香魂不相遇。"]', '["痛填心兮不能語，寸斷腸兮訴何处。","春生万物妾不生，更恨香魂不相遇。"]', '诗', 'shi', '', NULL, '敘幽冤 鄭瓊羅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8db6c08-db76-4baf-ac0d-71572c8823d3', '過臺城感舊', '過台城感旧', '5797a576-2a15-4461-b9c8-147185a2878c', '唐', '["六代舊山川，興亡幾百年。","繁華今寂寞，朝市昔諠闐。","夜月琉璃水，春風卵色天。","傷時與懷古，垂淚國門前。"]', '["六代旧山川，兴亡幾百年。","繁华今寂寞，朝市昔諠闐。","夜月琉璃水，春风卵色天。","傷时與懷古，垂泪国门前。"]', '诗', 'shi', '', NULL, '過臺城感舊 沈青箱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db54b041-1d93-49fc-97d5-70b8dd4a9e82', '詩', '诗', '940f2540-895a-4202-8306-44898e1363c1', '唐', '["流水涓涓芹努芽，織烏西飛客還家。","荒村無人作寒食，殯宮空對棠棃花。"]', '["流水涓涓芹努芽，织烏西飞客還家。","荒村無人作寒食，殯宮空对棠棃花。"]', '诗', 'shi', '', NULL, '詩 襄陽旅殯舉人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e3b002-01aa-4031-94fd-30001eb4ae48', '踏歌', '踏歌', 'de03b1a9-3d33-40fc-8e41-3680d125e84d', '唐', '["河水流溷溷，山頭種蕎麥。","兩箇胡孫門底來，東家阿嫂決一百。"]', '["河水流溷溷，山头種蕎麦。","兩箇胡孫门底来，东家阿嫂決一百。"]', '诗', 'shi', '', NULL, '踏歌 河中鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11b8b38-737f-43c8-9ea4-63b264d652d2', '題少陵別墅', '題少陵別墅', '14d58560-5b2b-41d8-8d02-677ce6548144', '唐', '["新構茅齋野澗東，松楸交影足悲風。","人間歲月如流水，何事頻行此路中。"]', '["新構茅斋野澗东，松楸交影足悲风。","人间歲月如流水，何事頻行此路中。"]', '诗', 'shi', '', NULL, '題少陵別墅 蕭微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d33b82-c31c-448a-beb5-d687325ab268', '夢張垂贈詩', '梦張垂贈诗', '258d7f0c-c704-4b9d-914a-5b7b056a85ac', '唐', '["戚戚復戚戚，秋堂百年色。","而我獨茫茫，荒郊遇寒食。"]', '["戚戚复戚戚，秋堂百年色。","而我独茫茫，荒郊遇寒食。"]', '诗', 'shi', '', NULL, '夢張垂贈詩 張省躬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ea9e47-b953-42f5-b3cf-37980278a8b9', '秋月聯句', '秋月聯句', '890e6f57-1c2d-476c-8271-87fdec09c94e', '唐', '["秋月圓如鏡，秋風利似刀。","秋雲輕比絮，秋草細如毛。"]', '["秋月圓如镜，秋风利似刀。","秋云轻比絮，秋草細如毛。"]', '诗', 'shi', '', NULL, '秋月聯句 商山三丈夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5edef38a-44bd-4625-9191-a30da70dedee', '天明聯句', '天明聯句', '890e6f57-1c2d-476c-8271-87fdec09c94e', '唐', '["幽樹高高影，山花寂寂香。","山天遙歷歷，山水急湯湯。"]', '["幽樹高高影，山花寂寂香。","山天遙歷歷，山水急湯湯。"]', '诗', 'shi', '', NULL, '天明聯句 商山三丈夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7986ee98-e3b0-44c9-8581-d41a992cedf5', '贈張珽', '贈張珽', '4d66122f-546d-4c75-8c58-2ed4363342ce', '唐', '["昔爲吟風嘯月人，今爲吟風嘯月身。","冢壞路邊吟嘯罷，安知今日又勞神。"]', '["昔爲吟风嘯月人，今爲吟风嘯月身。","冢壞路邊吟嘯罷，安知今日又勞神。"]', '诗', 'shi', '', NULL, '贈張珽 鄭適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88856142-89df-46b7-ad0a-989e525b842e', '西軒詩 一', '西軒诗 一', 'ef9031e2-1f18-4fa5-ad91-ba0f4bcda3cb', '唐', '["趙壹能爲賦，鄒陽解獻書。","可惜西江水，不救轍中魚。"]', '["趙壹能爲賦，鄒陽解獻书。","可惜西江水，不救轍中鱼。"]', '诗', 'shi', '', NULL, '西軒詩 一 甘露寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd714d2-3ac2-415f-8c87-dcc6547900a7', '西軒詩 二', '西軒诗 二', 'ef9031e2-1f18-4fa5-ad91-ba0f4bcda3cb', '唐', '["偉哉橫海鱗，壯矣垂天翼。","一旦失風水，翻爲螻蟻食。"]', '["偉哉橫海鱗，壯矣垂天翼。","一旦失风水，翻爲螻蟻食。"]', '诗', 'shi', '', NULL, '西軒詩 二 甘露寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa18000-095e-4941-bae2-038c38b62c5a', '西軒詩 三', '西軒诗 三', 'ef9031e2-1f18-4fa5-ad91-ba0f4bcda3cb', '唐', '["功遂侔昔人，保退無智力。","既涉太行險，茲路信難陟。"]', '["功遂侔昔人，保退無智力。","既涉太行險，茲路信难陟。"]', '诗', 'shi', '', NULL, '西軒詩 三 甘露寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9bd7d4-271f-4659-938a-d6923c46605b', '西軒詩 四', '西軒诗 四', 'ef9031e2-1f18-4fa5-ad91-ba0f4bcda3cb', '唐', '["握裏龍蛇紙上鸞，逡巡千幅不將難。","顧雲已往羅隱耄，更有何人逞筆端。"]', '["握裏龙蛇紙上鸾，逡巡千幅不將难。","顧云已往羅隐耄，更有何人逞笔端。"]', '诗', 'shi', '', NULL, '西軒詩 四 甘露寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88635f9f-b292-4fc7-806f-b60c20c91c39', '降巫詩', '降巫诗', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["青山山下少年郎，失意當時別故鄉。","惆悵不堪回首望，隔谿遙見舊書堂。"]', '["青山山下少年郎，失意當时別故乡。","惆悵不堪回首望，隔谿遙见旧书堂。"]', '诗', 'shi', '', NULL, '降巫詩 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40b1378-cdc5-45a5-9f41-166ad969b4e6', '贈雷殿直。', '贈雷殿直。', '9f2f4b29-3ed1-415d-a524-d84577cca477', '唐', '["衡陽去此正三年，一路程途甚坦然。","深邃門牆三楚外，清風池館五峰前。","西邊市井來商客，東岸汀洲簇釣船。","公退只應無別事，朱陵後洞看神仙。"]', '["衡陽去此正三年，一路程途甚坦然。","深邃门牆三楚外，清风池館五峰前。","西邊市井来商客，东岸汀洲簇釣船。","公退只應無別事，朱陵後洞看神仙。"]', '诗', 'shi', '', NULL, '贈雷殿直。 石恪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf7c29b8-d79f-4e75-872c-40b09f03afb0', '吟', '吟', 'aeab3218-7a77-4b06-b9e9-4ca76b200151', '唐', '["陊江三十年，潮打形骸朽。","家人都不知，何處奠杯酒。"]', '["陊江三十年，潮打形骸朽。","家人都不知，何处奠杯酒。"]', '诗', 'shi', '', NULL, '吟 富春沙際鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e3d31f-f10d-4607-a618-da73d3bf1d1c', '又吟', '又吟', 'aeab3218-7a77-4b06-b9e9-4ca76b200151', '唐', '["莫問我姓名，向君言亦空。","潮生沙骨冷，魂魄悲秋風。"]', '["莫问我姓名，向君言亦空。","潮生沙骨冷，魂魄悲秋风。"]', '诗', 'shi', '', NULL, '又吟 富春沙際鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5559e870-ae8a-4764-8446-4e573affb200', '獻高駢', '獻高駢', '02ab0315-2f78-4dff-96c6-b65a83f61746', '唐', '["我昔勝君昔，君今勝我今。","人生一世事，何用苦相侵。"]', '["我昔勝君昔，君今勝我今。","人生一世事，何用苦相侵。"]', '诗', 'shi', '', NULL, '獻高駢 趙𤰳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42582fe-3280-400f-b1df-13fb6e3bd852', '吟', '吟', '6fce7c7d-053a-4607-bf74-edcce04ebb5c', '唐', '["澗水潺潺聲不絕，溪壠茫茫野花發。","自去自來人不知，歸時唯對空山月。"]', '["澗水潺潺声不絕，溪壠茫茫野花發。","自去自来人不知，归时唯对空山月。"]', '诗', 'shi', '', NULL, '吟 九華山白衣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8905d150-130a-43d1-a1af-5967477ee838', '詩', '诗', 'af511f18-47a0-4879-beb5-10d4fc7fb102', '唐', '["天然與我一靈通，還與人間事不同。","要識吾家真姓字，天地南頭一段紅。"]', '["天然與我一靈通，還與人间事不同。","要識吾家真姓字，天地南头一段紅。"]', '诗', 'shi', '', NULL, '詩 田達誠借宅鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed549c13-ea5c-40f6-83e0-51fdaa7d0e4c', '秋夜吟', '秋夜吟', '1ba190ca-3085-4927-8917-a6bc5cd9e896', '唐', '["六街鼓歇行人絕，九衢茫茫室有月。","九衢生人何勞勞，長安土盡槐根高。"]', '["六街鼓歇行人絕，九衢茫茫室有月。","九衢生人何勞勞，长安土尽槐根高。"]', '诗', 'shi', '', NULL, '秋夜吟 長安中鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a04c045-cd9e-4576-aaab-97841fc5bae9', '題窗上詩', '題窗上诗', 'c855581c-e73c-4ac8-af01-d9c55f773980', '唐', '["何人窗下讀書聲，南斗闌干北斗橫。","千里思家歸不得，春風腸斷石頭城。"]', '["何人窗下读书声，南斗闌干北斗橫。","千里思家归不得，春风腸斷石头城。"]', '诗', 'shi', '', NULL, '題窗上詩 隔窗鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f240f42f-4bf0-4463-8026-4bb19f4db3af', '柱上詩', '柱上诗', 'c9f150f5-3253-4d08-8ad4-6bfdafb4805d', '唐', '["爺娘送我青楓根，不記青楓幾迴落。","當時手刺衣上花，今日爲灰不堪著。"]', '["爺娘送我青楓根，不記青楓幾迴落。","當时手刺衣上花，今日爲灰不堪著。"]', '诗', 'shi', '', NULL, '柱上詩 巴陵館鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5d220c-a1e9-4779-93a0-b9359d1fca2a', '留別安鳳', '留別安鳳', '279550af-31ce-4da6-9bda-79e0cfaa81ff', '唐', '["君寄長安久，恥不還故鄉。","我別長安去，切在慰高堂。","不意與離恨，泉下亦難忘。"]', '["君寄长安久，恥不還故乡。","我別长安去，切在慰高堂。","不意與離恨，泉下亦难忘。"]', '诗', 'shi', '', NULL, '留別安鳳 徐侃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15dc522d-0721-4e69-ab49-6e2ef357f9a3', '安鳳贈別徐侃', '安鳳贈別徐侃', '279550af-31ce-4da6-9bda-79e0cfaa81ff', '唐', '["一自離鄉國，十年在咸秦。","泣盡卞和血，不逢一故人。","今日舊友別，羞此漂泊身。","離情吟詩處，麻衣掩淚頻。","淚別各分袂，且及來年春。"]', '["一自離乡国，十年在咸秦。","泣尽卞和血，不逢一故人。","今日旧友別，羞此漂泊身。","離情吟诗处，麻衣掩泪頻。","泪別各分袂，且及来年春。"]', '诗', 'shi', '', NULL, '安鳳贈別徐侃 徐侃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e773542f-8f35-4a99-9b96-8c7c9b118a2d', '述懷 一', '述懷 一', '0a1bc1c9-f4f2-4f40-a572-faed5dcaeb3b', '唐', '["家住驛北路，百里無四鄰。","往來不相問，寂寂山家春。"]', '["家住驛北路，百里無四鄰。","往来不相问，寂寂山家春。"]', '诗', 'shi', '', NULL, '述懷 一 商山客死書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286527d0-f51f-4035-91e1-1216e23637d0', '述懷 二', '述懷 二', '0a1bc1c9-f4f2-4f40-a572-faed5dcaeb3b', '唐', '["南岡夜蕭蕭，青松與白楊。","家人應有夢，遠客已無腸。"]', '["南岡夜蕭蕭，青松與白楊。","家人應有梦，远客已無腸。"]', '诗', 'shi', '', NULL, '述懷 二 商山客死書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87499b24-d37b-49eb-858f-0289be3a359a', '述懷 三', '述懷 三', '0a1bc1c9-f4f2-4f40-a572-faed5dcaeb3b', '唐', '["白草寒露裏，亂山明月中。","是夕苦吟罷，寒燭與君同。"]', '["白草寒露裏，亂山明月中。","是夕苦吟罷，寒燭與君同。"]', '诗', 'shi', '', NULL, '述懷 三 商山客死書生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249fa103-26ff-4a6b-b3e4-dc45e21ef435', '續鄭郊吟', '續鄭郊吟', '292caec5-4a39-47fc-b7d9-bbdb46faa568', '唐', '["冢上兩竿竹，風吹常嫋嫋。","下有百年人，長眠不知曉。"]', '["冢上兩竿竹，风吹常嫋嫋。","下有百年人，长眠不知晓。"]', '诗', 'shi', '', NULL, '續鄭郊吟 冢中人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcfa1b4-12c5-4dbf-8619-efd97d123588', '題壁 一', '題壁 一', '40bb260b-3856-4647-b0d6-a456dcafbc57', '唐', '["禁煙佳節同遊此，正值酴醿夾岸香。","緬首十年前往事，強吟風景亂愁腸。"]', '["禁煙佳節同游此，正值酴醿夾岸香。","緬首十年前往事，強吟风景亂愁腸。"]', '诗', 'shi', '', NULL, '題壁 一 崇聖寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5895994c-913c-4df6-9f28-39511432cd56', '題壁 二', '題壁 二', '40bb260b-3856-4647-b0d6-a456dcafbc57', '唐', '["策馬暫尋原上路，落花芳草尚依然。","家亡國破一場夢，惆悵又逢寒食天。"]', '["策马暫尋原上路，落花芳草尚依然。","家亡国破一場梦，惆悵又逢寒食天。"]', '诗', 'shi', '', NULL, '題壁 二 崇聖寺鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832ce408-5aa4-44ce-9491-71041357cad4', '血書詩', '血书诗', 'cea3d57b-e92c-450e-b46b-3ebc52064e85', '唐', '["物類易遷變，我行人不見。","珍重任彥思，相別日已遠。"]', '["物類易遷变，我行人不见。","珍重任彥思，相別日已远。"]', '诗', 'shi', '', NULL, '血書詩 任彥思家鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d65fe3cd-9ae0-4e52-ba07-ffbf30daea86', '贈馬植', '贈马植', '4106169e-af64-4091-80ed-7abe529a93cf', '唐', '["截竹爲筒作笛吹，鳳凰池上鳳凰飛。","勞君更向黔南去，即是陶鈞萬類時。"]', '["截竹爲筒作笛吹，鳳凰池上鳳凰飞。","勞君更向黔南去，即是陶鈞万類时。"]', '诗', 'shi', '', NULL, '贈馬植 峽中白衣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba0c173-6974-4837-9bb9-5da9619bcd13', '題芭蕉葉上', '題芭蕉葉上', '1b902a66-30f7-447e-9a48-7c9245499552', '唐', '["寒食家家盡禁煙，野棠風墜小花鈿。","如今空有孤魂夢，半在嘉陵半錦川。"]', '["寒食家家尽禁煙，野棠风墜小花鈿。","如今空有孤魂梦，半在嘉陵半錦川。"]', '诗', 'shi', '', NULL, '題芭蕉葉上 張仁寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6403d78f-966f-453a-9d67-1f15803a466b', '官坡館聯句', '官坡館聯句', '213d3dc2-9e1a-4675-9dce-50c0c00b9fb3', '唐', '["牀頭錦衾班復班，架上朱衣殷復殷。","空庭朗月閑復閑，夜長路遠山復山。"]', '["牀头錦衾班复班，架上朱衣殷复殷。","空庭朗月闲复闲，夜长路远山复山。"]', '诗', 'shi', '', NULL, '官坡館聯句 崔常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f98f4a-2111-4c9c-b168-d703e15a1e16', '亡後見形詩', '亡後见形诗', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["異國非所志，煩勞殊清閑。","驚濤千萬里，無乃見鍾山。"]', '["異国非所志，煩勞殊清闲。","驚濤千万里，無乃见鍾山。"]', '诗', 'shi', '', NULL, '亡後見形詩 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726e16c3-72c4-410b-a7d8-776511bf3287', '同鹿門少年馬紹隆冥遊詩 一', '同鹿门少年马紹隆冥游诗 一', '03f28410-2a7a-4534-9a03-a22d80b0027d', '唐', '["千年故國歲華奔，一柱高臺已斷魂。","唯有峴亭清夜月，與君長嘯學蘇門。"]', '["千年故国歲华奔，一柱高台已斷魂。","唯有峴亭清夜月，與君长嘯学蘇门。"]', '诗', 'shi', '', NULL, '同鹿門少年馬紹隆冥遊詩 一 龐德公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8d2990-8205-43bb-bf3f-d4c06200ae55', '同鹿門少年馬紹隆冥遊詩 二', '同鹿门少年马紹隆冥游诗 二', '03f28410-2a7a-4534-9a03-a22d80b0027d', '唐', '["高名宋玉遺閑麗，作賦蘭成絕盛才。","誰似遼東千歲鶴，倚天華表却歸來。"]', '["高名宋玉遺闲丽，作賦蘭成絕盛才。","誰似遼东千歲鹤，倚天华表却归来。"]', '诗', 'shi', '', NULL, '同鹿門少年馬紹隆冥遊詩 二 龐德公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7621d29-d9ee-4cad-bfd3-a59e69f9b6bc', '貽常夷詩', '貽常夷诗', 'b075bfea-7694-44df-9f06-a07f1a19b985', '唐', '["平生遊城郭，殂沒委荒榛。","自我辭人世，不知秋與春。","牛羊久來牧，松柏幾成薪。","分絕車馬好，甘隨狐兔羣。","何處清風至，君子幸爲鄰。","烈烈盛名德，依依佇良賓。","千年何旦暮，一室動人神。","喬木如在望，通衢良易遵。","高門儻無隔，向與析龍津。"]', '["平生游城郭，殂沒委荒榛。","自我辞人世，不知秋與春。","牛羊久来牧，松柏幾成薪。","分絕车马好，甘隨狐兔羣。","何处清风至，君子幸爲鄰。","烈烈盛名德，依依佇良賓。","千年何旦暮，一室动人神。","喬木如在望，通衢良易遵。","高门儻無隔，向與析龙津。"]', '诗', 'shi', '', NULL, '貽常夷詩 朱均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0783a8b-1521-476e-9aa0-71ec7e44d0cf', '空館夜歌 一', '空館夜歌 一', 'cd51c849-1478-4308-9260-6e8f1bd4f0b6', '唐', '["明月清風，良宵會同。","星河易翻，歡娛不終。","綠樽翠杓，爲君斟酌。"]', '["明月清风，良宵會同。","星河易翻，歡娛不終。","綠樽翠杓，爲君斟酌。"]', '诗', 'shi', '', NULL, '空館夜歌 一 夷陵女郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0cdbce8-bc72-46b4-b74f-a42221bab4cc', '空館夜歌 二', '空館夜歌 二', 'cd51c849-1478-4308-9260-6e8f1bd4f0b6', '唐', '["楊柳楊柳，嫋嫋隨風急。","西樓美人春夢長，繡簾斜捲千條入。"]', '["楊柳楊柳，嫋嫋隨风急。","西楼美人春梦长，繡簾斜捲千條入。"]', '诗', 'shi', '', NULL, '空館夜歌 二 夷陵女郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc2d713-cb2c-4195-9081-fce8058a0cf2', '空館夜歌 三', '空館夜歌 三', 'cd51c849-1478-4308-9260-6e8f1bd4f0b6', '唐', '["[玉]戶金缸，願陪君王。","邯鄲宮中，金石絲簧。","衛女秦娥，左右成行。","紈縞繽紛，翠眉紅妝。","王歡顧盼，爲王歌舞。","願得君歡，常無災苦。"]', '["[玉]戶金缸，願陪君王。","邯鄲宮中，金石絲簧。","衛女秦娥，左右成行。","紈縞繽紛，翠眉紅妝。","王歡顧盼，爲王歌舞。","願得君歡，常無災苦。"]', '诗', 'shi', '', NULL, '空館夜歌 三 夷陵女郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5ffc84-b4dd-493d-8261-61a761a6c71f', '贈夫詩三首 一', '贈夫诗三首 一', 'b91bb430-9fee-4126-9305-087555bf9a47', '唐', '["不忿成故人，掩涕每盈巾。","死生今有隔，相見永無因。"]', '["不忿成故人，掩涕每盈巾。","死生今有隔，相见永無因。"]', '诗', 'shi', '', NULL, '贈夫詩三首 一 孔氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad54997-3044-4f7a-9acb-9b4468036f02', '贈夫詩三首 二', '贈夫诗三首 二', 'b91bb430-9fee-4126-9305-087555bf9a47', '唐', '["匣裏殘妝粉，留將與後人。","黃泉無用處，恨作冢中塵。"]', '["匣裏殘妝粉，留將與後人。","黄泉無用处，恨作冢中塵。"]', '诗', 'shi', '', NULL, '贈夫詩三首 二 孔氏 shi');
